  ui_story_5036_50360101_33_dialog_content = "หา?",
  ui_story_5036_50360101_34_dialog_content = "คุณไม่รู้เกี่ยวกับยักษ์ใหญ่พเนจรใช่ไหม",
  ui_story_5036_50360101_35_dialog_content = "เกือบทุกคนรู้เรื่องนี้ ตั้งแต่ดินแดนทางเหนือไปจนถึงทะเลทรายเรดดีเซล จากลูโมโปลิสไปจนถึงอัมบราตัน",
  ui_story_5036_50360101_36_dialog_content = "แต่คุณไม่เคยได้ยินเรื่องนี้แม้ว่าจะเป็น Caelesite ก็ตาม?",
  ui_story_5036_50360101_37_dialog_content = "ฉันเดาว่านับเป็นข่าวด้วย!",
  ui_story_5036_50360101_38_dialog_content = "อืม มันมีศักยภาพในการพาดหัวข่าว ฉันควรจะจดบันทึกนี้!",
  ui_story_5036_50360101_39_dialog_content = "อะแฮ่ม. ช่วงนี้ฉัน... ยุ่งกับงานและสิ่งต่างๆ มากเกินกว่าจะตามทันเหตุการณ์ปัจจุบัน",
  ui_story_5036_50360101_40_dialog_content = "อย่าบอกนะว่ายังมีสำนักข่าวแพร่ข่าวลือเกี่ยวกับฉันอีก?",
  ui_story_5036_50360101_41_dialog_content = "เปล่าเลยนะ!",
  ui_story_5036_50360101_42_dialog_content = "ฟังนะ นี่คือบางส่วนจากเมื่อคืนนี้",
  ui_story_5036_50360101_43_dialog_content = "พิเศษ:",
  ui_story_5036_50360101_44_dialog_content = "ทำนายเส้นทางของยักษ์ใหญ่พเนจร",
  ui_story_5036_50360101_45_dialog_content = "มุ่งหน้าสู่ Umbraton ริมแม่น้ำโกลด์!",
  ui_story_5036_50360101_46_dialog_content = "ฉันจะอ่านให้พวกคุณฟัง!",
  ui_story_5036_50360101_47_dialog_content = "\"อัปเดตล่าสุด: ยักษ์ใหญ่พเนจรออกจากนอร์ธแลนด์แล้ว\"",
  ui_story_5036_50360101_48_dialog_content = "\"ขณะนี้นักวิทยาศาสตร์กำลังติดตามมัน และจากการคำนวณของพวกเขา...\"",
  ui_story_5036_50360101_49_dialog_content = "\"ยักษ์ใหญ่จะเดินทางต่อไปทางใต้สู่อัมบราตันตามแม่น้ำโกลด์\"",
  ui_story_5036_50360101_50_dialog_content = "\"ยักษ์ใหญ่ปรากฏตัวครั้งแรกอย่างกะทันหันบนท้องฟ้าเหนือ Northland และคิดว่ามาจาก Dark Zone\"",
  ui_story_5036_50360101_51_dialog_content = "\"หลังจากนักวิทยาศาสตร์นิรนามได้ยืนยันทฤษฎีนี้ ข่าวก็สั่นสะเทือนไปทั้งทวีป\"",
  ui_story_5036_50360101_52_dialog_content = "\"บางคนอ้างว่า Colossus ไม่มีเนวิเกเตอร์หรือผู้โดยสาร และไม่ได้พกอาวุธทำลายล้างใดๆ\"",
  ui_story_5036_50360101_53_dialog_content = "\"แต่ภายนอก โดยเฉพาะด้านล่าง ติดตั้งจอยักษ์และอุปกรณ์สเตอริโอที่ดูเหมือนมาจากสมัยโบราณ\"",
  ui_story_5036_50360101_54_dialog_content = "\"ขณะนี้ อิลลูมินาและลูโมโพลิสกำลังหาทางสกัดกั้นยักษ์ใหญ่พเนจร...\"",
  ui_story_5036_50360101_55_dialog_content = "\"... เพื่อตัดสินใจว่าพวกเขาจะดำเนินการกับสถานการณ์อย่างไร\"",
  ui_story_5036_50360101_56_dialog_content = "พเนจร... ยักษ์ใหญ่?",
  ui_story_5036_50360101_57_dialog_content = "ฉันมีคำถามมากมาย ฉันไม่รู้ด้วยซ้ำว่าจะเริ่มต้นจากตรงไหน",
  ui_story_5036_50360101_58_dialog_content = "ยักษ์ใหญ่ที่ติดตั้งหน้าจอและระบบสเตอริโอ?",
  ui_story_5036_50360101_59_dialog_content = "ฉันคิดว่าฉันเคยอ่านเรื่องนี้มาก่อนที่ไหนสักแห่ง!",
  ui_story_5036_50360101_60_dialog_content = "จริงหรือ คุณสามารถบอกอะไรฉันได้อีก",
  ui_story_5036_50360101_61_dialog_content = "ขอโทษ ฉันจำอะไรไม่ได้มากนัก",
  ui_story_5036_50360101_62_dialog_content = "แต่ดูแล้วไม่ผิดหวัง ฉันจะไปถามเจ้าหน้าที่กรอนรูเดี๋ยวนี้",
  ui_story_5036_50360101_63_dialog_content = "ฉันแน่ใจว่าเธอสามารถบอกเราได้มากขึ้นด้วยความรู้อันกว้างไกลของเธอเกี่ยวกับ Colossi!",
  ui_story_5036_50360101_64_dialog_content = "ไม่จำเป็นหรอก",
  ui_story_5036_50360101_65_dialog_content = "คาร์ลีน...? คุณกลับมาแล้ว!",
  ui_story_5036_50360101_66_dialog_content = "ฉันคิดว่าคุณจะอยู่ในลูโมโพลิสตลอดไป",
  ui_story_5036_50360101_67_dialog_content = "ฉันอ่านเกี่ยวกับยักษ์ใหญ่พเนจรในข่าวเมื่อไม่กี่วันก่อน และพบว่าสถานการณ์ทั้งหมดค่อนข้างแปลก ดังนั้นฉันจึงหมกมุ่นอยู่กับการค้นคว้าในห้องสมุด",
  ui_story_5036_50360101_68_dialog_content = "คุณต้องได้พบอะไรบางอย่าง!",
  ui_story_5036_50360101_69_dialog_content = "หรือท่านจะไม่รีบมาที่นี่...",
  ui_story_5036_50360101_70_dialog_content = "ใช่ ฉันพบอะไรบางอย่างเมื่อกว่าศตวรรษที่แล้ว",
  ui_story_5036_50360101_71_dialog_content = "กว่าศตวรรษ?",
  ui_story_5036_50360101_72_dialog_content = "ถูกตัอง. Caelestites เป็นพวกโดดเดี่ยวและไม่ได้ติดต่อกับ Aurorians มากนักในตอนนั้น",
  ui_story_5036_50360101_73_dialog_content = "แต่แล้ววันหนึ่งพวกเขาก็ขอความช่วยเหลือจากลูโมโปลิสและอิลลูมินา",
  ui_story_5036_50360101_74_dialog_content = "คำร้องขอความช่วยเหลือบ่งบอกเป็นนัยว่าพวกเขาขาดการติดต่อกับยักษ์ใหญ่ที่โทรมา <color=#FFB400>ยูโลโกซ</color>.",
  ui_story_5036_50360101_75_dialog_content = "Eulogoz มีคุณลักษณะที่โดดเด่นมาก—",
  ui_story_5036_50360101_76_dialog_content = "<color=#FFB400>มีหน้าจอภายนอกขนาดใหญ่</color>.",
