  ui_story_5036_50360101_124_dialog_content = "โว่ว!",
  ui_story_5036_50360101_125_dialog_content = "เรากำลังออกเดินทางจริงๆ!",
  ui_story_5036_50360101_126_dialog_content = "บรรณาธิการที่ตามรังควานฉันวันแล้ววันเล่าจะไม่มีทางจินตนาการถึงสิ่งนี้ได้ภายในหนึ่งล้านปี!",
  ui_story_5036_50360101_127_dialog_content = "ในบรรดานักข่าวที่พยายามหาโอกาสที่จะติดตามเรื่องราวของ Caelestite ในเมือง Umbraton ฉันเป็นคนเดียวที่บินเข้าไปใน Colossus ได้จริงๆ!",
  ui_story_5036_50360101_128_dialog_content = "ฉันจะแสดงให้เขาเห็นว่าใครเป็นนักข่าวที่ยอดเยี่ยมที่สุดในเมือง!",
  ui_story_5036_50360101_129_dialog_content = "เอ่อ บรั่นดี...?",
  ui_story_5036_50360101_130_dialog_content = "ไม่นะ ฉันไม่ควรเปิดเผยตัวเองต่อหน้าผู้ให้สัมภาษณ์!",
  ui_story_5036_50360101_131_dialog_content = "อะแฮ่ม. ขอให้ทุกท่านมั่นใจ ฉันเป็นมืออาชีพและจะทำงานของฉันด้วยความเที่ยงธรรมสูงสุด",
  ui_story_5036_50360101_132_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันหมายถึง",
  ui_story_5036_50360101_133_dialog_content = "คุณต้องการกลับไปที่ Umbraton หรือไม่? ฉันสามารถส่งคุณระหว่างทาง",
  ui_story_5036_50360101_134_dialog_content = "โอ้ ไม่เลย! ฉันยังสัมภาษณ์คุณไม่เสร็จด้วยซ้ำ",
  ui_story_5036_50360101_135_dialog_content = "ฉันขออนุญาตจากคุณในการเดินทางไปยัง Wandering Colossus ด้วย",
  ui_story_5036_50360101_136_dialog_content = "ฉันสัญญาว่าฉันจะเขียนบทความที่ยิ่งใหญ่และรุ่งโรจน์ที่สุดเกี่ยวกับคุณ!",
  ui_story_5036_50360101_137_dialog_content = "ผู้ที่อยู่ใน Lumopolis และ Illumina จะไม่คิดแม้แต่จะแตะต้องทรัพย์สินของ Caelestite หลังจากที่พวกเขาอ่านมัน!",
  ui_story_5036_50360101_138_dialog_content = "เอ่อ คือว่า... ดราม่าไปหน่อย ฮ่า...",
  ui_story_5036_50360101_139_dialog_content = "เฮ้ นั่นอะไรน่ะ?",
  ui_story_5036_50360101_140_dialog_content = "โปสเตอร์เพิ่งหลุดออกจากกระเป๋าคุณ บรั่นดี",
  ui_story_5036_50360101_141_dialog_content = "อะฮ่าฮ่าฮ่า ถูกต้อง! ขอบคุณ! ปล่อยวางทันที!",
  ui_story_5036_50360101_142_dialog_content = "เดี๋ยวนะ เราไม่รู้จักคนในโปสเตอร์คนนั้นเหรอ?",
  ui_story_5036_50360101_143_dialog_content = "ใช่ โกลดี้คนนั้นไม่ใช่เหรอ?",
  ui_story_5036_50360101_144_dialog_content = "หลังจาก \"Into the Haunted House\" ฉายรอบปฐมทัศน์ เราพบเธอครั้งหนึ่งที่บ้านผีสิง Andersen",
  ui_story_5036_50360101_145_dialog_content = "ภาพยนตร์เรื่องนี้ได้รับคำวิจารณ์ที่ดี แต่เธอตัดสินใจเลิกแสดง",
  ui_story_5036_50360101_146_dialog_content = "ฉันสงสัยว่าเธอทำอะไรเมื่อเร็ว ๆ นี้?",
  ui_story_5036_50360101_147_dialog_content = "ฉันรู้สึกว่าเธอได้รับความนิยมใน Umbraton ตั้งแต่ช่วงปลายๆ ฉันเห็นโปสเตอร์ของเธอทุกที่ที่ฉันไป",
  ui_story_5036_50360101_148_dialog_content = "ที่ฉันมีนี้จะแตกต่างจากบนถนน",
  ui_story_5036_50360101_149_dialog_content = "ตัวนี้เป็นของสะสมจำนวนจำกัด!",
  ui_story_5036_50360101_150_dialog_content = "คุณเป็นแฟนของเธอ?",
  ui_story_5036_50360101_151_dialog_content = "ฉันจะไม่เรียกตัวเองว่า Goldilock จริงๆ ...",
  ui_story_5036_50360101_152_dialog_content = "โกลดิล็อก?",
  ui_story_5036_50360101_153_dialog_content = "นั่นคือสิ่งที่แฟน ๆ ของ Goldie เรียกว่า ฉันไม่ใช่หนึ่งในนั้นจริงๆ!",
  ui_story_5036_50360101_154_dialog_content = "ฉันเพิ่งสัมภาษณ์โกลดี้หลังจาก \"Into the Haunted House\" ฉายรอบปฐมทัศน์",
  ui_story_5036_50360101_155_dialog_content = "ฉันพบว่าเธอเป็นคนมองโลกในแง่ดีและใจดีมาก ราวกับสายลมอุ่นๆ",
  ui_story_5036_50360101_156_dialog_content = "ไม่อย่างนั้น ฉันคงอยู่ได้ไม่นานเหมือนตอนฝึกงานที่ The Daily Scoop",
  ui_story_5036_50360101_157_dialog_content = "หลังจากนั้นผมก็ติดตามผลงานเธอเป็นระยะๆ ก็แค่นั้น",
