  ui_story_5036_50360101_159_dialog_content = "D-งั้นเหรอ? แต่ฉันได้ยินผ่านต้นองุ่นว่าโกลดี้มีแนวโน้มรุนแรง",
  ui_story_5036_50360101_160_dialog_content = "เป็นความจริงที่บุคคลสาธารณะหลายคนมีด้านที่ไม่มีใครรู้",
