  ui_story_5036_50360101_163_dialog_content = "เมื่อเร็ว ๆ นี้มีข่าวลือที่ไร้สาระมากมาย และนั่นอาจเป็นหนึ่งในนั้น",
  ui_story_5036_50360101_164_dialog_content = "หนังสือพิมพ์ Umbraton น่าจะเป็นภาพ PlayerName ราวกับสัตว์ประหลาดสามหัวอาถรรพ์ในตอนนี้",
