  ui_story_5036_50360101_170_dialog_content = "เอ็ม-มี? โอ้โฮ ฮิฮิฮิ...",
  ui_story_5036_50360101_171_dialog_content = "<color=#e8d9bb>คำเตือน: ตรวจพบวัตถุบินที่ไม่ปรากฏชื่ออยู่ข้างหน้า</color>",
