  ui_story_5036_50360201_1_dialog_content = "<color=#e8d9bb>ความสนใจ กำลังเข้าใกล้วัตถุบินที่ไม่ปรากฏชื่อ</color>",
  ui_story_5036_50360201_2_dialog_content = "ยักษ์ใหญ่สั่นมาก! เราปะทะกับยักษ์ใหญ่พเนจรหรือไม่?",
