  ui_story_5036_50360201_10_dialog_content = "ไม่ใช่ทุกคนที่มีสิทธิ์เป็นเจ้าของอุปกรณ์ขั้นสูงเช่นกล้องถ่ายรูป",
  ui_story_5036_50360201_11_dialog_content = "ไม่ต้องพูดถึงว่าฉันอัปเดตส่วนต่างๆ อยู่เสมอเพื่อให้ฉันถ่ายภาพได้ดีขึ้น",
  ui_story_5036_50360201_12_dialog_content = "ฉันได้รับการว่าจ้างให้เป็นนักศึกษาฝึกงานด้วยกล้องนี้",
