  ui_story_5036_50360201_14_dialog_content = "ฉันไม่สามารถสัญญาได้ แต่ฉันสามารถรับประกันได้ว่ามันจะจับภาพที่เหมือนจริงและสมจริงที่สุด!",
  ui_story_5036_50360201_15_dialog_content = "<color=#e8d9bb>มีการปรับแต่งเพื่อให้ความเร็วและทิศทางสอดคล้องกับวัตถุที่ไม่ปรากฏชื่อ</color>",
