  ui_story_5036_50360401_99_dialog_content = "ไม่สนใจผู้หญิงที่ส่งเสียงดัง ฉัน บาร์บาร่า เกิดมาเพื่อเป็นไอดอลอย่างแท้จริง!",
  ui_story_5036_50360401_100_dialog_content = "ฮ่า บางทีคุณควรแน่ใจว่าคุณสามารถตีโน้ตได้ก่อนที่จะขึ้นเวที!",
  ui_story_5036_50360401_101_dialog_content = "ทำไมคุณไม่ใช้เวลาน้อยลงในการวิจารณ์ฉันและใช้เวลามากขึ้นในการเรียนรู้ที่จะร้องเพลงจริง ๆ แทนล่ะ",
