  ui_story_5036_50360401_103_dialog_content = "ฉันไม่อยากจะเชื่อเลย",
  ui_story_5036_50360401_104_dialog_content = "Rediesel Wrench ลงเอยกับคนที่มีรสนิยมทางดนตรีอย่างคุณได้อย่างไร",
