  ui_story_5036_50360401_132_dialog_content = "น่าเสียดายจริง ๆ",
  ui_story_5036_50360401_133_dialog_content = "จนถึงขณะนี้ยังไม่มีผู้เข้าแข่งขันรายใดที่สามารถเข้าร่วมคอนเสิร์ตได้นอกจากสองคนแรกของเรา",
  ui_story_5036_50360401_134_dialog_content = "ตอนนี้ขอต้อนรับผู้เข้าร่วมคนสุดท้ายของวันนี้",
  ui_story_5036_50360401_135_dialog_content = "เขามีผลงานอะไรให้เราบ้าง?",
  ui_story_5036_50360401_136_dialog_content = "สวัสดี ทุกคน",
  ui_story_5036_50360401_137_dialog_content = "ฉันคือวิค ฉันเป็นผู้ฝึกสัตว์มหัศจรรย์",
