  ui_story_5036_50360401_139_dialog_content = "PlayerName?",
  ui_story_5036_50360401_140_dialog_content = "ฉันไม่ได้คาดหวังว่าจะได้เห็นใบหน้าที่คุ้นเคยในคณะกรรมการคัดเลือก",
  ui_story_5036_50360401_141_dialog_content = "ต้องขอชี้แจงว่าไม่ทราบจริงๆ PlayerName กำลังจะได้เป็นผู้พิพากษา",
  ui_story_5036_50360401_142_dialog_content = "เป็นคุณจริงๆ!",
  ui_story_5036_50360401_143_dialog_content = "ฉันคิดว่าฉันคิดผิด... ทำไมคุณถึงลงทะเบียนสำหรับสิ่งนี้?",
  ui_story_5036_50360401_144_dialog_content = "เพราะฉันอยากเป็นไอดอลและแสดงบนเวทีที่ไม่เหมือนใครนี้",
  ui_story_5036_50360401_145_dialog_content = "ฉันไม่เคยรู้ว่าคุณอยากเป็นไอดอล",
  ui_story_5036_50360401_146_dialog_content = "จากที่ฉันรู้ คุณสร้างชื่อให้ตัวเองแล้วในโลกของการฝึกฝนสัตว์มหัศจรรย์",
  ui_story_5036_50360401_147_dialog_content = "ใครว่านักสัตววิทยาเป็นไอดอลไม่ได้?",
  ui_story_5036_50360401_148_dialog_content = "ฉันเท่านั้นที่จะตัดสินใจได้!",
  ui_story_5036_50360401_149_dialog_content = "ในยุคนี้ ใครๆ ก็สามารถเป็นไอดอลได้...",
  ui_story_5036_50360401_150_dialog_content = "และเพลิดเพลินไปกับ 15 นาทีแห่งชื่อเสียงในสปอตไลต์",
  ui_story_5036_50360401_151_dialog_content = "“ในยุคนี้ใคร ๆ ก็สามารถเป็นไอดอลได้” คุณว่าไหม?",
  ui_story_5036_50360401_152_dialog_content = "ใส่ดีมาก!",
  ui_story_5036_50360401_153_dialog_content = "ฉันขอขอบคุณสำหรับทัศนคติและความเข้าใจของคุณเกี่ยวกับธุรกิจนี้ ฉันหวังว่าจะได้แสดงของคุณ!",
  ui_story_5036_50360401_154_dialog_content = "ว้าว นี่คือผู้เข้าแข่งขันคนแรกจนถึงขณะนี้ที่ดึงดูดความสนใจของ Miss Goldie ด้วยตัวเอง!",
  ui_story_5036_50360401_155_dialog_content = "เขาจะนำการแสดงที่น่าตื่นเต้นอะไรมาให้เรา?",
  ui_story_5036_50360401_156_dialog_content = "เริ่มเลย วิค!",
  ui_story_5036_50360401_157_dialog_content = "ฉันจะท่องบางอย่างสำหรับคุณทั้งหมด อะแฮ่ม...",
  ui_story_5036_50360401_158_dialog_content = "อา! ฤดูใบไม้ผลิมาถึงแล้ว และโลกก็กลับมามีชีวิตชีวาอีกครั้ง!",
  ui_story_5036_50360401_159_dialog_content = "เป็นฤดูกาลอีกครั้งที่สัตว์ร้ายแสดงพลัง",
  ui_story_5036_50360401_160_dialog_content = "(ฉันไม่แน่ใจด้วยซ้ำว่าสิ่งนี้มีคุณสมบัติเป็นการแสดง ...)",
  ui_story_5036_50360401_161_dialog_content = "(แต่ดูเหมือนว่าวิคกำลังท่อง Encyclopedia Exotica อยู่นะ?!)",
  ui_story_5036_50360401_162_dialog_content = "อนิจจา ความรุ่งโรจน์แห่งชีวิตมีอยู่ทุกตารางนิ้วของผืนดิน ไม่ว่าจะเป็นป่าหรือที่ราบ!",
  ui_story_5036_50360401_163_dialog_content = "แต่ท่ามกลางเสียงขรมนี้มีสิ่งมีชีวิตหนึ่งที่เป็นข้อยกเว้น",
  ui_story_5036_50360401_164_dialog_content = "เดอะ <color=#FFB400>โอโรโบรอส</color> คือหนึ่งใน <color=#FFB400> อายุยืนที่สุด </color> สัตว์มหัศจรรย์ใน Astra",
  ui_story_5036_50360401_165_dialog_content = "เมื่อพวกเขาโตเต็มที่—",
  ui_story_5036_50360401_166_dialog_content = "ขออภัย ขอขัดจังหวะสักครู่!",
  ui_story_5036_50360401_167_dialog_content = "กรรมการกำลังสงสัยว่าคุณมีอะไรจะโชว์ให้เราดูอีกไหม?",
  ui_story_5036_50360401_168_dialog_content = "เปล่าเลย... ฉันแค่เตรียมบทบรรยายสำหรับวันนี้เท่านั้น",
  ui_story_5036_50360401_169_dialog_content = "เห็นแล้ว...เสียดายจัง",
  ui_story_5036_50360401_170_dialog_content = "คุณทำได้ดีในการบรรยายของคุณ แต่มันไม่ใช่สิ่งที่เรากำลังมองหา",
  ui_story_5036_50360401_171_dialog_content = "แต่อย่าดูถูกตัวเอง!",
  ui_story_5036_50360401_172_dialog_content = "คุณมีเสียงที่ดีมากและภาพก็ดีมากเช่นกัน",
  ui_story_5036_50360401_173_dialog_content = "ฉันแน่ใจว่าคุณจะเปลี่ยนไปร้องเพลงหรือเต้นได้ดี",
