  ui_story_5036_50360401_175_dialog_content = "ฉันหวังว่าจะเห็นความแตกต่างจากคุณในรอบต่อไป",
  ui_story_5036_50360401_176_dialog_content = "ฉันคิดว่าคุณมีศักยภาพที่ดี พยายามต่อไป!",
  ui_story_5036_50360401_177_dialog_content = "อา ฉันคิดว่าฉันจะลองอีกครั้ง",
  ui_story_5036_50360401_178_dialog_content = "(โกลดี้มองวิกราวกับว่าเธอเพิ่งค้นพบอัญมณีที่ซ่อนอยู่...)",
  ui_story_5036_50360401_179_dialog_content = "(วิคมีคุณสมบัติในการเป็นไอดอลจริงๆ เหรอ?)",
  ui_story_5036_50360401_180_dialog_content = "ขอขอบคุณผู้สมัครและผู้ตัดสินของเราทุกคน! การออดิชั่นของวันนี้สิ้นสุดลงแล้ว",
