  ui_story_5036_50360401_182_dialog_content = "เราจะพบคุณในวันพรุ่งนี้!",
  ui_story_5036_50360401_183_dialog_content = "PlayerNameโกลดี้ มันจบแล้วเหรอ?",
  ui_story_5036_50360401_184_dialog_content = "ใช่. ฉันคิดว่าการดูการแสดงจะผ่อนคลาย แต่จริงๆ แล้วฉันเอาอะไรไปหลายอย่าง",
  ui_story_5036_50360401_185_dialog_content = "ยังไงก็ตาม ทำไมพวกคุณไม่ปรากฏตัวล่ะ?",
  ui_story_5036_50360401_186_dialog_content = "เราต้องการซักซ้อมเพิ่มเติมก่อนที่จะเข้าร่วม",
  ui_story_5036_50360401_187_dialog_content = "ซ้อมด้วยกันมั้ย?",
  ui_story_5036_50360401_188_dialog_content = "ใช่. เราคิดว่าน่าจะสนุกกว่าถ้าเข้าร่วมเป็นคู่",
  ui_story_5036_50360401_189_dialog_content = "ดูไม่ตกใจเท่าไหร่ คุณได้ยินถูกต้องแล้ว",
  ui_story_5036_50360401_190_dialog_content = "Vice และฉันจะแสดงเป็นคู่",
  ui_story_5036_50360401_191_dialog_content = "เป็นความคิดที่ดีมาก!",
  ui_story_5036_50360401_192_dialog_content = "คุณมีความคิดว่าคุณจะทำอะไรหรือยัง?",
  ui_story_5036_50360401_193_dialog_content = "เราจะร้องเพลง เรามีเพลงบางเพลงที่คัดออกมาแล้ว",
  ui_story_5036_50360401_194_dialog_content = "แต่เราต้องซ้อมก่อนตัดสินใจว่าจะไปกับใคร",
  ui_story_5036_50360401_195_dialog_content = "จริง ๆ ไม่รู้จะทำได้หรือเปล่า...",
