  ui_story_5036_50360401_198_dialog_content = "คุณต้องมีเพลงของคุณเองให้เลือกมากมายใช่ไหม?",
  ui_story_5036_50360401_199_dialog_content = "ใช่ แต่ฉันไม่รู้สึกว่ามีใครเหมาะกับเวทีบน Eulogoz",
  ui_story_5036_50360401_200_dialog_content = "ไม่เป็นไรแม้ว่า บางทีฉันอาจจะคิดออกในอีกสองสามวันข้างหน้า",
  ui_story_5036_50360401_201_dialog_content = "คุณหมายถึงคุณกำลังเขียนเพลงใหม่สำหรับ Eulogoz ใช่ไหม",
