  ui_story_5036_50360401_203_dialog_content = "ฉันไม่แน่ใจว่าจะทำได้ไหม ดังนั้นโปรดเก็บเป็นความลับ",
  ui_story_5036_50360401_204_dialog_content = "คุณเขียนเพลงทั้งหมดของคุณหรือไม่?",
  ui_story_5036_50360401_205_dialog_content = "เยี่ยมสุด ๆ ไปเลย!",
  ui_story_5036_50360401_206_dialog_content = "ไม่ใช่ทั้งหมด ไม่ใช่",
  ui_story_5036_50360401_207_dialog_content = "เป็นเพียงทำนองหรือจังหวะที่ผุดขึ้นมาในความคิดของฉันเป็นครั้งคราว",
  ui_story_5036_50360401_208_dialog_content = "ก็เลยลองเอามาเขียนเป็นเพลงดู",
  ui_story_5036_50360401_209_dialog_content = "แต่มันไม่ใช่ทุกครั้งที่ฉันได้เมโลดี้ที่ต้องการ",
