  ui_story_5036_50360401_211_dialog_content = "♪ อู-อู-อู-อู... ♪",
  ui_story_5036_50360401_212_dialog_content = "♪ ลา ลา ลา ลา... ♪",
  ui_story_5036_50360401_213_dialog_content = "เอ่อ ตั้งแต่ฉันเข้าใกล้ยูโลโกซ ฉันก็ได้ยินเสียงเพลงแว่วเข้ามาในหัว",
