  ui_story_5036_50360401_215_dialog_content = "จริงเหรอ",
  ui_story_5036_50360401_216_dialog_content = "ฉันได้ยินมาว่าชาวคาเลสเป็นเผ่าพันธุ์ที่รักในเสียงดนตรี",
  ui_story_5036_50360401_217_dialog_content = "บางทีคุณอาจมีความใกล้ชิดกับการทำดนตรีโดยธรรมชาติ!",
