  ui_story_5036_50360401_220_dialog_content = "เป็นไปได้นะ!",
  ui_story_5036_50360401_221_dialog_content = "มันสมเหตุสมผล",
  ui_story_5036_50360401_222_dialog_content = "Eulogoz เป็นของชาว Caelestites",
