  ui_story_5036_50360502_37_dialog_content = "แย่เกินไปที่ perp หมดก่อนที่ฉันจะยกมันได้",
  ui_story_5036_50360502_38_dialog_content = "ดูสิ ปันส่วนครึ่งหนึ่ง",
  ui_story_5036_50360502_39_dialog_content = "เป็นบรรจุภัณฑ์ของอิลลูมินา",
  ui_story_5036_50360502_40_dialog_content = "ปันส่วนอิลลูมินา?",
  ui_story_5036_50360502_41_dialog_content = "แต่ไม่มีทหารของอิลลูมินาคนใดได้รับมอบหมายให้ทำงานใกล้เวที",
  ui_story_5036_50360502_42_dialog_content = "ใช่. คนที่อยู่รอบตัวฉันล้วนมีสิ่งเดียวกันเกิดขึ้นกับพวกเขา",
  ui_story_5036_50360502_43_dialog_content = "ปันส่วนของเราหายไปอย่างลึกลับ",
  ui_story_5036_50360502_44_dialog_content = "หรือว่าจะเป็น...",
  ui_story_5036_50360502_45_dialog_content = "<color=#e8d9bb>ฟิ้วว—</color>",
  ui_story_5036_50360502_46_dialog_content = "นั่นคือหนู?",
  ui_story_5036_50360502_47_dialog_content = "ไม่! ไม่ใช่หนู",
  ui_story_5036_50360502_48_dialog_content = "คุณเห็นสิ่งนั้นวิ่งหนี Marshmallow?",
  ui_story_5036_50360502_49_dialog_content = "ตามไป!",
  ui_story_5036_50360502_50_dialog_content = "โฮ่ง โฮ่ง!",
  ui_story_5036_50360502_51_dialog_content = "ไฮ!",
  ui_story_5036_50360502_52_dialog_content = "ไฮ~",
  ui_story_5036_50360502_53_dialog_content = "อย่าจับมัน Marshmallow เพียงติดตามอย่างใกล้ชิดในตอนนี้",
  ui_story_5036_50360502_54_dialog_content = "บางทีมันอาจจะทำให้เรา <color=#FFB400>ปลาที่ใหญ่กว่า</color>.",
  ui_story_5036_50360502_55_dialog_content = "ไฮ—!",
  ui_story_5036_50360502_56_dialog_content = "ฮะ? เฮ้อ...",
  ui_story_5036_50360502_57_dialog_content = "เมื่อนาทีที่แล้วคุณไม่สนใจฉันเลย บิก้า...",
  ui_story_5036_50360502_58_dialog_content = "ตอนนี้คุณต้องการที่จะกอด?",
  ui_story_5036_50360502_59_dialog_content = "โฮ่ง!",
  ui_story_5036_50360502_60_dialog_content = "อะแฮ่ม. พูดว่า คุณไม่ควรจูงหมาอ้วนๆ ของคุณใช่ไหม",
  ui_story_5036_50360502_61_dialog_content = "Bica ของฉันอ่อนไหวมากและประหม่าง่าย ซึ่งจะทำให้ท้องไส้ปั่นป่วน—",
  ui_story_5036_50360502_62_dialog_content = "คุณเป็นโจรผี?",
  ui_story_5036_50360502_63_dialog_content = "ผี? ไม่มีทาง.",
  ui_story_5036_50360502_64_dialog_content = "ไม่เชื่อฉัน? ฉันจะกัดฟันพิสูจน์เอง โอ๊ย",
  ui_story_5036_50360502_65_dialog_content = "ผู้ชายคนนั้นเจ็บจริงๆ!",
  ui_story_5036_50360502_66_dialog_content = "เห็นไหมว่าฉันมีชีวิตอยู่ได้ ฉันรู้สึกเจ็บปวด ผีไม่ได้",
  ui_story_5036_50360502_67_dialog_content = "(มันเป็นเรื่องน่าเบื่อที่จะพูดคุยกับผู้ชายคนนี้)",
  ui_story_5036_50360502_68_dialog_content = "(แต่ทำไมเขาฟังดูคุ้นเคย?)",
  ui_story_5036_50360502_69_dialog_content = "ฉันไม่สนหรอกว่าเธอจะเป็นผีหรือไม่ แต่ฉันจะไม่ทนให้ใครมาทำลายคอนเสิร์ตของฉัน!",
  ui_story_5036_50360502_70_dialog_content = "คุณควรเริ่มอธิบายตัวเองดีกว่า!",
  ui_story_5036_50360502_71_dialog_content = "<color=#e8d9bb>ติ๊ง!</color>",
  ui_story_5036_50360502_72_dialog_content = "ของในมือนี้ไม่ใช่แค่ไม้ประดับ!",
  ui_story_5036_50360502_73_dialog_content = "ตกลงตกลง...",
  ui_story_5036_50360502_74_dialog_content = "ใจเย็นๆ! ฉันเกือบจะสะดุดเพราะคำขู่ของคุณ",
  ui_story_5036_50360502_75_dialog_content = "ชุดของคุณดูเป็นก้อน คุณซ่อนอะไรอยู่ใต้นั้น?",
  ui_story_5036_50360502_76_dialog_content = "เป็นเพียงทารกที่มีค่าที่ฉันเพิ่งเลี้ยงให้เชื่อง ตอนนี้กำลังพักผ่อนอยู่",
  ui_story_5036_50360502_77_dialog_content = "ทำไมฉันไม่เชื่อเลยสักนิด",
  ui_story_5036_50360502_78_dialog_content = "ถอนหายใจ ฉันบอกได้แค่ว่าคุณขาดความเข้าใจ",
  ui_story_5036_50360502_79_dialog_content = "อ่านหนังสือมากขึ้น ดูหนังสือพิมพ์มากขึ้น ทำงานการกุศลมากขึ้น... นั่นคือคำแนะนำทั้งหมดที่ฉันสามารถให้คุณได้",
  ui_story_5036_50360502_80_dialog_content = "ถ้าไม่มีอะไรแล้ว ฉันไปก่อนนะ",
  ui_story_5036_50360502_81_dialog_content = "ถอดเสื้อผ้าออก!",
  ui_story_5036_50360502_82_dialog_content = "หะ?! อาจจะมืดมองไม่เห็นอะไรเลย...",
  ui_story_5036_50360502_83_dialog_content = "แต่ฉันยังมีความสุภาพเรียบร้อยที่จะปกป้อง!",
  ui_story_5036_50360502_84_dialog_content = "รับเขา Marshmallow!",
  ui_story_5036_50360502_85_dialog_content = "โฮ่ง!",
  ui_story_5036_50360502_86_dialog_content = "ดูมัน...!",
  ui_story_5036_50360502_87_dialog_content = "<color=#e8d9bb>แผละ!</color>",
  ui_story_5036_50360502_88_dialog_content = "ยังไงก็ตกอยู่ดี...",
  ui_story_5036_50360502_89_dialog_content = "เฮ้ เขาเป็นหนึ่งในนักแสดงในการออดิชั่นไม่ใช่เหรอ?",
  ui_story_5036_50360502_90_dialog_content = "นั่นคือข้ออ้างที่คุณใช้ในการแอบขึ้นเครื่อง",
  ui_story_5036_50360502_91_dialog_content = "อุ๊ย อุ๊ย อุ๊ย...",
  ui_story_5036_50360502_92_dialog_content = "เขาเนี่ยนะ?!",
  ui_story_5036_50360502_93_dialog_content = "แกว๊ก แกว๊ก!",
  ui_story_5036_50360502_94_dialog_content = "อะไรนะ...? นกฮูกเพิ่งสะดุดออกจากแขนของเขาหรือไม่?",
  ui_story_5036_50360502_95_dialog_content = "ไม่ใช่ของที่ขโมยมา? ฉันหวาดระแวงเกินไปหรือเปล่า",
  ui_story_5036_50360502_96_dialog_content = "ฉันบอกคุณว่าฉันบริสุทธิ์",
  ui_story_5036_50360502_97_dialog_content = "<color=#e8d9bb>*สาด* กริ๊ง กริ๊ง...</color>",
  ui_story_5036_50360502_98_dialog_content = "เครื่องประดับจำนวนมากหลุดออกมาจากภายในขนของนกฮูก",
  ui_story_5036_50360502_99_dialog_content = "ฉันบอกแล้วไงว่าฉันไม่ใช่ขโมย",
  ui_story_5036_50360502_100_dialog_content = "โอ ลูทูมิ เธอเป็นอะไรก็ได้! ทำไมคุณถึงเป็นขโมย?",
  ui_story_5036_50360502_101_dialog_content = "คู..",
  ui_story_5036_50360502_102_dialog_content = "คุณยังปฏิเสธได้อย่างไร หลักฐานกระจัดกระจายรอบตัวเราอย่างแท้จริง!",
  ui_story_5036_50360502_103_dialog_content = "ผ่อนคลาย!",
  ui_story_5036_50360502_104_dialog_content = "ฉันจะไม่แสดงความเมตตาต่อคุณ!",
  ui_story_5036_50360502_105_dialog_content = "โอย...",
  ui_story_5036_50360502_106_dialog_content = "มิสโกลดี้?!",
  ui_story_5036_50360502_107_dialog_content = "ไม่ต้องกังวล เขาแค่สลบไปชั่วคราว",
  ui_story_5036_50360502_108_dialog_content = "เขามีลิ้นสีเงิน และพวกเราต่างก็ไม่มีเวลาหรือพลังงานที่จะจัดการกับมันในตอนนี้",
  ui_story_5036_50360502_109_dialog_content = "โปรดจับเขาไว้และสอบปากคำเขาเมื่อคุณทำงานเสร็จแล้ว",
  ui_story_5036_50360502_110_dialog_content = "<color=#e8d9bb>เปรี๊ยะ!</color>",
  ui_story_5036_50360502_111_dialog_content = "เอาละ...",
  ui_story_5036_50360502_112_dialog_content = "ข่าวลือเกี่ยวกับค่าเฉลี่ยสตรีคของโกลดี้เป็นความจริงหรือไม่?",
  ui_story_5036_50360502_113_dialog_content = "ด้วยภาพนี้ ผมจะสามารถ...",
  ui_story_5036_50360601_1_dialog_content = "หา?",
  ui_story_5036_50360601_2_dialog_content = "ฉันเข้าใจแล้ว! สกู๊ปข่าววงในที่รับประกันยอดวิว!",
  ui_story_5036_50360601_3_dialog_content = "คุณอย่ามาเสียเวลากับฉันดีกว่า",
  ui_story_5036_50360601_4_dialog_content = "ฉันสัญญาว่าคุณจะมีความสุขกับสิ่งที่ฉันมี!",
  ui_story_5036_50360601_5_dialog_content = "จำได้ไหมว่าเมื่อคุณได้รับคำแนะนำเกี่ยวกับโกลดี้ที่มีพฤติกรรมแย่ๆ",
  ui_story_5036_50360601_6_dialog_content = "(ฉันอยู่ที่ไหนเนี่ย)",
  ui_story_5036_50360601_7_dialog_content = "(ฉันกลับไปที่ Eraveil เมื่อไหร่ ครั้งสุดท้ายที่ฉันจำได้คือฉัน...)",
  ui_story_5036_50360601_8_dialog_content = "(ฉันอยู่ที่ไหนอีกครั้ง?)",
  ui_story_5036_50360601_9_dialog_content = "♪ ลา... ลา ลา ลา... ♪",
  ui_story_5036_50360601_10_dialog_content = "(ฉันรู้จักเพลงนั้น!)",
  ui_story_5036_50360601_11_dialog_content = "♪ อู-อู-อู-อู... ♪",
  ui_story_5036_50360601_12_dialog_content = "(ใครฮัมเพลง?)",
  ui_story_5036_50360601_13_dialog_content = "<color=#e8d9bb>ฟิ้วววว!</color>",
  ui_story_5036_50360601_14_dialog_content = "(อะไรที่เพิ่งบินไป ยักษ์ใหญ่?)",
  ui_story_5036_50360601_15_dialog_content = "(ฉันควรจะค้นหา.)",
  ui_story_5036_50360601_16_dialog_content = "♪ ลา ลา ลา ลา... ♪",
  ui_story_5036_50360601_17_dialog_content = "♪ อู-อู-อู-อู... ♪",
  ui_story_5036_50360601_18_dialog_content = "♪ ลา... ลา ลา... ♪",
  ui_story_5036_50360601_19_dialog_content = "(ผู้หญิงตรงนั้น เธอคือคนที่กำลังร้องเพลงอยู่)",
  ui_story_5036_50360601_20_dialog_content = "อยู่นี่เอง",
  ui_story_5036_50360601_21_dialog_content = "(เธอกำลังคุยกับฉัน?)",
  ui_story_5036_50360601_22_dialog_content = "ครี ครี!",
  ui_story_5036_50360601_23_dialog_content = "(โอ้ เธอกำลังคุยกับสิ่งมีชีวิตที่ดูเหมือนยักษ์ใหญ่)",
  ui_story_5036_50360601_24_dialog_content = "นี่ฟังฉันร้องเพลงเหรอ? คุณเป็นแฟนตัวยง!",
  ui_story_5036_50360601_25_dialog_content = "แต่ฉันคิดว่าถึงเวลาแล้วที่จะใส่คำลงในเพลง",
  ui_story_5036_50360601_26_dialog_content = "(การแต่งตัวและการแสดงของเธอ... เธอเป็นชาวคาเลสไทต์อย่างแน่นอน)",
  ui_story_5036_50360601_27_dialog_content = "(ฉันรู้ว่าฉันจะพบ Caelestites คนอื่น!)",
  ui_story_5036_50360601_28_dialog_content = "อืม ฉันหิวน้ำนิดหน่อย",
  ui_story_5036_50360601_29_dialog_content = "ไปเก็บผลไม้ป่ากันเถอะ!",
  ui_story_5036_50360601_30_dialog_content = "ครี ครี!",
  ui_story_5036_50360601_31_dialog_content = "เฮ้สาวน้อย!",
  ui_story_5036_50360601_32_dialog_content = "รอก่อน!",
  ui_story_5036_50360601_33_dialog_content = "หา?",
  ui_story_5036_50360601_34_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก!</color>",
  ui_story_5036_50360601_35_dialog_content = "สาวน้อย!",
  ui_story_5036_50360601_36_dialog_content = "หา?",
  ui_story_5036_50360601_37_dialog_content = "โอ้ มันเป็นแค่ความฝัน...",
  ui_story_5036_50360601_38_dialog_content = "<color=#e8d9bb>สี่วันก่อนคอนเสิร์ต</color>",
  ui_story_5036_50360601_39_dialog_content = "<color=#e8d9bb>ปอนด์ ปอนด์ ปอนด์!</color>",
  ui_story_5036_50360601_40_dialog_content = "คุณสบายดีไหมในนั้น PlayerName?",
  ui_story_5036_50360601_41_dialog_content = "กำลังไปน่า!",
  ui_story_5036_50360601_42_dialog_content = "คุณหลับเป็นตาย!",
  ui_story_5036_50360601_43_dialog_content = "คุณไม่ได้ยินเราทุบประตูเหรอ?",
  ui_story_5036_50360601_44_dialog_content = "เราเริ่มคิดว่า Eclipsites แอบเข้ามาในห้องของคุณ...",
  ui_story_5036_50360601_45_dialog_content = "ผมกับไวซ์ใกล้จะพังประตูเข้าไปแล้ว",
  ui_story_5036_50360601_46_dialog_content = "ขอโทษ ฉันเพิ่งฝันไป มันรู้สึกเหมือนฉันยังคงอยู่ในนั้น",
  ui_story_5036_50360601_47_dialog_content = "อา ฝันอีกแล้ว",
  ui_story_5036_50360601_48_dialog_content = "อื่น?",
  ui_story_5036_50360601_49_dialog_content = "ใช่. ลืมแล้วเหรอ คาร์ลีน?",
  ui_story_5036_50360601_50_dialog_content = "PlayerName มักจะฝันแปลกๆ",
  ui_story_5036_50360601_51_dialog_content = "ทันใดนั้นฉันก็จำได้ว่าฉันฝันแปลก ๆ เมื่อเช้านี้ด้วย",
  ui_story_5036_50360601_52_dialog_content = "ฉันคิดว่าฉันฝันถึง Eraveil",
  ui_story_5036_50360601_53_dialog_content = "ยกเว้นคนที่อาศัยอยู่ที่นั่นไม่ใช่ PlayerNameแต่เป็นเด็กผู้หญิงตัวเล็ก ๆ ที่ฉันไม่เคยเห็นมาก่อน",
  ui_story_5036_50360601_54_dialog_content = "ฉันด้วย! ฉันมีความฝันแบบเดียวกัน!",
  ui_story_5036_50360601_55_dialog_content = "ว้าว ช่วงนี้เคมีเข้ากันสุดๆ",
  ui_story_5036_50360601_56_dialog_content = "มันต้องเป็นการซ้อมทั้งหมดนั่นแหละ!",
  ui_story_5036_50360601_57_dialog_content = "แต่ฉันฝันในสิ่งเดียวกัน",
  ui_story_5036_50360601_58_dialog_content = "ว่าไง",
  ui_story_5036_50360601_59_dialog_content = "ฉันเห็นเด็กหญิงตัวเล็ก ๆ ร้องเพลงใน Eraveil",
  ui_story_5036_50360601_60_dialog_content = "เพลงของเธอเป็นเพลงที่ติดอยู่ในหัวของฉัน!",
  ui_story_5036_50360601_61_dialog_content = "ผู้หญิงในฝันของฉันไม่ได้ร้องเพลง เธอแค่กำลังจัดบ้านของเธอ",
  ui_story_5036_50360601_62_dialog_content = "ผู้หญิงที่ฉันฝันถึงกำลังอ่านหนังสืออยู่ในห้อง",
  ui_story_5036_50360601_63_dialog_content = "ดังนั้นความฝันของเราจึงแตกต่างกันเล็กน้อย",
  ui_story_5036_50360601_64_dialog_content = "ฉันได้ยินมาว่าเมื่อหลายคนประสบกับสิ่งเดียวกัน มีโอกาสที่พวกเขาจะจบลงด้วยความฝันที่คล้ายกัน",
  ui_story_5036_50360601_65_dialog_content = "เนื่องจากประสบการณ์ร่วมกันของพวกเขา จิตใต้สำนึกของพวกเขาจึงมุ่งไปยังความคิดเดียวกัน ส่งผลให้เกิดความฝันที่คล้ายกัน",
  ui_story_5036_50360601_66_dialog_content = "ในเวลากลางคืนคนหนึ่งฝันถึงสิ่งที่ไตร่ตรองในตอนกลางวัน ดังคำกล่าวที่ว่า",
