  ui_story_5036_50360602_89_dialog_content = "ฉันเพิ่งค้นพบว่าสายเลือดของฉันดูเหมือนจะเชื่อมโยงกับโอโรโบรอส เพราะฉะนั้นต้องหาให้เจอ!",
