  ui_story_5036_50360802_53_dialog_content = "<size=45>คะแนนเอกฉันท์!</size>",
  ui_story_5036_50360802_54_dialog_content = "อย่างจริงจัง? แม้แต่มือใหม่ก็ยังทำได้ ความกดดันเกิดขึ้นกับบางคน",
