  ui_story_5036_50360901_28_dialog_content = "เว้นแต่ว่าในความฝันนั้นฉันสัมผัสได้ถึงร่องรอยการมีอยู่ของเธอบนยักษ์ใหญ่นี้",
  ui_story_5036_50360901_29_dialog_content = "Caelestite ร้องเพลงขี่ Colossus ท่อง Astra... เธอดูเหมือน Goldie มาก",
  ui_story_5036_50360901_30_dialog_content = "*หาว* ฉันฝันเยอะมากแน่ๆกับการนอนแค่ชั่วโมงเดียว",
