  ui_story_5036_50360901_32_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก!</color>",
  ui_story_5036_50360901_33_dialog_content = "(ใครมาเคาะตอนดึกๆเนี่ย?)",
  ui_story_5036_50360901_34_dialog_content = "กำลังไปน่า!",
  ui_story_5036_50360901_35_dialog_content = "เสียใจ, PlayerNameฉันปลุกคุณหรือเปล่า",
