  ui_story_5036_50360901_39_dialog_content = "ไม่ มันไม่ได้แย่ขนาดนั้น... ช่วงนี้คุณฝันแปลกๆ หรือเปล่า?",
  ui_story_5036_50360901_40_dialog_content = "ความฝันของหุบเขาอันกว้างใหญ่และเสียงของหญิงสาวที่ร้องเพลง",
