  ui_story_5036_50360901_48_dialog_content = "ทุกคน?!",
  ui_story_5036_50360901_49_dialog_content = "ใช่. มันเป็นเรื่องบังเอิญเมื่อมีคนสองหรือสามคน แต่ไม่ใช่ทุกคน!",
