  ui_story_5036_50360901_58_dialog_content = "แต่ด้วยขนาดที่แท้จริงของ Eulogoz ฉันจึงไม่สามารถครอบคลุมโครงสร้างทั้งหมดได้แม้จะใช้กระแสจิตก็ตาม",
