  ui_story_5036_50361002_64_dialog_content = "พวกเขารู้ว่าฉันสัญญากับแฟนๆ ว่าจะจัดคอนเสิร์ตที่ Umbraton และกำลังพยายามทำให้ฉันกลับคำ",
