  ui_story_5036_50361002_X67_dialog_content = "ฉันต้องพิสูจน์ให้แฟนๆ เห็นว่าฉันจะไม่มีวันทรยศต่อความรักและการสนับสนุนที่พวกเขามอบให้ฉัน!",
