  ui_story_5036_50361002_67_dialog_content = "สิ่งเดียวที่ฉันทำได้ในตอนนี้คือการจัดคอนเสิร์ตที่ไม่ซ้ำแบบใครให้ทุกคนได้สัมผัสตัวตนที่แท้จริงของฉันด้วยตัวฉันเอง",
