  ui_story_5036_50361002_69_dialog_content = "ดังนั้นเมื่อเหตุการณ์นั้นสงบลง ฉันเลือกที่จะนอนลงและเก็บสิ่งต่างๆ ไว้กับตัวเอง ฉันไม่ต้องการให้ใครเห็นฉันในตำแหน่งที่อ่อนแอ",
