  ui_story_5036_50361101_81_dialog_content = "เพียงแค่บอกเราแล้ว! ฉันจะทำอะไรก็ได้ ตราบใดที่ยังให้โอกาสฉันได้จัดคอนเสิร์ตนี้!",
  ui_story_5036_50361101_82_dialog_content = "บอกฉันเกี่ยวกับนิมิตที่คุณเห็นเมื่อไม่กี่นาทีก่อน PlayerName. Chaminade ดูเหมือนจะได้รับผลกระทบในทางลบจากไข่ Ouroboros หรือไม่?",
  ui_story_5036_50361101_83_dialog_content = "ฮะ? พอมาคิดดูแล้ว... ไม่สิ เธอดูไม่ใส่ใจเลยจริงๆ",
  ui_story_5036_50361101_84_dialog_content = "เข้าใจแล้ว. คำตอบอยู่ในนั้นเพื่อนของฉัน!",
  ui_story_5036_50361101_85_dialog_content = "ความสามารถทางจิตของ Ouroboros ดูเหมือนจะเป็นกลไกป้องกันตัวเองที่ใช้เฉพาะเมื่อสัมผัสได้ถึงอันตรายที่อยู่ใกล้เคียง",
  ui_story_5036_50361101_86_dialog_content = "ถ้าเราสามารถเอาแหล่งที่มาของอันตรายนั้นออกจาก Colossus ได้ มันควรจะรู้สึกปลอดภัยพอที่จะปัดเป่าอิทธิพลทางจิตของมัน!",
  ui_story_5036_50361101_87_dialog_content = "คุณกำลังบอกว่าเราต้องกำจัด Eclipsites บน Colossus เหรอ?",
  ui_story_5036_50361101_88_dialog_content = "นั่นเป็นวิธีหนึ่งในการพูดใช่",
  ui_story_5036_50361101_89_dialog_content = "นั่นหมดแล้วหรือ? นั่นไม่ใช่ปัญหาสำหรับเรา!",
  ui_story_5036_50361101_90_dialog_content = "N-ตอนนี้ รอสักครู่!",
  ui_story_5036_50361101_91_dialog_content = "ยักษ์ใหญ่ตัวนี้ก็มหึมา! เราจะกำจัด Eclipsite ทุกอันด้วยพวกเราสี่คนได้อย่างไร! มันเป็นไปไม่ได้!",
