  ui_story_5036_50361101_95_dialog_content = "จะเกิดอะไรขึ้นถ้าเราพยายามกำจัด Eclipsites ในบริเวณใกล้เคียง แล้วปิดรอยร้าวทั้งหมดบนกำแพง ด้วยวิธีนี้พวกมันจะไม่มีทางเข้าใกล้ไข่ได้เลย!",
