  ui_story_5036_50361102_8_dialog_content = "ถ้าเรียกได้ว่านั่งล้อมวงเชียร์พวกเรา \"ผู้นำ\" ล่ะก็...",
  ui_story_5036_50361102_9_dialog_content = "คุณคาดหวังจริงๆเหรอว่าคนแก่อย่างฉันจะไล่ตามฝูงไก่ฤดูใบไม้ผลิอย่างคุณ?",
