  ui_story_5036_50361102_34_dialog_content = "คุณคิดเหมือนกันใช่ไหม? ฉันไม่. การมีความฝันแปลกๆ แบบนั้นก็เหมือนกับการปลดล็อกความสำเร็จที่ซ่อนอยู่ในเกม!",
