  ui_story_5036_50361102_64_dialog_content = "แต่ฉันรู้ว่าคุณควรพักงานของคุณไว้สักหน่อย และพักผ่อนเสียเดี๋ยวนี้ โกลดี",
  ui_story_5036_50361102_65_dialog_content = "เฮ้อ",
  ui_story_5036_50361102_66_dialog_content = "ฉันคิดว่ามันคงไม่เสียหายที่จะบอกความจริงกับคุณ PlayerName. ท้ายที่สุด คุณช่วยฉันได้มากแล้ว",
