  ui_story_5036_50361102_X67_dialog_content = "ฉันไม่เพียงแค่ทำตามสัญญาที่ให้ไว้กับแฟนๆ ในคอนเสิร์ตนี้เท่านั้น... ฉันยังทำตามสัญญาที่ให้ไว้กับ Lady Sheol อีกด้วย",
  ui_story_5036_50361102_68_dialog_content = "ด้วยความสัตย์จริงกับคุณ ฉันทำข้อตกลงกับ Sheol แล้ว",
