  ui_story_5036_50361102_70_dialog_content = "เธอมองเห็นถึงศักยภาพของวงการไอดอลรวมถึงความสามารถของตัวฉันเอง ดังนั้นเธอจึงตัดสินใจลงทุนในอาชีพของฉัน",
  ui_story_5036_50361102_71_dialog_content = "เธอเป็นแหล่งสนับสนุนทางการเงินที่ใหญ่ที่สุดของฉัน แต่ในขณะเดียวกัน ฉันต้องทำทุกอย่างเท่าที่ทำได้เพื่อปฏิบัติตามข้อเรียกร้องของเธอ",
  ui_story_5036_50361102_72_dialog_content = "หนึ่งในนั้นคือการจัดคอนเสิร์ตที่นี่ใน Umbraton ภายในช่วงระยะเวลาหนึ่ง และคอนเสิร์ตนั้น—",
