  ui_story_5036_50361102_74_dialog_content = "คุณไม่คิดว่า Sheol กำลังเอาเปรียบคุณเหรอ? เป้าหมายนั้นเป็นไปได้หรือไม่!",
  ui_story_5036_50361102_75_dialog_content = "ฉันยอมรับว่ามันไม่ง่ายเลยสำหรับคนที่มีชื่อเสียงในระดับเดียวกับฉัน แต่ไม่มีอะไรที่เป็นไปไม่ได้ตราบใดที่ฉันวางแผนทุกอย่างไว้อย่างลงตัว",
  ui_story_5036_50361102_76_dialog_content = "แต่รู้ไหม เรื่องทั้งหมดเกิดขึ้น ดังนั้นฉันจึงไม่สามารถเช่าสถานที่ได้",
  ui_story_5036_50361102_77_dialog_content = "แต่เมื่อความหวังทั้งหมดดูเหมือนจะหายไป ยักษ์ใหญ่พเนจรก็ปรากฏตัวขึ้นบนท้องฟ้า! การมาถึงของมันช่างบังเอิญเหลือเกิน!",
  ui_story_5036_50361102_78_dialog_content = "ตามสัญญาของฉันกับ Sheol พรุ่งนี้เป็นวันสุดท้ายที่ฉันสามารถจัดคอนเสิร์ตได้ มันคือโอกาสสุดท้ายของฉัน ฉันจึงต้องทุ่มสุดตัว",
  ui_story_5036_50361102_79_dialog_content = "ถ้าฉันล้มเหลว ฉันจะต้องชดใช้ Sheol สำหรับค่าใช้จ่ายทั้งหมดของเธอ ฉันจะเป็นหนี้ท่วมหัว",
  ui_story_5036_50361102_80_dialog_content = "อาชีพการเป็นไอดอลของฉันก็จะจบลงเช่นกัน",
  ui_story_5036_50361102_81_dialog_content = "ฉันไม่รู้ว่าคุณทำงานภายใต้แรงกดดันขนาดนี้ โกลดี้ มันไม่มากเกินไปเหรอ?",
  ui_story_5036_50361102_82_dialog_content = "ฉันไม่คิดอย่างนั้น มันเป็นหน้าที่ของฉันแล้ว",
  ui_story_5036_50361102_83_dialog_content = "ในฐานะไอดอล เหตุผลทั้งหมดของฉันคือนำความหวังและความสุขมาสู่แฟนๆ ที่ภักดีของฉันผ่านเพลงและการเต้น",
  ui_story_5036_50361102_84_dialog_content = "หากปราศจากความรักและการสนับสนุนจากพวกเขา ฉันคงไม่สามารถเรียกตัวเองว่าเป็นไอดอลได้เลย",
  ui_story_5036_50361102_85_dialog_content = "หลังจากความรักที่พวกเขาแสดงให้ฉันเห็น ฉันจะเป็นคนแบบไหนถ้าฉันไม่ตอบแทนพวกเขาด้วยการทำงานหนักเท่าที่จะทำได้?",
  ui_story_5036_50361102_86_dialog_content = "ฉันจะเสี่ยงทั้งหมดหากมันหมายความว่าคอนเสิร์ตของฉันจะช่วยให้เสียงของฉันเข้าถึงผู้คนได้มากขึ้น!",
  ui_story_5036_50361102_87_dialog_content = "ฉันรู้ว่าคุณทำได้ โกลดี้!",
  ui_story_5036_50361102_88_dialog_content = "แต่คุณไม่ได้อยู่คนเดียว คุณมีฉันด้วย!",
  ui_story_5036_50361102_89_dialog_content = "ถ้ามีอะไรที่ฉันสามารถช่วยได้ สิ่งที่คุณต้องทำก็แค่ถาม",
  ui_story_5036_50361102_90_dialog_content = "ขอบคุณนะ PlayerName!",
  ui_story_5036_50361102_91_dialog_content = "เรามาทำให้ดีที่สุดเพื่อปกป้อง Eulogoz และทำให้คอนเสิร์ตครั้งนี้ยิ่งใหญ่ที่สุดเท่าที่โลกเคยเห็นมา!",
  ui_story_5036_50361201_1_dialog_content = "<color=#e8d9bb>วันต่อมา สิบห้านาทีก่อนคอนเสิร์ตเริ่ม</color>",
  ui_story_5036_50361201_2_dialog_content = "คอนเสิร์ตกำลังจะเริ่ม! ทุกคนพร้อมยัง?",
  ui_story_5036_50361201_3_dialog_content = "พร้อมค่ะ!",
  ui_story_5036_50361201_4_dialog_content = "ในที่สุดการแสดงก็เริ่มต้นขึ้น? ถึงเวลาที่เราทุกคนรอคอย!",
  ui_story_5036_50361201_5_dialog_content = "(พูดตามตรง ทำให้ฉันเสียเวลาอันมีค่าไปกับการคลุกคลีกับคนธรรมดาสามัญเหล่านี้)",
  ui_story_5036_50361201_6_dialog_content = "แสดงออก, เปิดเผย.",
  ui_story_5036_50361201_7_dialog_content = "การแสดงความคิดที่หยาบคายและต่ำต้อยจะมองเห็นได้ชัดเจนบนใบหน้าของคุณ",
  ui_story_5036_50361201_8_dialog_content = "โอ้หุบปาก",
  ui_story_5036_50361201_9_dialog_content = "สุดยอด! เกมกำลังจะเริ่มขึ้นแล้ว!",
  ui_story_5036_50361201_10_dialog_content = "พร้อมที่จะช่วยฉันเชียร์พวกเขา Sio?",
  ui_story_5036_50361201_11_dialog_content = "R-พร้อม...",
  ui_story_5036_50361201_12_dialog_content = "ทำไมเรายังไม่เริ่ม ฉันอยากจะกระแทกฝูงชนให้ตายไปกับเพลงร็อคของฉัน!",
  ui_story_5036_50361201_13_dialog_content = "เอาจริงดิไอ้โง่! นี่คือคอนเสิร์ตของไอดอล ไม่ใช่คอนเสิร์ตร็อค! สิ่งที่สำคัญที่สุดคือไอดอล!",
  ui_story_5036_50361201_14_dialog_content = "นั่นคือเหตุผลที่ฉัน Barbara the Diesel Sweety ถูกสร้างมาเพื่อสิ่งนี้!",
  ui_story_5036_50361201_15_dialog_content = "ใครจะอยากฟังเพลงเด็กแบบคุณ? ฝูงชนไม่ต้องการได้ยินว่าขยะ!",
  ui_story_5036_50361201_16_dialog_content = "...?! เกิดอะไรขึ้นน่ะ?",
  ui_story_5036_50361201_17_dialog_content = "สองคนนี้มีชีวิตชีวาเช่นเคย ฉันหวังว่าพวกเขาจะไม่สร้างปัญหาให้กับเรา",
  ui_story_5036_50361201_18_dialog_content = "เห็นด้วย ท้ายที่สุดพวกเขาต้องทำการแสดงเปิดด้วยกัน!",
  ui_story_5036_50361201_19_dialog_content = "ใช่ ฉันรู้ว่าคุณ... เดี๋ยวนะ อะไรนะ! เปิดฉาก? ด้วยกัน?!",
  ui_story_5036_50361201_20_dialog_content = "แน่ใจนะว่าโอเค?!",
  ui_story_5036_50361201_21_dialog_content = "ฉันจะไม่โกหก ฉันก็กังวลนิดหน่อยเหมือนกัน แต่ถ้าฉันปล่อยให้พวกเขาแสดงแยกกัน พวกเขาก็จะสู้กันว่าใครจะได้ไปก่อน",
  ui_story_5036_50361201_22_dialog_content = "การทำให้พวกเขาขึ้นเวทีพร้อมกัน อย่างน้อย คอนเสิร์ตก็จะดำเนินไปอย่างราบรื่นบ้าง",
  ui_story_5036_50361201_23_dialog_content = "นอกจากนี้ ทั้งคู่ยังสาบานว่าจะทำการแสดงเปิดคอนเสิร์ตอย่างบ้าคลั่ง!",
  ui_story_5036_50361201_24_dialog_content = "อ๋อ จะเป็น \"นักฆ่า\" ก็ได้... แค่ไม่แน่ใจว่าจะเป็นสกิลอะไร...",
  ui_story_5036_50361201_25_dialog_content = "มีศรัทธาในพวกเขาเล็กน้อย! ฉันรู้ว่าพวกเขาทะเลาะกันตลอดเวลา แต่ก็ไม่ปฏิเสธทักษะหรือความทุ่มเทในการแสดงของพวกเขา",
  ui_story_5036_50361201_26_dialog_content = "ได้เลย ฉันแค่หวังว่าพวกเขาจะอยู่บนเวทีได้นานพอที่จะผ่านการแสดงไปได้",
  ui_story_5036_50361201_27_dialog_content = "ท้ายที่สุดแล้ว Eulogoz ก็มีทุกอย่างในคอนเสิร์ตนี้เช่นกัน",
  ui_story_5036_50361201_28_dialog_content = "คุณสนใจ Eulogoz จริงๆ ใช่ไหม",
  ui_story_5036_50361201_29_dialog_content = "นั่นเป็นเพราะมันเป็น Colossus ที่ทำงานเต็มรูปแบบเพียงแห่งเดียวในโลก นอกเหนือจาก Soroz และ Lepidoz",
  ui_story_5036_50361201_30_dialog_content = "Caelestites มีสายสัมพันธ์ที่แน่นแฟ้นกับยักษ์ใหญ่ทุกตัว พวกเขากำลังพิสูจน์ว่าเคยมีคนของฉันอยู่",
  ui_story_5036_50361201_31_dialog_content = "ฉันต้องการทำให้ดีที่สุดเพื่อรักษาพวกเขาไว้ให้ได้มากที่สุด ฉันรู้ว่าชาว Caelesti คนอื่นๆ จะชอบสิ่งนั้น...",
  ui_story_5036_50361201_32_dialog_content = "ไม่ต้องพูดถึงว่าถ้าเราแก้ไข Eulogoz ในที่สุด Soroz จะมีเพื่อนอีกคน มันคงไม่รู้สึกเหงาเท่าไหร่",
  ui_story_5036_50361201_33_dialog_content = "ไม่ต้องกังวล, PlayerName. ฉันจะทำให้ดีที่สุดเพื่อประโยชน์ของคุณ เช่นเดียวกับพวกเขา!",
  ui_story_5036_50361201_34_dialog_content = "เราจะช่วยด้วย!",
  ui_story_5036_50361201_35_dialog_content = "ถ้ามีอะไรผิดพลาดจริงๆ ฉันจะอยู่ตรงนั้นเพื่อรักษาความสงบเรียบร้อย",
  ui_story_5036_50361201_36_dialog_content = "เช่นเคย คาร์ลีนควบคุมทุกอย่างได้!",
  ui_story_5036_50361201_37_dialog_content = "ว้าว คุณสองคนดูพร้อมมากสำหรับคอนเสิร์ตครั้งนี้",
  ui_story_5036_50361201_38_dialog_content = "แน่นอน! เรายังเตรียมอาวุธลับไว้สำหรับโอกาสนี้ด้วย!",
  ui_story_5036_50361201_39_dialog_content = "จะทำเพลงอะไรด้วยกัน?",
  ui_story_5036_50361201_40_dialog_content = "เดิมทีเราจะร้องเพลงตั้งแต่สมัยเป็นนักเรียน แต่พอซ้อม รู้สึกเหมือนขาดอะไรไป",
  ui_story_5036_50361201_41_dialog_content = "มันไม่ได้ครอบคลุมทุกอย่างเกี่ยวกับการเดินทาง ความยากลำบาก หรือช่วงเวลาแห่งความสุขของเรา",
  ui_story_5036_50361201_42_dialog_content = "ถูกตัอง! และเมื่อฉันถามเธอเกี่ยวกับเรื่องนี้ ฉันก็รู้ว่าเราสองคนรู้สึกแบบเดียวกัน!",
  ui_story_5036_50361201_43_dialog_content = "นั่นเป็นเหตุผลที่เราตัดสินใจเขียนเพลงใหม่ทั้งหมดสำหรับการแสดง!",
  ui_story_5036_50361201_44_dialog_content = "ว้าว ฉันแทบจะรอฟังไม่ไหวแล้ว!",
  ui_story_5036_50361201_45_dialog_content = "Regina, Barbara, Carleen, รอง, วิก...",
  ui_story_5036_50361201_46_dialog_content = "เดี๋ยวนะ วิคอยู่ไหน?",
  ui_story_5036_50361201_47_dialog_content = "วิค? เมื่อคุณพูดถึงมัน ฉันสังเกตเห็นว่าห้องของเขาว่างเปล่าเมื่อฉันผ่านมันไประหว่างทางที่นี่",
