  ui_story_5036_50361201_51_dialog_content = "บางทีเขาอาจจะกลับไปตรวจสอบไข่โอโรโบรอส?",
  ui_story_5036_50361201_52_dialog_content = "บางครั้งเขาสนใจเกี่ยวกับสัตว์ร้ายมากกว่าคนอื่น ๆ และยังมีแนวโน้มที่จะเผลอหลับไปโดยบังเอิญอีกด้วย",
  ui_story_5036_50361201_53_dialog_content = "มีโอกาสดีที่เขาจะไปนอนที่นั่น",
