  ui_story_5036_50361201_57_dialog_content = "เขากรอกเราเข้าไป มันอยู่ในเขตล็อคดาวน์ไม่ใช่เหรอ?",
  ui_story_5036_50361201_58_dialog_content = "สถานที่นั้นอันตรายเกินไป! ฉันจะไปกับคุณ!",
  ui_story_5036_50361201_59_dialog_content = "นับฉันเข้าไปด้วย",
  ui_story_5036_50361201_60_dialog_content = "ค่อนข้างไกลจากเวที ไปและกลับจะใช้เวลาสักครู่แน่นอน",
  ui_story_5036_50361201_61_dialog_content = "หากคุณสองคนยังคงวางแผนที่จะแสดง คุณควรอยู่ที่นี่และเตรียมตัวให้พร้อม",
  ui_story_5036_50361201_62_dialog_content = "แต่คุณจะจัดการกับ Eclipsites เหล่านั้นด้วยตัวคุณเองได้อย่างไร?",
  ui_story_5036_50361201_63_dialog_content = "คุณไม่ต้องกังวลเรื่องนั้น คาร์ลีน Goldie, Vic และฉันได้กำจัด Eclipsite ทุกที่ระหว่างที่นี่และที่นั่นแล้ว",
