  ui_story_5036_50361201_65_dialog_content = "ถ้าคุณพูดอย่างนั้น ก็รีบทำซะ และระวังด้วย!",
  ui_story_5036_50361201_66_dialog_content = "ฉันจะทำ ไม่ต้องกังวล",
  ui_story_5036_50361201_67_dialog_content = "เอาล่ะทุกคน! ได้เวลาเริ่มคอนเสิร์ตของเราแล้ว!",
  ui_story_5036_50361201_68_dialog_content = "ถ้าวิคกลับไม่ทัน คุณสองคนจะต้องขึ้นเวทีเร็วกว่ากำหนดนิดหน่อย เข้าใจไหม?",
  ui_story_5036_50361201_69_dialog_content = "ได้! เข้าใจแล้ว!",
  ui_story_5036_50361201_70_dialog_content = "เข้าใจแล้ว",
  ui_story_5036_50361201_71_dialog_content = "มันยังไม่เริ่ม?",
  ui_story_5036_50361201_72_dialog_content = "ฉันคิดว่าพวกเขากำลังจะ! ดูนั่นสิ!",
  ui_story_5036_50361201_73_dialog_content = "ในที่สุดช่วงเวลาก็มาถึง ทุกคน! ขออภัยที่ให้ทุกท่านรอนาน!",
  ui_story_5036_50361201_74_dialog_content = "คอนเสิร์ต \"The Moment the Star Shining Brightest\" Sky Concert กำลังจะเริ่มขึ้นแล้ว!",
  ui_story_5036_50361201_75_dialog_content = "วู้ฮู้!!!",
  ui_story_5036_50361201_76_dialog_content = "<color=#e8d9bb>ในขณะเดียวกัน</color>",
  ui_story_5036_50361201_77_dialog_content = "อืม? นั่นอาจเป็นอะไร",
  ui_story_5036_50361201_78_dialog_content = "มีบางอย่างเป็นประกายผ่านก้อนเมฆ... นั่นมันโคลอสซัสเหรอ!",
  ui_story_5036_50361201_79_dialog_content = "ดูเหมือนว่าจะมีเสียงดนตรีมาจากมัน เสียงนั้นพูดอะไรบางอย่างเกี่ยวกับ Sky Concert ใช่ไหม?",
  ui_story_5036_50361201_80_dialog_content = "ให้ฉันอธิบายให้ชัดเจน มิส คุณอาจจะรู้หรือไม่ก็ได้ว่านั่นคือ Wandering Colossus ที่เพิ่งมาถึงจาก Eternal Night",
  ui_story_5036_50361201_81_dialog_content = "ดูเหมือนว่าไอดอลชื่อ Goldie กำลังจัดคอนเสิร์ตอยู่บนนั้น",
  ui_story_5036_50361201_82_dialog_content = "กระดาษทุกแผ่นใน Umbraton เต็มไปด้วยข่าวคอนเสิร์ตนี้",
  ui_story_5036_50361201_83_dialog_content = "อย่างนั้นเหรอ? ช่างน่าขบขันมาก",
  ui_story_5036_50361201_84_dialog_content = "มา ให้เราหามุมมองที่ดีและดูว่าความวุ่นวายนั้นเกี่ยวกับอะไร!",
  ui_story_5036_50361201_85_dialog_content = "ตามที่คุณต้องการคุณผู้หญิง",
  ui_story_5036_50361201_86_dialog_content = "ดูนั่นซิ! มันคือยักษ์ใหญ่!",
  ui_story_5036_50361201_87_dialog_content = "ว้าว! ยักษ์ใหญ่ตัวจริง!",
  ui_story_5036_50361201_88_dialog_content = "เดี๋ยวก่อน ด้านบนของ Colossus นั่นคือหน้าจอเหรอ? เหมือนกำลังเล่นอะไรสักอย่าง...",
  ui_story_5036_50361201_89_dialog_content = "เฮ้! ผู้หญิงคนนั้นที่ปกป้องเราจากเจ้าของโรงละครวันนั้นไม่ใช่เหรอ!",
  ui_story_5036_50361201_90_dialog_content = "มันคือเธอ! ดังนั้นเธอจึงหาสถานที่สำหรับจัดคอนเสิร์ตของเธอ! และบนยักษ์ใหญ่ไม่น้อย!",
  ui_story_5036_50361201_91_dialog_content = "แม้ว่าเราจะไม่มีตั๋ว แต่ก็สามารถเห็นและได้ยินทุกอย่างได้ชัดเจนเหมือนกลางวัน เธอช่างเหลือเชื่อ ใช่มั้ยพี่สาว?",
  ui_story_5036_50361201_92_dialog_content = "มันกำลังบินไปที่นั่น! มาเลยมาติดตามกันเลย!",
  ui_story_5036_50361201_93_dialog_content = "เราจะตามเชียร์เธอไปตลอดทาง!",
  ui_story_5036_50361201_94_dialog_content = "ฉันสัมผัสได้ถึงความกระตือรือร้นของทุกคนแล้ว!",
  ui_story_5036_50361201_95_dialog_content = "สำหรับการแสดงเปิดตัวของเรา เรามีไอดอลสุดฮอตสองคนจากที่ที่ร้อนยิ่งกว่า นั่นคือ Rediesel Desert ที่จะมาแสดงการแสดงที่เร่าร้อนและเร่าร้อนให้กับคุณ!",
  ui_story_5036_50361201_96_dialog_content = "ยอมแพ้ให้กับ Regina และ Barbara กันเถอะ!",
  ui_story_5036_50361201_97_dialog_content = "♪ เผา เผามันทั้งหมดให้ราบเป็นหน้ากลอง—♪",
  ui_story_5036_50361201_98_dialog_content = "♪ ฉันมอบความรักทั้งหมดของฉันให้คุณ—♪",
  ui_story_5036_50361201_99_dialog_content = "<size=40>♪ ระเบิด! ระเบิด! ทำลายมันลงเป็นชิ้น ๆ ! ♪</size>",
  ui_story_5036_50361201_100_dialog_content = "<size=45>♪ ได้ยินเสียงหัวใจของฉันที่เต้นรัว อยากเจอเธออีกครั้ง ♪</size>",
  ui_story_5036_50361201_101_dialog_content = "(บ้าเอ้ย ทำไมเสียงเธอดังจังวะ!)",
  ui_story_5036_50361201_102_dialog_content = "(ฉันไม่ยอมให้เธอทุบฉันแน่!!!)",
  ui_story_5036_50361201_103_dialog_content = "<size=40>♪ นี่ของฉัน—♪</size>",
  ui_story_5036_50361201_104_dialog_content = "<size=45>♪ ความปรารถนาเดียวของฉัน ที่จะได้เป็นของเธอ—♪</size>",
  ui_story_5036_50361201_105_dialog_content = "<size=50>♪ ร็อคแอนด์โรล!!! ♪</size>",
  ui_story_5036_50361201_106_dialog_content = "<size=50>♪ ไอดอล!!! ♪</size>",
  ui_story_5036_50361201_107_dialog_content = "นี่มันเสียงบ้าอะไรเนี่ย! มันดังมากและฉันไม่สามารถเข้าใจสิ่งที่พวกเขากำลังพูด!",
  ui_story_5036_50361201_108_dialog_content = "หูยยย รู้สึกเหมือนจะระเบิด ปิดไมค์!",
  ui_story_5036_50361201_109_dialog_content = "คุณกำลังล้อเล่นฉัน?! พวกเขาสัญญาว่าจะไม่ทะเลาะกันบนเวที!",
  ui_story_5036_50361201_110_dialog_content = "สิ่งนี้จะไม่เกิดขึ้น... หากยังเป็นเช่นนี้ การแสดงจะเป็นหายนะ ฉันต้องพาพวกเขากลับเข้าที่เข้าทางให้ได้!",
  ui_story_5036_50361201_111_dialog_content = "♪ รู้สึกถึงหัวใจของฉัน มันเต้นแรงและแผดเผา เหมือนกับแสงอาทิตย์ในทะเลทราย—♪",
  ui_story_5036_50361201_112_dialog_content = "(เดี๋ยวนะ พิธีกรกำลังทำอะไรอยู่บนเวที? แล้วเธอร้องเพลงทำไม?!)",
  ui_story_5036_50361201_113_dialog_content = "(นี่ไม่ใช่ส่วนหนึ่งของการซ้อม!)",
  ui_story_5036_50361201_114_dialog_content = "(ฉันหวังว่าพวกเขาจะได้รับข้อความ เอาเลย เลดี้โชค อย่าเพิ่งทำให้ฉันผิดหวัง!)",
  ui_story_5036_50361201_115_dialog_content = "♪ ทั้งหมดที่ฉันต้องการคือให้คุณได้ยินฉันและรู้สึกว่าฉันรู้สึกอย่างไร! และนั่นคือ—♪",
  ui_story_5036_50361201_116_dialog_content = "♪ นั่นคือ—♪",
  ui_story_5036_50361201_117_dialog_content = "♪ นั่นสินะ—♪",
  ui_story_5036_50361201_118_dialog_content = "<size=45>♪ รัก—!!!♪</size>",
  ui_story_5036_50361201_119_dialog_content = "♪ ความรักที่ไม่มีวันมอดดับ! ♪",
  ui_story_5036_50361201_120_dialog_content = "♪ รักที่อยู่ตรงนี้เสมอ! ♪",
  ui_story_5036_50361201_121_dialog_content = "<size=50>♪ รักเหมือนเม็ดทรายที่ไม่มีวันสิ้นสุดของ Rediesel—♪</size>",
  ui_story_5036_50361201_122_dialog_content = "(ได้ผล! ในที่สุดทั้งสองก็กลับมาซิงค์กันอีกครั้ง!)",
  ui_story_5036_50361201_123_dialog_content = "(ตอนนี้เพื่อให้ทางออกของฉัน.)",
  ui_story_5036_50361201_124_dialog_content = "♪ ด้วยศิลาอันชอบธรรมของฉันที่ไม่อาจหยุดยั้งได้— ♪",
  ui_story_5036_50361201_125_dialog_content = "♪ ฉันจะยื่นมือออกไปสัมผัสหัวใจของคุณ— ♪",
  ui_story_5036_50361201_126_dialog_content = "<size=50>♪ ปล่อยให้เพลงของเราดังไปถึงท้องฟ้าเบื้องบน—♪</size>",
  ui_story_5036_50361201_127_dialog_content = "ฮะ? เฮ้ พวกเขาเริ่มฟังดูดีทีเดียว!",
  ui_story_5036_50361201_128_dialog_content = "ท่าทางของ Goldie นั้นเหลือเชื่อมาก! ฉันควรถ่ายรูปให้ได้มากที่สุด!",
  ui_story_5036_50361201_129_dialog_content = "แม้ว่าท่วงทำนองของพวกเขาจะแตกต่างกันเพียงใด แต่พวกเขาทั้งสองก็ร้องเพลงประสานเสียงได้อย่างสมบูรณ์แบบ แค่มองไปที่ฝูงชนที่มารวมตัวกัน!",
  ui_story_5036_50361201_130_dialog_content = "ตะลึง! ฉันไม่เชื่อว่า Lumopolis จะเคยจัดคอนเสิร์ตแบบนี้มาก่อน!",
  ui_story_5036_50361201_131_dialog_content = "ดูเหมือนว่ายักษ์ใหญ่กำลังบินหนีไปแล้ว มิสซิส",
  ui_story_5036_50361201_132_dialog_content = "เร็ว! สู่เรือเหาะส่วนตัว!",
  ui_story_5036_50361201_133_dialog_content = "?!?",
  ui_story_5036_50361201_134_dialog_content = "ฉันจะพลาดคอนเสิร์ตสุดมันส์แบบนี้ไปได้ยังไง? รีบ!",
  ui_story_5036_50361201_135_dialog_content = "จัดคอนเสิร์ตบน Colossus ให้โลกได้เห็น ไม่คิดว่าจะมีใครเคยทำมาก่อน!",
  ui_story_5036_50361201_136_dialog_content = "มีผู้คนมารวมตัวกันมากขึ้นเรื่อยๆ",
  ui_story_5036_50361201_137_dialog_content = "แม้แต่พ่อค้าก็เริ่มที่จะเช่าเรือของพวกเขาสำหรับคนดูคอนเสิร์ตจากโกลด์ริเวอร์",
  ui_story_5036_50361201_138_dialog_content = "หึหึหึ ดูเหมือนว่าฉันคิดถูกแล้วที่ลงทุนในความฝันของผู้หญิงคนนี้",
  ui_story_5036_50361201_139_dialog_content = "เป็นวิคและ PlayerName กลับยัง?",
  ui_story_5036_50361201_140_dialog_content = "ยังเลย",
  ui_story_5036_50361201_141_dialog_content = "เริ่มเป็นห่วงสองคนนั้นแล้วสิ...",
  ui_story_5036_50361201_142_dialog_content = "ดูเหมือนว่าเราไม่มีทางเลือกนอกจากให้คุณสองคนขึ้นเวทีก่อน",
  ui_story_5036_50361201_143_dialog_content = "รับทราบ!",
  ui_story_5036_50361201_144_dialog_content = "ขอปรบมือให้กับ Regina และ Barbara สำหรับการแสดงที่ยอดเยี่ยมของพวกเขา!",
  ui_story_5036_50361201_145_dialog_content = "การแสดงเริ่มร้อนแรงขึ้น หัวใจของฉันแทบจะเต้นออกมานอกอก!",
  ui_story_5036_50361201_146_dialog_content = "ต่อไป เรามีดาวที่สว่างที่สุดสองดวงใน Astra ทั้งหมดพร้อมที่จะเปิดตัวอย่างยิ่งใหญ่!",
  ui_story_5036_50361201_147_dialog_content = "คู่หูที่ไม่น่าจะเป็นไปได้: คนหนึ่งเป็นอัศวินแห่งลูโมโพลิส และอีกคนเป็นเจ้าหน้าที่ของสหพันธ์อิลลูมินา!",
  ui_story_5036_50361201_148_dialog_content = "แต่ถึงแม้พวกเขาจะอยู่กันคนละกลุ่ม แต่พวกเขาก็กลายมาเป็นเพื่อนที่สนิทที่สุดและร่วมผจญภัยไปนับครั้งไม่ถ้วนร่วมกับ Caelestite ในตำนาน!",
  ui_story_5036_50361201_149_dialog_content = "วันนี้พวกเขาอยากจะแบ่งปันเพลงของพวกเขากับทุกคน เพลงที่รวบรวมความสวยงามและความตื่นเต้นของการเดินทางทั้งหมดของพวกเขาด้วยกัน!",
  ui_story_5036_50361201_150_dialog_content = "จับมือกันเพื่อ Carleen และ Vice—!",
  ui_story_5036_50361201_151_dialog_content = "ว้าว ดูคนพวกนั้นสิ ถ้าเพียงแค่ PlayerName อยู่ที่นี่...",
  ui_story_5036_50361201_152_dialog_content = "อย่าประหม่า เราจะสบายดี",
  ui_story_5036_50361201_153_dialog_content = "คุณถูก! ไปกันเถอะ คาร์ลีน!",
  ui_story_5036_50361201_154_dialog_content = "♪ การเดินทางที่เหนือจินตนาการ ♪",
  ui_story_5036_50361201_155_dialog_content = "♪ ไม่พบถนนในแผนที่ใดๆ ♪",
  ui_story_5036_50361201_156_dialog_content = "♪ บอกฉันสิ อะไรรออยู่ข้างหน้า? ♪",
  ui_story_5036_50361201_157_dialog_content = "♪ ความรู้สึกประหลาดใจ ♪",
  ui_story_5036_50361201_158_dialog_content = "♪ เราเคยเดินเคียงข้างกัน ตั้งแต่วันที่พบกัน ♪",
  ui_story_5036_50361201_159_dialog_content = "♪ ไม่ว่าจะไกลแค่ไหน เราจะกลับมาพบกันใหม่เสมอ! ♪",
  ui_story_5036_50361201_160_dialog_content = "♪ เพื่อนรักของฉัน ♪",
  ui_story_5036_50361201_161_dialog_content = "♪ จากคนแปลกหน้าสู่เพื่อน! ♪",
  ui_story_5036_50361201_162_dialog_content = "♪ สหายชั่วชีวิต แสงสว่างที่ไม่มีวันสิ้นสุด! ♪",
  ui_story_5036_50361201_163_dialog_content = "♪ เราแล่นผ่านท้องฟ้าเมื่อดาวหางสองดวงโอบกัน ♪",
  ui_story_5036_50361201_164_dialog_content = "ขอบคุณพระเจ้า Gronru ที่มองการณ์ไกลในการติดตั้งเครื่องส่งสัญญาณก่อนที่คอนเสิร์ตจะเริ่มขึ้น ตอนนี้เราทุกคนสามารถเพลิดเพลินกับเสียงเพลงได้แม้จากที่นี่",
  ui_story_5036_50361201_165_dialog_content = "ฉันต้องบอกว่าความบันเทิงรูปแบบใหม่นี้สมควรได้รับการพิจารณา",
  ui_story_5036_50361201_166_dialog_content = "บางทีเราอาจทำการทดลองที่คล้ายกันใน Undercities สักวันหนึ่ง คุณว่าอย่างไร จอมพล?",
  ui_story_5036_50361201_167_dialog_content = "ดีมาก. ฉันจะอนุญาต",
  ui_story_5036_50361201_168_dialog_content = "ร-จริงเหรอ? ยอดเยี่ยม!",
  ui_story_5036_50361201_169_dialog_content = "ทำไมคุณดูประหลาดใจมาก?",
  ui_story_5036_50361201_170_dialog_content = "ฉันแค่กังวลว่าคุณจะไม่เห็นด้วยกับความบันเทิงประเภทนี้ ก็แค่นั้นเอง",
  ui_story_5036_50361201_171_dialog_content = "ฮ่าฮ่าฮ่า! แน่นอน ฉันมีการพิจารณาเกี่ยวกับเรื่องแบบนี้...แต่ตั้งใจฟังดนตรีให้ดี",
  ui_story_5036_50361201_172_dialog_content = "ฉันอาจไม่มีพรสวรรค์มากนักในเรื่องของการร้องเพลง แต่ฉันบอกได้เลยว่าตอนนี้ ในช่วงเวลานี้ Vice กำลังเปี่ยมไปด้วยความสุข",
  ui_story_5036_50361201_173_dialog_content = "มันก็แค่ความรู้สึกที่เราต้องการไม่ใช่เหรอ?",
  ui_story_5036_50361201_174_dialog_content = "ฉันแทบไม่ได้ยิน Lady Carleen และ Vice ร้องเพลง แม้แต่จากตรงนี้...",
  ui_story_5036_50361201_175_dialog_content = "พวกเขาฟังดูน่าทึ่ง! นั่นคือ Lady Carleen สำหรับคุณ!",
  ui_story_5036_50361201_176_dialog_content = "ราฟาเอล อยู่ที่นี่และปกป้องสถานที่นี้ด้วยความระมัดระวังเป็นพิเศษ",
  ui_story_5036_50361201_177_dialog_content = "ให้มีคนเตรียมเรือบินให้ฉันด้วย และเก็บมันไว้เป็นความลับ",
  ui_story_5036_50361201_178_dialog_content = "ฮะ? คุณกำลังออกไปเดี๋ยวนี้ เจ้านายของฉัน?",
  ui_story_5036_50361201_179_dialog_content = "ยังไม่ชัดเจนว่า Colossus เป็นภัยคุกคามหรือไม่ ในฐานะเจ้าเมือง เป็นหน้าที่ของฉันที่จะต้องตรวจสอบเรื่องนี้และรับรองความปลอดภัยของเมืองเป็นการส่วนตัว",
  ui_story_5036_50361201_180_dialog_content = "เข้าใจแล้ว!",
  ui_story_5036_50361201_181_dialog_content = "เฮ้อ...",
  ui_story_5036_50361201_182_dialog_content = "เมื่อไหร่ลอร์ดชวาร์ตษ์จะยอมรับว่าเขาห่วงใยเลดี้คาร์ลีน?",
  ui_story_5036_50361201_183_dialog_content = "<color=#e8d9bb>ในขณะเดียวกัน ภายใน Wandering Colossus</color>",
  ui_story_5036_50361201_184_dialog_content = "เสียงร้องเพลงนั้นเหมือน Vice และ Carleen!",
  ui_story_5036_50361201_185_dialog_content = "ถึงเวลาสำหรับการแสดงของพวกเขาแล้วหรือยัง? แย่แล้ว ฉันควรจะเร่งฝีเท้าให้เร็วขึ้น!",
  ui_story_5036_50361201_186_dialog_content = "ฉันควรจะอยู่ที่นั่นแล้ว แต่...",
  ui_story_5036_50361201_187_dialog_content = "ไม่มีอะไรที่เหมือนกับการแสดงจากสองนักผจญภัยที่ยิ่งใหญ่ที่สุดในโลก!",
  ui_story_5036_50361201_188_dialog_content = "มันแสดงให้เห็นว่าไอดอลมาจากทุกสาขาอาชีพ!",
  ui_story_5036_50361201_189_dialog_content = "สำหรับแฟนๆ บางคน ไอดอลที่ดีที่สุดคือคนที่ดึงเอาความแข็งแกร่งที่แท้จริงของคนอื่นออกมา!",
  ui_story_5036_50361201_190_dialog_content = "ถัดไปบนเวทีคือคณะนักร้องประสานเสียงที่มีเสน่ห์จากอิลลูมินา!",
  ui_story_5036_50361201_191_dialog_content = "พวกเขามาที่นี่เพื่อร้องเพลงสรรเสริญทหารที่สร้างแรงบันดาลใจ—!",
  ui_story_5036_50361201_192_dialog_content = "วู้ฮู้!!!",
  ui_story_5036_50361201_193_dialog_content = "วุ้ย ขอบคุณอีกครั้งสำหรับความช่วยเหลือ ผู้หญิง!",
  ui_story_5036_50361201_194_dialog_content = "อย่าพูดถึงมัน! ฉันดีใจที่ทุกอย่างเป็นไปด้วยดี!",
  ui_story_5036_50361201_195_dialog_content = "ฉันเริ่มกังวลเกี่ยวกับ PlayerName และวิกแม้ว่า พวกเขาหายไปพักหนึ่งแล้ว",
  ui_story_5036_50361201_196_dialog_content = "อย่างแท้จริง. ยักษ์ใหญ่อาจมีขนาดใหญ่ แต่ไม่ควรใช้เวลามากในการหาใครสักคน",
  ui_story_5036_50361201_197_dialog_content = "อืมม...",
  ui_story_5036_50361201_198_dialog_content = "เอาล่ะ คาร์ลีน เราควรไปหาพวกเขา",
  ui_story_5036_50361201_199_dialog_content = "ฉันเห็นด้วย. ตอนนี้การแสดงของเราจบลงแล้ว สิ่งที่เราให้ความสำคัญสูงสุดคือการทำให้สองคนนั้นปลอดภัย",
  ui_story_5036_50361201_200_dialog_content = "แน่นอน แต่ระวังตัวให้ดี และอย่าลืมกลับมาเพื่อที่คุณจะได้คำนับ!",
  ui_story_5036_50361201_201_dialog_content = "เข้าใจแล้ว!",
  ui_story_5036_50361201_202_dialog_content = "ไปกันเถอะ",
  ui_story_5036_50361201_203_dialog_content = "<color=#e8d9bb>หลังจากนั้นซักพัก</color>",
  ui_story_5036_50361201_204_dialog_content = "คณะนักร้องประสานเสียงอิลลูมินาร้องเพลงของพวกเขาเสร็จ และคณะนักร้องประสานเสียงลูโมโปลิสก็เกือบจะร้องเพลงของพวกเขาเสร็จแล้วเช่นกัน...",
  ui_story_5036_50361201_205_dialog_content = "อยู่ที่ไหนบนโลก PlayerName และอื่น ๆ ? อาจมีบางอย่างเกิดขึ้นกับพวกเขา?",
  ui_story_5036_50361201_206_dialog_content = "พวกเขาเริ่มเป็นห่วงฉัน แต่ฉันไม่สามารถจากไปได้ การแสดงรอบสุดท้ายของฉันใกล้จะมาถึงแล้ว!",
  ui_story_5036_50361201_207_dialog_content = "ฉันต้องแน่ใจว่าทุกคนได้ยินเพลงของฉัน",
  ui_story_5036_50361201_208_dialog_content = "มิฉะนั้น การทำงานหนักทั้งหมดของเราจะไม่สูญเปล่า",
  ui_story_5036_50361201_209_dialog_content = "ฉันจะไปหาพวกเขาทันทีที่ฉันทำเสร็จ",
  ui_story_5036_50361201_210_dialog_content = "ใกล้จะถึงตอนจบสุดยิ่งใหญ่แล้วนะครับทุกคน! เรายังสนุกกันอยู่มั้ย?!",
  ui_story_5036_50361201_211_dialog_content = "ใช่-!",
  ui_story_5036_50361201_212_dialog_content = "มหัศจรรย์! ขอบคุณที่รักษาพลังในคอนเสิร์ตให้ยาวนาน ทุกคน!",
  ui_story_5036_50361201_213_dialog_content = "ตอนนี้สำหรับการแสดงสุดท้ายของการแสดง ให้ฉันส่งทุกคนด้วยเพลงของฉันเอง!",
  ui_story_5036_50361201_214_dialog_content = "วู้!!! ในที่สุดก็ถึงคราวที่โกลดี้ต้องร้องเพลง!!!",
  ui_story_5036_50361201_215_dialog_content = "เพลงต่อไปนี้เป็นเพลงที่พิเศษมาก Caelestites ใช้เพื่อสื่อสารกับ Colossi",
  ui_story_5036_50361201_216_dialog_content = "ด้วยการใช้ท่วงทำนองที่เป็นเอกลักษณ์ ชาว Caelesti จะขับเครื่องบิน Colossi ที่ยิ่งใหญ่ของพวกเขาไปทั่วโลก!",
  ui_story_5036_50361201_217_dialog_content = "วันนี้ เพื่อเป็นเกียรติแก่การกลับมาที่รอคอยมานานของ Colossus ท่วงทำนองนี้จะดังอีกครั้ง!",
  ui_story_5036_50361201_218_dialog_content = "วู้วววว—!!!",
  ui_story_5036_50361201_219_dialog_content = "(นี่แหละ ถึงเวลาที่เราทุกคนรอคอย)",
  ui_story_5036_50361201_220_dialog_content = "ไม่ว่า Goldie จะไปที่ไหน Goldilocks จะติดตาม!",
  ui_story_5036_50361201_221_dialog_content = "(ขอให้เพลงนี้ตอบแทนแฟนเพลงและ PlayerName สำหรับการสนับสนุนที่ไม่สิ้นสุด!)",
  ui_story_5036_50361201_222_dialog_content = "♪ แสงดาวพร่างพรายบนฟากฟ้า ♪",
  ui_story_5036_50361201_223_dialog_content = "♪ นกน้อยกางปีกโบยบิน ♪",
  ui_story_5036_50361201_224_dialog_content = "♪ การเดินทางที่ยาวนานและอันตรายอยู่ต่อหน้าต่อตาเธอ ♪",
  ui_story_5036_50361201_225_dialog_content = "♪ ทำให้เส้นทางของเธอสว่างไสวตลอดทั้งคืน! ♪",
  ui_story_5036_50361201_226_dialog_content = "โกลดี้! โกลดี้!",
  ui_story_5036_50361201_227_dialog_content = "อา... ฉันได้ยินเสียงร้องเพลงของ Miss Goldie...",
  ui_story_5036_50361201_228_dialog_content = "ไม่ว่าอะไรจะยากเย็นแสนเข็ญ สิ่งนี้ทำให้ทุกอย่างคุ้มค่า!",
  ui_story_5036_50361201_229_dialog_content = "♪ โอกาสที่จะได้พบคุณ โอกาสที่ความรักจะเติบโต! ♪",
  ui_story_5036_50361201_230_dialog_content = "♪ เติมความกล้าให้เต็มหัวใจ แล้วบอกฉันทีว่าจะไปทางไหน! ♪",
  ui_story_5036_50361201_231_dialog_content = "(เอิ่ม... ทะ-ทำไมฉันง่วงจัง...?)",
  ui_story_5036_50361201_232_dialog_content = "(เดี๋ยวนะ นี่ฉันกำลังคิดอะไรอยู่เนี่ย! ฉันกำลังร้องเพลงอยู่!!)",
  ui_story_5036_50361201_233_dialog_content = "♪ ไปกันเถอะ พาฉันไป! ♪",
  ui_story_5036_50361201_234_dialog_content = "♪ ไปยังที่ที่ฉันสามารถพบคุณได้ทุกวัน! ♪",
  ui_story_5036_50361201_235_dialog_content = "(เกิดอะไรขึ้น...? หัวหมุนไปหมด...)",
  ui_story_5036_50361201_236_dialog_content = "ครี—!",
  ui_story_5036_50361201_237_dialog_content = "(เสียงนั้น... เสียงนั้นมาจากไหน?)",
  ui_story_5036_50361201_238_dialog_content = "(เหนื่อยจัง...แต่ยังนอนไม่ได้!คอนเสิร์ต...ยังไม่จบ...)",
  ui_story_5036_50361301_1_dialog_content = "<color=#e8d9bb>ในขณะเดียวกันในพื้นที่ล็อคดาวน์</color>",
  ui_story_5036_50361301_2_dialog_content = "เกิดอะไรขึ้น? รู้สึกเหมือนได้กลับไปเป็นวงกลมอีกครั้ง",
  ui_story_5036_50361301_3_dialog_content = "ยังจำทางไปไข่ได้ ทำไมยังไปไม่ถึง?",
  ui_story_5036_50361301_4_dialog_content = "Ouroboros สามารถเปิดใช้งานพลังจิตอีกครั้งได้หรือไม่?",
  ui_story_5036_50361301_5_dialog_content = "เราอยู่ที่นั่นหรือยัง? คอนเสิร์ตน่าจะใกล้จบแล้ว...",
  ui_story_5036_50361301_6_dialog_content = "อา! นั่นมัน! หลังจากเวลาผ่านไป ในที่สุดฉันก็ทำสำเร็จ!",
  ui_story_5036_50361301_7_dialog_content = "อืม? คุณมาทำอะไรที่นี่, PlayerName?",
  ui_story_5036_50361301_8_dialog_content = "อย่าบอกนะว่าคอนเสิร์ตมันน่าเบื่อถึงขนาดมางีบหลับด้วย?",
  ui_story_5036_50361301_9_dialog_content = "แกหลอกฉันเพื่ออะไร!",
  ui_story_5036_50361301_10_dialog_content = "ที่สำคัญกว่านั้น คุณมาทำอะไรที่นี่! ทุกคนยังรอการแสดงของคุณอยู่!",
  ui_story_5036_50361301_11_dialog_content = "การแสดงของฉัน? โอ้ คุณหมายถึงการร้องเพลงทั้งหมดใช่ไหม",
  ui_story_5036_50361301_12_dialog_content = "ขอโทษนะ แต่ฉันทำไม่ได้",
  ui_story_5036_50361301_13_dialog_content = "คุณหมายถึงอะไร?! คุณมีพรสวรรค์ และโกลดี้ใช้เวลาและความพยายามทั้งหมดเพื่อฝึกฝนคุณ! คุณเลือกที่จะประกันตัวในเวลาเช่นนี้ได้อย่างไร!",
  ui_story_5036_50361301_14_dialog_content = "ฮ่า ๆ ๆ ๆ! คุณพูดถูก ฉันมีของขวัญ แต่ฉันทำไม่ได้จริงๆ",
  ui_story_5036_50361301_15_dialog_content = "คุณเคยเห็นวิธีที่พวกเขาฝึกฝนหรือไม่?",
  ui_story_5036_50361301_16_dialog_content = "ในการแสดงบนเวที พวกเขาต้องการการฝึกฝนเป็นเวลาหลายสัปดาห์ รวมถึงพลังงานและความกระตือรือร้นที่ไม่มีที่สิ้นสุด และฉันก็ขาดทั้งสองแผนกมาก ไอ้หนู",
  ui_story_5036_50361301_17_dialog_content = "นอกจากนี้ ฉันไม่มีความสนใจในคอนเสิร์ตหรือไอดอลเลย กระดูกเก่าของฉันไม่ได้ถูกตัดออกสำหรับสิ่งเล็ก ๆ น้อย ๆ แบบนั้น",
  ui_story_5036_50361301_18_dialog_content = "และแม้ว่าฉันจะได้ขึ้นไปบนเวทีนั้น ฉันก็จะรั้งเธอไว้เท่านั้น",
  ui_story_5036_50361301_19_dialog_content = "ดังนั้น แทนที่จะทำให้ทุกคนลำบาก ฉันตัดสินใจใช้ทักษะที่มีอยู่น้อยนิดให้เป็นประโยชน์! ชอบดูแลไข่ใบนี้ไม่ให้ทำลายคอนเสิร์ต!",
  ui_story_5036_50361301_20_dialog_content = "สำหรับคนที่บอกว่าพวกเขาไม่สนใจคอนเสิร์ต แสดงว่าคุณกำลังกังวลอย่างมาก",
  ui_story_5036_50361301_21_dialog_content = "ฮ่าๆ! ฉันแค่ไม่อยากอยู่ในฐานะติดหนี้บุญคุณเด็กหลายคน",
  ui_story_5036_50361301_22_dialog_content = "ฉันคิดว่ามันช้าไปหน่อยสำหรับเรื่องนั้น...",
  ui_story_5036_50361301_23_dialog_content = "อะแฮ่ม ถ้านายกำลังพูดถึงลูกศิษย์ของฉัน ทั้งหมดนี้เป็นส่วนหนึ่งของการฝึกของพวกเขา",
  ui_story_5036_50361301_24_dialog_content = "แต่พอถึงตรงนั้น คุณก็รู้สึกได้ระหว่างทางที่นี่ด้วยใช่ไหม ไข่ Ouroboros เปิดใช้งานพลังอีกครั้ง",
  ui_story_5036_50361301_25_dialog_content = "ใช่. รู้สึกเหมือนเดินอยู่หลายชั่วโมงกว่าจะมาถึงที่นี่",
  ui_story_5036_50361301_26_dialog_content = "นี่หมายความว่า Ouroboros ตรวจพบอันตรายอีกครั้งและพยายามป้องกันตัวเอง",
  ui_story_5036_50361301_27_dialog_content = "แล้ว Eclipsites ที่เราเอาออกมาหรือรอยร้าวที่เรายึดไว้ล่ะ?",
  ui_story_5036_50361301_28_dialog_content = "อาจเป็นเพราะชาวออโรเรียนคนอื่นอยู่ไกลเกินไป?",
  ui_story_5036_50361301_29_dialog_content = "เมื่อคอนเสิร์ตดำเนินไปอย่างเต็มรูปแบบ ชาวออโรเรียนทุกคนจะมารวมตัวกันที่ด้านหน้าของ Colossus ซึ่งอยู่ห่างจากตำแหน่งปัจจุบันของเรามากที่สุด",
  ui_story_5036_50361301_30_dialog_content = "ถ้ามีอะไรเกิดขึ้นที่นี่ เราจะเป็นเพียงคนเดียวที่เหลืออยู่ที่จะปกป้องมัน คนอื่นไม่สามารถมาที่นี่ได้ทันเวลา",
