  ui_story_5036_50361301_32_dialog_content = "มันเป็นไปได้!",
  ui_story_5036_50361301_33_dialog_content = "Ouroboros นี้กลายเป็นสัตว์ที่ขี้ขลาดเสียนี่กระไร หลังจากหลายปีเหล่านี้บนยานยักษ์ใหญ่ที่รบกวน Eclipsite มันก็ยังกลัว!",
  ui_story_5036_50361301_34_dialog_content = "ฉันไม่คิดว่ามันกลัวพวกเขามากเท่ากับกลัวที่จะต้องอยู่คนเดียวอีกแล้ว วิค",
  ui_story_5036_50361301_35_dialog_content = "ฉันใช้ชีวิตสิบเจ็ดปีแรกบนเรือโคลอสซัส แม้ว่าฉันจะอยู่คนเดียว แต่ฉันก็ไม่เคยรู้สึกเหงาเพราะมีโซรอซคอยอยู่เป็นเพื่อน",
  ui_story_5036_50361301_36_dialog_content = "แต่ตอนนี้ฉันมีเพื่อนมากมาย ฉันรู้ว่าฉันไม่สามารถแยกทางกับพวกเขาได้",
  ui_story_5036_50361301_37_dialog_content = "คุณให้ประเด็นที่ดี",
  ui_story_5036_50361301_38_dialog_content = "อย่างไรก็ตาม เมื่อกี้คุณหมายถึงอะไรโดยไข่ \"ทำลายคอนเสิร์ต\"?",
  ui_story_5036_50361301_39_dialog_content = "มันกำลังดำเนินไปได้ด้วยดี ไข่ Ouroboros จะทำอะไรได้บ้างในตอนนี้?",
  ui_story_5036_50361301_40_dialog_content = "ช่างสังเกตเช่นเคย",
  ui_story_5036_50361301_41_dialog_content = "อย่างที่ฉันพูดไปก่อนหน้านี้ มีปัจจัยบางอย่างที่ไม่รู้จักทำให้ไข่นี้ไม่สามารถฟักออกได้ ซึ่งเป็นเหตุผลว่าทำไมมันถึงเติบโตเป็นสัดส่วนที่ใหญ่โต",
  ui_story_5036_50361301_42_dialog_content = "แต่ด้วยเหตุผลเดียวกันนี้ ฉันไม่รู้ว่ามันจะฟักออกมาเมื่อไหร่เช่นกัน",
  ui_story_5036_50361301_43_dialog_content = "ด้วยขนาดปัจจุบันของไข่ หาก Ouroboros ฟักตัวในตอนนี้... ฉันเกรงว่ามันจะส่งผลกระทบอย่างใหญ่หลวงต่อ Colossus ทั้งหมด",
  ui_story_5036_50361301_44_dialog_content = "หา...?!",
  ui_story_5036_50361301_45_dialog_content = "ไม่ได้หมายความว่าไข่นี้อันตรายพอๆ กับระเบิดเวลาใช่ไหม!",
  ui_story_5036_50361301_46_dialog_content = "แม่นยำ!",
  ui_story_5036_50361301_47_dialog_content = "ซึ่งเป็นเหตุผลที่ฉันตัดสินใจที่จะดูมัน คุณเข้าใจไหม? ไม่ใช่แค่เพื่อคอนเสิร์ต แต่เพื่อชีวิตของเราเช่นกัน",
  ui_story_5036_50361301_48_dialog_content = "และความจริงที่ว่าคุณสามารถสรุปได้หมายความว่าคุณมีความถนัดในการประกอบอาชีพด้านสัตววิทยา PlayerName!",
  ui_story_5036_50361301_49_dialog_content = "พูดว่าอะไรนะ? สนใจที่จะทำงานภายใต้ฉันในฐานะเด็กฝึกงานคนล่าสุดของฉันหรือไม่?",
  ui_story_5036_50361301_50_option_content = "เอาสิ!",
  ui_story_5036_50361301_51_dialog_content = "ฉันต้องยอมรับว่าสัตว์มหัศจรรย์นั้นค่อนข้างน่าสนใจ ไม่ต้องพูดถึง พวกเขาจำนวนมากก็ตกอยู่ในอันตรายเช่นกัน",
  ui_story_5036_50361301_52_dialog_content = "การปกป้องพวกเขาจะเป็นทางเลือกอาชีพที่มีความหมายมาก",
  ui_story_5036_50361301_53_dialog_content = "มุมมองที่ถูกต้องมาก, PlayerName. หรือฉันควรจะพูดว่า ลูกศิษย์ตัวน้อยของฉัน?",
  ui_story_5036_50361301_54_dialog_content = "แต่ฉันกำลังจะบอกคุณตอนนี้ ฉันไม่ปล่อยให้คุณบังคับหรือส่งฉันไปทำธุระฟรีๆ",
  ui_story_5036_50361301_55_dialog_content = "*สะอื้น* นั่นเป็นวิธีที่จะพบเจ้านายของคุณหรือไม่?",
  ui_story_5036_50361301_56_option_content = "ฉันคิดว่าฉันจะผ่าน",
  ui_story_5036_50361301_57_dialog_content = "การวิจัยสัตว์มหัศจรรย์นั้นยอดเยี่ยมและทั้งหมด แต่หลังจากได้พบกับ Fia และ Shira ฉันรู้ทุกอย่างเกี่ยวกับชีวิตในฐานะหนึ่งในลูกศิษย์ของคุณ...",
  ui_story_5036_50361301_58_dialog_content = "ถูกส่งออกไปสืบสวนโดยไม่มีเงิน, ดูแลสัตว์มหัศจรรย์, ดูแลเจ้านายของพวกมัน...",
  ui_story_5036_50361301_59_dialog_content = "นี่มันชีวิตอะไรกันเนี่ย!",
  ui_story_5036_50361301_60_dialog_content = "ทุกสิ่งที่เราทำเพื่อสัตว์มหัศจรรย์นั้นเกิดจากความรักและความเคารพต่อพวกมัน ซึ่งเป็นเหตุผลที่เราไม่ขอสิ่งใดเป็นการแลกเปลี่ยน!",
  ui_story_5036_50361301_61_dialog_content = "แต่ถ้าคุณรู้สึกต่อต้านอย่างรุนแรง ฉันจะไม่พยายามเปลี่ยนใจคุณ",
  ui_story_5036_50361301_62_dialog_content = "ฉันเสียเวลามากที่นี่ ฉันสงสัยว่าคอนเสิร์ตเป็นอย่างไรบ้าง",
  ui_story_5036_50361301_63_dialog_content = "ฉันจะกลับไปบอกให้พวกเขารู้ว่าทุกอย่างเรียบร้อยดี เพื่อที่พวกเขาจะได้ไม่ต้องกังวลเกี่ยวกับเรา",
  ui_story_5036_50361301_64_dialog_content = "แน่นอน! ในกรณีนี้ ฉันจะอยู่ที่นี่และ—",
  ui_story_5036_50361301_65_dialog_content = "ครี—!",
  ui_story_5036_50361301_66_dialog_content = "เสียงอะไรน่ะ?",
  ui_story_5036_50361301_67_dialog_content = "เสียง? เสียงอะไร? คุณแน่ใจว่าคุณไม่ได้ยินสิ่งต่างๆ ใช่ไหม",
  ui_story_5036_50361301_68_dialog_content = "เฮ้ คาร์ลีน? คุณเพิ่งได้ยินเสียงแปลก ๆ หรือไม่?",
  ui_story_5036_50361301_69_dialog_content = "มันฟังดูเหมือนเสียงสัตว์ร้อง",
  ui_story_5036_50361301_70_dialog_content = "งะ...",
  ui_story_5036_50361301_71_dialog_content = "คาร์ลีน! คุณสบายดีไหม?! อะไรนะ...",
  ui_story_5036_50361301_72_dialog_content = "เกิดอะไรขึ้น...? ง่วงจัง...",
  ui_story_5036_50361301_73_dialog_content = "ฟังดูเหมือน...โอโรโบรอส...",
  ui_story_5036_50361301_74_dialog_content = "(ห๊ะ ทำไมฉัน... ง่วงจัง...?)",
  ui_story_5036_50361301_75_dialog_content = "PlayerName? เกิดอะไรขึ้น? รีบออกจากมัน!",
  ui_story_5036_50361301_76_dialog_content = "ดูเหมือนว่าฉันไม่มีทางเลือกอื่นนอกจากใช้ทางเลือกสุดท้ายของฉัน บิก้า! เข้าไปในกระเป๋าของ PlayerName แล้วกิน Nightium ของเขาให้หมด!",
  ui_story_5036_50361301_77_dialog_content = "ไฮ~",
  ui_story_5036_50361301_78_dialog_content = "ห-หา?! ไม่ได้นะ!",
  ui_story_5036_50361301_79_dialog_content = "คุณรู้ไหมว่าฉันทำงานนานแค่ไหนเพื่อบันทึกทั้งหมดนี้!",
  ui_story_5036_50361301_80_dialog_content = "โอ้คนดี คุณตื่นแล้ว",
  ui_story_5036_50361301_81_dialog_content = "เมื่อคืนคุณนอนดึกหรือเปล่า คุณกำลังจะหมดสติ",
  ui_story_5036_50361301_82_dialog_content = "ฮะ? ไม่เลย เมื่อคืนฉันเข้านอนค่อนข้างเร็ว",
  ui_story_5036_50361301_83_dialog_content = "แปลก... ฉันสาบานได้เลยว่าตอนนี้ฉันได้ยินเสียงโอโรโบรอส แล้วจู่ๆ ฉันก็ง่วงนอนมาก...",
  ui_story_5036_50361301_84_dialog_content = "คุณได้ยินคำว่า Ouroboros หรือไม่? ทำไมฉันไม่ได้ยิน",
  ui_story_5036_50361301_85_dialog_content = "ฉันจริงจัง! ถ้าไม่เชื่อก็ฟังต่อไป มันอาจจะร้องออกมาอีกครั้ง!",
  ui_story_5036_50361301_86_dialog_content = "ถ้าคุณพูดอย่างนั้น ฉันจะอุดหู",
  ui_story_5036_50361301_87_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361301_88_dialog_content = "ฉันไม่ได้ยินอะไรเลย น้อยกว่า Ouroboros! คุณต้องได้ยินผิด",
  ui_story_5036_50361301_89_dialog_content = "แต่กลับ...",
  ui_story_5036_50361301_90_dialog_content = "<color=#e8d9bb>กระหน่ำ-</color>",
  ui_story_5036_50361301_91_dialog_content = "ฉันได้ยินอะไรบางอย่างอีกแล้ว! เพียงแต่คราวนี้มันไม่เหมือนกับเสียงร้องของโอโรโบรอส",
  ui_story_5036_50361301_92_dialog_content = "เสียงนั่นน่ะเหรอ?!",
  ui_story_5036_50361301_93_dialog_content = "คุณก็ได้ยินเหมือนกันใช่ไหม?",
  ui_story_5036_50361301_94_dialog_content = "<color=#e8d9bb>ตุ้บ—ตุ้บ—</color>",
  ui_story_5036_50361301_95_dialog_content = "อ๋อ ฉันได้ยินแล้ว ไม่เป็นไร ฉันได้ยินมันดังและชัดเจน",
  ui_story_5036_50361301_96_dialog_content = "มันคือ...เสียงหัวใจ",
  ui_story_5036_50361301_97_dialog_content = "มันมาจากภายในไข่",
  ui_story_5036_50361301_98_dialog_content = "ฮะ? ย-หมายความว่าในที่สุดก็ฟักออกมาแล้วเหรอ?!",
  ui_story_5036_50361301_99_dialog_content = "เพื่อนคนนี้มีช่วงเวลาที่แย่ที่สุด คุณเห็นด้วยไหม",
  ui_story_5036_50361301_100_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5036_50361301_101_dialog_content = "อะไรตอนนี้!",
  ui_story_5036_50361301_102_dialog_content = "ระวัง PlayerName!",
  ui_story_5036_50361301_103_dialog_content = "มีบางอย่างพยายามที่จะทำลายกำแพงที่เราปิดไว้เมื่อคืนนี้!",
  ui_story_5036_50361301_104_dialog_content = "<color=#e8d9bb>ตูม—!!</color>",
  ui_story_5036_50361301_105_dialog_content = "กราาาาาา—!",
  ui_story_5036_50361301_106_dialog_content = "มันคือ Eclipsites วิค!",
  ui_story_5036_50361301_107_dialog_content = "ช่วยเราด้วย เจ้าขนปุยตัวน้อย!",
