  ui_story_5036_50361302_2_dialog_content = "ฉันคิดว่าเรากำจัดพวกมันหมดแล้วเมื่อคืนนี้!",
  ui_story_5036_50361302_3_dialog_content = "ดูเหมือนว่า Eclipsites เหล่านี้มาจากที่ไกลออกไป",
  ui_story_5036_50361302_4_dialog_content = "ดูจากความปั่นป่วนของพวกมันแล้ว ฉันเดาว่ามันน่าจะเกี่ยวข้องกับการฟักไข่ของโอโรโบรอส",
  ui_story_5036_50361302_5_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น เราต้องบอกโกลดีและคนอื่นๆ ทันที!",
  ui_story_5036_50361302_6_dialog_content = "ถ้า Ouroboros เป็นเรื่องเกี่ยวกับฟักจริง ๆ การอยู่บน Colossus จะเป็นอันตรายเกินไปสำหรับเรา!",
  ui_story_5036_50361302_7_dialog_content = "เราต้องรีบกลับมาและอพยพทุกคน!",
  ui_story_5036_50361302_8_dialog_content = "จริงอยู่ที่นี่หมดคำถาม",
  ui_story_5036_50361302_9_dialog_content = "ท้ายที่สุด ห้องนี้อาจชนหัวเราได้เมื่อโอโรโบรอสฟักตัวออกมา",
  ui_story_5036_50361302_10_dialog_content = "ดูเหมือนได้เวลาวิ่งแล้ว!",
  ui_story_5036_50361302_11_dialog_content = "ทางนี้. อย่าแยกทาง!",
  ui_story_5036_50361302_12_dialog_content = "เดี๋ยวก่อน ฉันคิดว่ามีคนสองคนบนพื้นตรงนั้น",
  ui_story_5036_50361302_13_dialog_content = "มันคือไวซ์และคาร์ลีน!",
  ui_story_5036_50361302_14_dialog_content = "รอง! คาร์ลีน! ตื่นนอน!",
  ui_story_5036_50361302_15_dialog_content = "เกิดอะไรขึ้น? ฉันไม่สามารถปลุกพวกเขาได้!",
  ui_story_5036_50361302_16_dialog_content = "นี่อาจเป็นผลงานของ Ouroboros ด้วยหรือไม่?",
  ui_story_5036_50361302_17_dialog_content = "มันอันตรายเกินไปที่จะทิ้งพวกเขาไว้ที่นี่ เราจะต้องแบกพวกเขา",
  ui_story_5036_50361302_18_dialog_content = "เอาล่ะ ปล่อยให้ฉัน ฉันจะได้รับพวกเขา",
  ui_story_5036_50361302_19_dialog_content = "Hrrrrrrrrng—อ๊อฟ!",
  ui_story_5036_50361302_20_dialog_content = "คุณอาจจะพิจารณาการยกน้ำหนักถ้าเราออกจากที่นี่ PlayerName.",
  ui_story_5036_50361302_21_dialog_content = "มันไม่ใช่เวลาอย่างแน่นอน วิค! ช่วยฉันหยิบมันขึ้นมา!",
  ui_story_5036_50361302_22_dialog_content = "ฉันไม่คิดว่าฉันจะช่วยได้มากในเรื่องนี้เช่นกัน อย่างไรก็ตาม-",
  ui_story_5036_50361302_23_dialog_content = "ออกมา เจ้าลูกขนปุยตัวน้อย!",
  ui_story_5036_50361302_24_dialog_content = "จิ๊บ!",
  ui_story_5036_50361302_25_dialog_content = "ใหญ่ขึ้นได้?!",
  ui_story_5036_50361302_26_dialog_content = "อย่างชัดเจน! แต่นั่นก็ไม่ได้ทำให้ขนนุ่มน่ากอดของมันเปลี่ยนไป",
  ui_story_5036_50361302_27_dialog_content = "ฉันไม่สามารถขอเตียงที่ดีกว่านี้สำหรับการงีบหลับยามบ่ายได้! นี่เธออยากสัมผัสมันเหรอ? สัมผัสแรก ฟรี!",
  ui_story_5036_50361302_28_dialog_content = "ม-ไม่แน่ ครั้งหน้า วิค...",
  ui_story_5036_50361302_29_dialog_content = "เอาล่ะ เจ้าเฟอร์บอลน้อย หรือฉันควรจะเรียกว่าบิ๊กเฟอร์บอลดีล่ะ? ฉันต้องการให้คุณพาสองสาวไปที่นั่น",
  ui_story_5036_50361302_30_dialog_content = "เจี๊ยบบบ—!",
  ui_story_5036_50361302_31_dialog_content = "ก้าวต่อไป! เรายังคงต้องเตือนคนอื่นๆ!",
  ui_story_5036_50361302_32_dialog_content = "อ๊ะ ไม่นะ...",
  ui_story_5036_50361302_33_dialog_content = "ดูเหมือนว่าพวกเขาจะหลับกันหมด",
  ui_story_5036_50361302_34_dialog_content = "ผู้หญิงคนนั้นถึงกับสลบบนเวทีคนเดียว",
  ui_story_5036_50361302_35_dialog_content = "...",
  ui_story_5036_50361302_36_dialog_content = "โกลดี้! รีบออกมาโกลดี้!",
  ui_story_5036_50361302_37_dialog_content = "ทำไมฉันไม่สามารถปลุกพวกมันได้เลย...?",
  ui_story_5036_50361302_38_dialog_content = "มีบางอย่างแปลกเกี่ยวกับสภาพของเธอ ดูเหมือนว่าจะเป็นผลงานของ Luminatics",
  ui_story_5036_50361302_39_dialog_content = "คุณคิดว่าพวก Ouroboros ทำแบบนี้ด้วยเหรอ?",
  ui_story_5036_50361302_40_dialog_content = "แต่ถ้าเป็นเช่นนั้นทำไมเราถึงยังตื่นอยู่ในขณะที่คนอื่นอยู่ในอาการโคม่าเช่นนี้?",
  ui_story_5036_50361302_41_dialog_content = "เพราะมีบางสิ่งที่พิเศษเกี่ยวกับเราสองคน",
  ui_story_5036_50361302_42_dialog_content = "คุณเป็น Caelestite คุณมีความสามารถทางจิตที่ไม่เหมือนใคร",
  ui_story_5036_50361302_43_dialog_content = "สำหรับฉัน สายเลือดของฉันมีต้นกำเนิดคล้ายกับโอโรโบรอส นี่อาจเป็นที่มาของภูมิคุ้มกันของฉัน",
  ui_story_5036_50361302_44_dialog_content = "มีวิธีปลุกพวกเขาไหม?",
  ui_story_5036_50361302_45_dialog_content = "ฉันไม่สามารถพูดได้อย่างแน่นอน ไม่",
  ui_story_5036_50361302_46_dialog_content = "แต่จะเป็นไปได้อย่างไร? คุณเพิ่งพูดด้วยตัวเอง: คุณแบ่งปันต้นกำเนิดกับ Ouroboros! คุณต้องมีบางอย่าง",
  ui_story_5036_50361302_47_dialog_content = "ขอโทษนะ แต่นอกจากอายุยืนแล้ว พวกโอโรโบรอสกับฉันไม่มีอะไรเหมือนกันเลย",
  ui_story_5036_50361302_48_dialog_content = "คุณอาจมีช็อตที่ดีกว่า",
  ui_story_5036_50361302_49_dialog_content = "ความสามารถทางจิตของคุณอาจทำให้คุณรู้สึกบางอย่างที่ฉันไม่รู้",
