  ui_story_5036_50361401_2_dialog_content = "เดี๋ยวก่อน นี่คือเอราเวล! ฉันฝันอีกแล้วเหรอ?",
  ui_story_5036_50361401_3_dialog_content = "ครั้งนี้มีบางอย่างที่แตกต่างออกไป ฉากดูชัดเจนกว่าเดิมมาก",
