  ui_story_5036_50361401_5_dialog_content = "เดี๋ยวก่อน อะไรบินอยู่เหนือมัน? คือว่า...",
  ui_story_5036_50361401_6_dialog_content = "มังกร?",
  ui_story_5036_50361401_7_dialog_content = "โอ้ ฉันกำลังฝันอยู่แน่ๆ!",
  ui_story_5036_50361401_8_dialog_content = "แต่อย่างไร? มันเกิดขึ้นได้อย่างไร? มาเลยโกลดี้ คุณต้องตื่น! คอนเสิร์ตยังไม่จบ!",
  ui_story_5036_50361401_9_dialog_content = "พวกเขาบอกว่าการบีบต้นขาของคุณในความฝันจะทำให้คุณตื่น",
  ui_story_5036_50361401_10_dialog_content = "ไปเลย!",
  ui_story_5036_50361401_11_dialog_content = "อีเหี้ย!",
  ui_story_5036_50361401_12_dialog_content = "ทำไมฉันไม่ตื่น! บางทีฉันอาจต้องหยิกตัวเองให้แรงกว่านี้!",
  ui_story_5036_50361401_13_dialog_content = "♪ ลา—ลา ลา ♪",
  ui_story_5036_50361401_14_dialog_content = "เสียงนั้น... ฉันเคยได้ยินมาก่อน! ฟังดูเหมือนสาวคาเลสไทต์คนนั้น ชามินาด!",
  ui_story_5036_50361401_15_dialog_content = "♪ ปีก...เปียกโชก ♪",
  ui_story_5036_50361401_16_dialog_content = "ฉันคิดว่าฉันสามารถแปลเนื้อเพลงของเธอได้ในครั้งนี้",
  ui_story_5036_50361401_17_dialog_content = "ครั้งสุดท้ายฉันไม่ได้ยินอะไรนอกจากทำนองเพลง",
  ui_story_5036_50361401_18_dialog_content = "♪... บ้าน ♪",
  ui_story_5036_50361401_19_dialog_content = "ดูเหมือนว่ามันมาจากที่นั่น",
  ui_story_5036_50361401_20_dialog_content = "♪ สิ่งที่เหลืออยู่คือช่วงเวลาเหล่านั้นในความทรงจำของฉัน ♪",
  ui_story_5036_50361401_21_dialog_content = "♪ หอคอยสีขาวตั้งตระหง่านอย่างภาคภูมิ ♪",
  ui_story_5036_50361401_22_dialog_content = "♪ แต่แสงนำทางนั้นอยู่นอกสายตาของฉัน ♪",
  ui_story_5036_50361401_23_dialog_content = "(ท่วงทำนองฟังดูไพเราะมาก แต่สีหน้าของเธอเต็มไปด้วยความโศกเศร้า...)",
  ui_story_5036_50361401_24_dialog_content = "♪ ท่องไป ท่องไป ดูแผ่นดินและทะเล ♪",
  ui_story_5036_50361401_25_dialog_content = "♪ แต่อย่าลืมบ้านในฝันของคุณ ♪",
  ui_story_5036_50361401_26_dialog_content = "หืม? ฉันไม่นึกเลยว่าจะมีแขกคนอื่นๆ",
  ui_story_5036_50361401_27_dialog_content = "(ห๊ะ?! ฉัน-เธอกำลังพูดกับฉัน?!)",
  ui_story_5036_50361401_28_dialog_content = "(สิ่งนี้ไม่เคยเกิดขึ้นในความฝันครั้งก่อนของฉัน เว้นแต่ว่า... นี่ไม่ใช่ความฝัน?)",
  ui_story_5036_50361401_29_dialog_content = "H-สวัสดี! คุณต้องเป็น Chaminade ฉันชื่อโกลดี้ ฉันเป็นไอดอล!",
  ui_story_5036_50361401_30_dialog_content = "อืม? คุณรู้จักชื่อของฉันไหม",
  ui_story_5036_50361401_31_dialog_content = "แน่นอนฉันทำ! เพื่อนของฉัน PlayerName เป็นชาวคาเลสไทต์ด้วย! เขาใช้พลังจิตเห็นความทรงจำในอดีตของคุณ",
  ui_story_5036_50361401_32_dialog_content = "อย่างนั้นเหรอ? ฮี่ฮี่ น่าอายนิดหน่อย",
  ui_story_5036_50361401_33_dialog_content = "ถามหน่อยว่า \"ไอดอล\" คืออะไรกันแน่?",
  ui_story_5036_50361401_34_dialog_content = "ไอดอลคือคนที่ใช้พลังของดนตรีเพื่อนำความสุขและความหวังมาสู่ผู้อื่น ฉันเป็นไอดอลมืออาชีพ!",
  ui_story_5036_50361401_35_dialog_content = "ที่น่าตื่นตาตื่นใจ! ฉันอยากเป็นไอดอลด้วย!",
  ui_story_5036_50361401_36_dialog_content = "เรายินดีที่จะแบ่งปันคำแนะนำกับคุณหากคุณต้องการ โอ้ แต่ตอนนี้ไม่ใช่เวลาที่ดี ฉันต้องกลับไปที่คอนเสิร์ตและแสดงให้เสร็จ!",
  ui_story_5036_50361401_37_dialog_content = "คุณรู้ไหมว่าฉันจะออกไปจากที่นี่ได้อย่างไร Chaminade?",
  ui_story_5036_50361401_38_dialog_content = "ฉันขอโทษ... แต่ฉันไม่รู้จะออกจากที่นี่ยังไง",
  ui_story_5036_50361401_39_dialog_content = "ยังไงฉันก็ไม่มีทางออกไปจากที่นี่ได้เหมือนกัน",
  ui_story_5036_50361401_40_dialog_content = "ไม่มีทางออก?",
  ui_story_5036_50361401_41_dialog_content = "(ก็สมเหตุสมผลดีเพราะตัวจริงของเธออยู่แล้ว...)",
  ui_story_5036_50361401_42_dialog_content = "(เดี๋ยวก่อน ถ้า Chaminade ตัวจริงตายไปแล้ว... แล้วใครหรืออะไรที่อยู่ข้างหน้าฉัน?)",
  ui_story_5036_50361401_43_dialog_content = "อืม ไม่เป็นไร!",
  ui_story_5036_50361401_44_dialog_content = "ตราบใดที่เราค้นหา เราก็จะเจอ!",
  ui_story_5036_50361401_45_dialog_content = "<color=#e8d9bb>ขัดข้อง—</color>",
  ui_story_5036_50361401_46_dialog_content = "ฮะ? นั่นเสียงอะไร?",
  ui_story_5036_50361401_47_dialog_content = "มันคือพวกเขา!",
  ui_story_5036_50361401_48_dialog_content = "พวกเขากำลังมา! เราต้องออกไปจากที่นี่!",
  ui_story_5036_50361401_49_dialog_content = "\"พวกเขา\"? คุณกำลังพูดถึงใคร",
  ui_story_5036_50361401_50_dialog_content = "สุริยุปราคา!",
  ui_story_5036_50361401_51_dialog_content = "กราาาาาา—!",
  ui_story_5036_50361401_52_dialog_content = "โอ้ เธอไม่ได้ล้อเล่น! ทำไมมีเยอะจัง!",
  ui_story_5036_50361401_53_dialog_content = "กร๊ากกก—!",
  ui_story_5036_50361401_54_dialog_content = "พวกเขามาจากไหน!",
  ui_story_5036_50361401_55_dialog_content = "พวกมันกำลังจะกลับมาอีกครั้ง โกลดี้! รีบซ่อน!",
  ui_story_5036_50361401_56_dialog_content = "ไม่มีที่ให้ซ่อน ไม่ใช่กับพวกเขาจำนวนมากนี้ ทางเลือกเดียวของเราคือสู้!",
  ui_story_5036_50361401_57_dialog_content = "ฉันจะไม่ปล่อยให้ Eclipsites ของคุณอาละวาดอีกต่อไป!",
  ui_story_5036_50361402_1_dialog_content = "อ๊อฟ—!",
  ui_story_5036_50361402_2_dialog_content = "ยี้! ไม่มีที่สิ้นสุดสำหรับพวกเขา! เราไม่สามารถเอาชนะพวกเขาได้ทั้งหมด!",
  ui_story_5036_50361402_3_dialog_content = "กรี้ด!",
  ui_story_5036_50361402_4_dialog_content = "อ๊าาา!",
  ui_story_5036_50361402_5_dialog_content = "ลืมฉันแล้วหนีไปซะ! พวกมันจะหายไปในเร็วๆ นี้ ดังนั้นอยู่ห่างๆ ไว้ก่อน!",
  ui_story_5036_50361402_6_dialog_content = "หา หมายความว่ายังไง",
  ui_story_5036_50361402_7_dialog_content = "ครี—",
  ui_story_5036_50361402_8_dialog_content = "ครี—!",
  ui_story_5036_50361402_9_dialog_content = "มังกร...เรืองแสง!?",
  ui_story_5036_50361402_10_dialog_content = "แจ่มมาก! ฉันไม่เห็นอะไรเลย—!",
  ui_story_5036_50361402_11_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5036_50361402_12_dialog_content = "ต้องเดินหน้าต่อไป Eclipsites อยู่ข้างหลังแล้ว... ฮะ? W-สุริยุปราคาไปที่ไหน?",
  ui_story_5036_50361402_13_dialog_content = "พวกเขาหายไปแล้ว ทุกอย่างเรียบร้อยดี",
  ui_story_5036_50361402_13X1_dialog_content = "Ouroboros ทำให้พวกเขาหายไปทั้งหมด!",
  ui_story_5036_50361402_13X2_dialog_content = "ใช่ ฉันยังไม่ได้แนะนำให้คุณรู้จักเลยใช่ไหม อยู่นั่น เจ้าตัวเล็กบินอยู่บนฟ้าเบื้องบน!",
  ui_story_5036_50361402_14_dialog_content = "ไปแล้ว? คุณหมายถึงแสงของ Ouroboros กำจัดพวกเขา?",
  ui_story_5036_50361402_15_dialog_content = "ไม่ มันไม่แข็งแรงพอที่จะทำเช่นนั้น สิ่งที่ทำก็แค่เริ่มต้นความฝันนี้ใหม่อีกครั้ง",
  ui_story_5036_50361402_16_dialog_content = "นี่จึงเป็นความฝันจริงๆ!",
  ui_story_5036_50361402_17_dialog_content = "ใช่แล้ว. ความฝันที่สร้างโดย Ouroboros",
  ui_story_5036_50361402_18_dialog_content = "ในเมื่อเพื่อนของคุณเป็นชาวคาเลสไทต์ คุณคงเห็นแล้วว่าเกิดอะไรขึ้นกับฉัน...",
  ui_story_5036_50361402_19_dialog_content = "นั่นสิ...",
  ui_story_5036_50361402_20_dialog_content = "หลังจากรู้สึกว่าฉันตายเพื่อปกป้องมัน พวก Ouroboros ก็เศร้าโศกเสียใจ",
  ui_story_5036_50361402_21_dialog_content = "มันสัมผัสได้ถึงความปรารถนาสุดท้ายของหัวใจที่จะกลับบ้านของฉัน ดังนั้นมันจึงสร้าง Eraveil ขึ้นมาในโลกแห่งความฝัน และตัวฉันเอง",
  ui_story_5036_50361402_22_dialog_content = "แต่เนื่องจากความปรารถนาของมันเองที่ไม่ยอมละทิ้งความฝันนี้ เหล่า Ouroboros จึงบังคับตัวเองให้หลับใหลอย่างไม่มีที่สิ้นสุด",
  ui_story_5036_50361402_23_dialog_content = "จากนั้น Eclipsites เหล่านั้นก็—",
  ui_story_5036_50361402_24_dialog_content = "พวกเขาคือความกลัวของฉัน",
  ui_story_5036_50361402_25_dialog_content = "มันเป็นอาการของความกลัวที่ฉันรู้สึกในช่วงเวลาสุดท้ายของฉัน นั่นเป็นเหตุผลที่พวกมันปรากฏตัวและโจมตีฉันตลอดเวลา",
  ui_story_5036_50361402_26_dialog_content = "แต่ไม่เป็นไร เพราะพวกโอโรโบรอสกำลังปกป้องฉันอยู่ เมื่อพวกเขากำลังจะจับตัวฉัน มันก็รีเซ็ตความฝันและทำให้พวกเขาหายไป!",
  ui_story_5036_50361402_27_dialog_content = "เดี๋ยวก่อน บางทีคุณอาจขอให้ Ouroboros ช่วยคุณออกไปได้ไหม?",
  ui_story_5036_50361402_28_dialog_content = "ความคิดที่ดี! ฉันจะไปถามมันเดี๋ยวนี้!",
  ui_story_5036_50361402_29_dialog_content = "ตกลง! แต่ก่อนจะไป คุณช่วยอยู่คุยกับฉันอีกหน่อยได้ไหม?",
  ui_story_5036_50361402_30_dialog_content = "ฉันชอบ Chaminade ฉันจะทำจริงๆ แต่แฟนๆของฉันยังรอฉันอยู่ข้างนอกนั่น",
  ui_story_5036_50361402_31_dialog_content = "ใช้เวลาไม่นาน ฉันสัญญา! ฉันแค่มีคำถามเล็กๆ น้อยๆ ว่าโอเคไหม?",
  ui_story_5036_50361402_32_dialog_content = "แน่นอนอยู่แล้ว! มันคืออะไร?",
  ui_story_5036_50361402_33_dialog_content = "Eraveil มีลักษณะอย่างไรในปัจจุบัน",
  ui_story_5036_50361402_34_dialog_content = "โปรดบอกฉัน! ฉันอยากรู้อยากเห็น",
  ui_story_5036_50361402_35_dialog_content = "อืม... เอเรวิล?",
  ui_story_5036_50361402_36_dialog_content = "ฉันขอโทษ แต่ฉันไม่เคยไปที่นั่นมาก่อน...",
  ui_story_5036_50361402_37_dialog_content = "โอ๊ะ...",
  ui_story_5036_50361402_38_dialog_content = "แต่อย่าเพิ่งใจอ่อน! แม้ว่าฉันจะไม่เคยไปที่นั่นด้วยตัวเอง แต่ฉันมีเพื่อนชาวคาเลสไทต์ที่ไว้ใจได้อาศัยอยู่ที่นั่น!",
  ui_story_5036_50361402_39_dialog_content = "คุณหมายถึง Caelesite ที่คุณพูดถึงก่อนหน้านี้?",
  ui_story_5036_50361402_40_dialog_content = "ถูกตัอง! ชื่อของเขาคือ PlayerNameและเขาเป็นคนที่น่าทึ่งที่สุดคนหนึ่งที่ฉันเคยพบมา!",
  ui_story_5036_50361402_41_dialog_content = "ก่อนที่ฉันจะได้พบเขา ทั้งหมดที่ฉันรู้ก็คือเขาเป็นนักบินของ Caelesite ของยักษ์ใหญ่ที่เดินทางไปทั่วโลก",
  ui_story_5036_50361402_42_dialog_content = "ตลอดการเดินทางของเขา เขาได้รู้จักเพื่อนมากมายและผ่านการผจญภัยมากมาย เขายังเอาชนะ Eclipsites มากกว่าที่ฉันจะนับได้!",
  ui_story_5036_50361402_43_dialog_content = "ฉันเคยอิจฉาชีวิตของเขามาก สำหรับฉัน มันเหมือนกับว่าเขามีชีวิตที่มีอิสระสูงสุด",
  ui_story_5036_50361402_44_dialog_content = "แต่หลังจากที่ฉันได้รู้จักตัวจริงของเขา ฉันได้เรียนรู้ว่าชีวิตของเขาลำบากเพียงใด",
  ui_story_5036_50361402_45_dialog_content = "ในช่วงปีแรก ๆ ของชีวิตเขาใช้ชีวิตใต้ดินเพียงลำพัง จนกระทั่งเขาพบเพื่อนคนแรกของเขาในที่สุดเขาก็เห็นแสงสว่างของวัน",
  ui_story_5036_50361402_46_dialog_content = "เขาเป็นคนสุดท้ายของ Caelestites และเขายังสร้าง Eraveil ขึ้นใหม่จากซากปรักหักพัง",
  ui_story_5036_50361402_47_dialog_content = "ว่าไง",
  ui_story_5036_50361402_48_dialog_content = "คุณหมายถึงอะไร Eraveil... ถูกทำลาย? เหลือเพียง...",
  ui_story_5036_50361402_49_dialog_content = "อา! ไม่ ฉันไม่ได้หมายความอย่างนั้น! สิ่งที่ฉันตั้งใจจะพูด—",
  ui_story_5036_50361402_50_dialog_content = "ฉัน... บ้านของฉันถูกทำลาย...",
  ui_story_5036_50361402_51_dialog_content = "Eraveil... Eraveil หายไปจริงเหรอ?",
  ui_story_5036_50361402_52_dialog_content = "แต่อย่างไร? เป็นไปได้ยังไงเนี่ย?!",
  ui_story_5036_50361402_53_dialog_content = "<color=#e8d9bb>พลัก!</color>",
  ui_story_5036_50361402_54_dialog_content = "<color=#e8d9bb>แตก-!</color>",
  ui_story_5036_50361402_55_dialog_content = "ความฝันเริ่มสลาย! เป็นเพราะอารมณ์ของ Chaminade หรือเปล่า?",
  ui_story_5036_50361402_56_dialog_content = "ชามินาด! P-โปรดใจเย็นๆ!",
  ui_story_5036_50361402_57_dialog_content = "บ้านของฉัน... ฉันแค่อยากกลับบ้าน... อะแฮ่ม!",
  ui_story_5036_50361402_58_dialog_content = "เธอไม่สงบลงเลย...",
  ui_story_5036_50361402_59_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_5036_50361402_60_dialog_content = "ครี! ครี—!",
  ui_story_5036_50361402_61_dialog_content = "ความฝันเริ่มพังทลายมากขึ้นเรื่อยๆ แต่ทำไมมันไม่รีเซ็ต?",
  ui_story_5036_50361402_62_dialog_content = "โอ้ ฉันควรทำอย่างไร บางทีฉันควรจะเริ่มนับและข้ามเจ็ดทั้งหมด จะมีอะไรดีๆเกิดขึ้นไหม?",
  ui_story_5036_50361402_63_dialog_content = "ไม่... ตอนนี้ไม่ใช่เวลามายืนเฉยๆ! อย่างน้อยก็ต้องไปให้พ้นจากฝันที่แหลกสลาย!",
  ui_story_5036_50361402_64_dialog_content = "หอคอยตรงนั้นยังดูเหมือนอยู่ในสภาพดี นอกจากนี้ยังเป็นสถานที่ที่ใกล้ที่สุดกับ Ouroboros",
  ui_story_5036_50361402_65_dialog_content = "ไปกันเถอะ Chaminade—อ๊ะ!",
  ui_story_5036_50361402_66_dialog_content = "ฮือ ๆ ๆ",
  ui_story_5036_50361402_67_dialog_content = "โอ๊ย เธอไม่ให้ฉันเข้าใกล้เธอ!",
  ui_story_5036_50361402_68_dialog_content = "ชามินาด! ชามินาด! ต้องใจเย็น!!!",
  ui_story_5036_50361402_69_dialog_content = "เธอไม่ฟังฉันเลย...",
  ui_story_5036_50361402_70_dialog_content = "หากยังเป็นเช่นนี้ต่อไป ความฝันทั้งหมดจะพังทลายลงรอบตัวเรา!",
  ui_story_5036_50361402_71_dialog_content = "ฉันต้องหาทางแก้ไขความฝันนี้ให้ได้!",
  ui_story_5036_50361402_72_dialog_content = "ฉันแค่หวังว่า Ouroboros จะรู้ว่าต้องทำอะไร!",
  ui_story_5036_50361402_73_dialog_content = "หอคอยนี้ดูเหมือนไม่มีที่สิ้นสุด! ฉันยังไม่ถึงจุดสูงสุดได้อย่างไร",
  ui_story_5036_50361402_74_dialog_content = "ที่นี่เป็นสถานที่แบบไหน? มันช่างมืดมนและว่างเปล่า",
  ui_story_5036_50361402_75_dialog_content = "ไม่! ฉันปล่อยให้ความกลัวความมืดหยุดฉันไม่ได้แล้ว!",
  ui_story_5036_50361402_76_dialog_content = "กรร...",
  ui_story_5036_50361402_77_dialog_content = "ดูเหมือนว่าที่นี่จะไม่ปลอดภัยจาก Eclipsites",
  ui_story_5036_50361402_78_dialog_content = "ฉันเดาว่ามันสมเหตุสมผล เป็นจุดศูนย์กลางของความฝัน เป็นที่ที่มั่นคงที่สุด",
  ui_story_5036_50361402_79_dialog_content = "แม้แต่ Eclipsites ก็ยังรู้ว่าต้องหนีจากอันตราย ดูเหมือนว่า",
  ui_story_5036_50361402_80_dialog_content = "ฉันไม่มีเวลามาเสียกับพวกเขาหรอก ฉันต้องไปถึงจุดสูงสุดให้ได้!",
  ui_story_5036_50361402_81_dialog_content = "แสงสว่างข้างหน้าต้องเป็นทางออก",
  ui_story_5036_50361402_82_dialog_content = "ในที่สุด!",
  ui_story_5036_50361402_83_dialog_content = "ครี ครี!",
  ui_story_5036_50361402_84_dialog_content = "มันคือโอโรโบรอส! เฮ้!",
  ui_story_5036_50361402_85_dialog_content = "คุณช่วยแก้ไขความฝันและทำให้ Chaminade สงบลงได้ไหม?",
  ui_story_5036_50361402_86_dialog_content = "ครี...",
  ui_story_5036_50361402_87_dialog_content = "(มันดูเป็นห่วง มันพยายามจะบอกว่าช่วยไม่ได้ด้วยเหรอ?)",
  ui_story_5036_50361402_88_dialog_content = "(ฉันควรทำอย่างไรดีตอนนี้?!)",
  ui_story_5036_50361402_89_dialog_content = "<color=#e8d9bb>ตูมม!!!</color>",
  ui_story_5036_50361402_90_dialog_content = "ฟ้ายังเริ่มสลาย!!",
  ui_story_5036_50361402_91_dialog_content = "ครี! ครี—!",
  ui_story_5036_50361402_92_dialog_content = "พวกโอโรโบรอสดูเหมือนจะเจ็บปวดมาก...",
  ui_story_5036_50361402_93_dialog_content = "<color=#e8d9bb>ตูม—!</color>",
  ui_story_5036_50361402_94_dialog_content = "อ่า! T-หอคอยเริ่มถล่ม!",
  ui_story_5036_50361402_95_dialog_content = "อ๊ากกก—!!!",
  ui_story_5036_50361402_96_dialog_content = "โกลดี้! จับมือฉัน!",
  ui_story_5036_50361402_97_dialog_content = "PlayerName!?",
  ui_story_5036_50361402_98_dialog_content = "คุณมานี่ได้ยังไงเนี่ย!?",
  ui_story_5036_50361402_99_dialog_content = "เราสังเกตเห็นว่ามีบางอย่างผิดปกติเกี่ยวกับไข่ Ouroboros เราจึงกลับไปที่เวทีเพื่อตรวจสอบ",
  ui_story_5036_50361402_100_dialog_content = "แต่เมื่อเรากลับไปที่คอนเสิร์ต ทุกคนสลบ! ไม่เพียงเท่านั้น ยังมีร่องรอยของแสงแห่งโอโรโบรอสรอบๆ ร่างที่หมดสติของคุณ",
  ui_story_5036_50361402_101_dialog_content = "ในที่สุด Ouroboros ก็ฟักออกมา? แต่ทำไมตอนนี้ตลอดเวลา?!",
  ui_story_5036_50361402_102_dialog_content = "เป็นไปได้ว่ามันจะฟักออกมาหลังจากได้ยินเพลงของคุณ",
  ui_story_5036_50361402_103_dialog_content = "การเขียนเพลงของคุณด้วยท่วงทำนองที่ใช้ในการกระตุ้น Colossi คุณอาจปลุกให้ Ouroboros ตื่นโดยไม่ได้ตั้งใจ!",
  ui_story_5036_50361402_104_dialog_content = "อะไรนะ!",
  ui_story_5036_50361402_105_dialog_content = "ถ้ามัวแต่เอือมระอา มือฉันคงจับต่อไปไม่ไหว...",
  ui_story_5036_50361402_106_dialog_content = "รอ! อย่าปล่อย!!!",
  ui_story_5036_50361402_107_dialog_content = "ฮ่าฮ่าฮ่า! ฉันแค่ล้อเล่น! คุณคิดว่าฉันไม่น่าเชื่อถือจริงๆเหรอ?",
  ui_story_5036_50361402_108_dialog_content = "เอาล่ะ ลากเธอออกไปจากที่นี่เดี๋ยวนี้!",
  ui_story_5036_50361402_109_dialog_content = "จับให้แน่น โกลดี้!",
  ui_story_5036_50361402_110_dialog_content = "อ๊าาา!",
  ui_story_5036_50361402_111_dialog_content = "ฉันตื่นแล้ว!",
  ui_story_5036_50361402_112_dialog_content = "เธอไม่เป็นไรนะ",
  ui_story_5036_50361402_113_dialog_content = "ใช่ หัวของฉันรู้สึกวิงเวียนนิดหน่อย...",
  ui_story_5036_50361402_114_dialog_content = "ในที่สุด... ในที่สุดฉันก็... หะ? ฉ-ฉันฝันไปรึเปล่า?!",
  ui_story_5036_50361402_115_dialog_content = "เอ่อ... เกิดอะไรขึ้น?",
  ui_story_5036_50361402_116_dialog_content = "หัวของฉัน... เราหลับไปหรือเปล่า?",
  ui_story_5036_50361402_117_dialog_content = "ย่า—ว. สวัสดีตอนเช้า...? หรือฉันควรจะทักทายตอนเย็นดี?",
  ui_story_5036_50361402_118_dialog_content = "นี่ฉันเผลอหลับไปข้างสามัญชนพวกนี้จริงๆ เหรอ! อั๊ยยะ ฉันจะต้องเผาชุดนี้เมื่อกลับถึงบ้าน...",
  ui_story_5036_50361402_119_dialog_content = "ดูเหมือนทุกคนจะเริ่มรู้สึกตัวแล้ว!",
  ui_story_5036_50361402_120_dialog_content = "เป็นเพราะความฝันกลับมาเป็นปกติหรือไม่?",
  ui_story_5036_50361402_121_dialog_content = "ไม่ เป็นเพราะ...",
  ui_story_5036_50361402_122_dialog_content = "Ouroboros กำลังจะฟักไข่",
  ui_story_5036_50361501_1_dialog_content = "<color=#e8d9bb>Umbraton บนฝั่งแม่น้ำโกลด์</color>",
  ui_story_5036_50361501_2_dialog_content = "เฮ้ เกิดอะไรขึ้นบนนั้น? นักแสดงประเภทไหนเผลอหลับระหว่างแสดง?!",
  ui_story_5036_50361501_3_dialog_content = "ฉันสงสัยว่าเธอสบายดีไหม",
  ui_story_5036_50361501_4_dialog_content = "ไม่ต้องกังวล! ฉันแน่ใจว่าเธอสบายดี เธอแข็งแกร่งมาก!",
  ui_story_5036_50361501_5_dialog_content = "ไอ้บ้าสองคนนั้นทำอะไรกันบนเวที?",
  ui_story_5036_50361501_6_dialog_content = "ช่างเป็นการหลอกลวง ฉันจะไม่เสียเวลาที่นี่อีกแล้ว",
  ui_story_5036_50361501_7_dialog_content = "สักครู่ครับท่าน",
  ui_story_5036_50361501_8_dialog_content = "ยังเร็วเกินไปที่จะจากไป เพราะทุกสิ่งที่คุณเห็นเป็นส่วนหนึ่งของการแสดง",
  ui_story_5036_50361501_9_dialog_content = "ว่าไง",
  ui_story_5036_50361501_10_dialog_content = "เราพยายามอย่างมากในการวางแผนเอฟเฟ็กต์พิเศษทั้งหมด แค่ร้องกับเต้นก็น่าเบื่อแล้ว ว่าไหม?",
  ui_story_5036_50361501_11_dialog_content = "เราได้เตรียมเซอร์ไพรส์มากมายเพื่อเติมเต็มการแสดงและทำให้น่าตื่นเต้นที่สุดเท่าที่จะเป็นไปได้ เพื่อความสุขในการรับชมของคุณ",
  ui_story_5036_50361501_12_dialog_content = "ฉันหวังว่าทุกคนจะอยู่ต่ออีกสักพักและสนุกไปกับการแสดง ฉันสัญญาว่าจะไม่ทำให้ผิดหวัง",
  ui_story_5036_50361501_13_dialog_content = "ตกลง เราจะทำตามที่คุณพูดในตอนนี้",
  ui_story_5036_50361501_14_dialog_content = "ขอบคุณสำหรับความเข้าใจและการสนับสนุนของคุณ! เรายังเตรียมอาหารว่างและเครื่องดื่มสำหรับทุกคน",
  ui_story_5036_50361501_15_dialog_content = "โปรดช่วยตัวเอง",
  ui_story_5036_50361501_16_dialog_content = "(ตอนนี้ฉันได้ควบคุมฝูงชนแล้ว แต่จะไม่นานกว่านี้)",
  ui_story_5036_50361501_17_dialog_content = "(เกิดอะไรขึ้นบนนั้น โกลดี้?)",
  ui_story_5036_50361501_18_dialog_content = "(PlayerName และเพื่อนของเขาก็อยู่บนนั้นเช่นกัน... ฉันแค่หวังว่าพวกเขาจะไม่ตกอยู่ในอันตราย...)",
  ui_story_5036_50361501_19_dialog_content = "<color=#e8d9bb>ในขณะเดียวกันบน Eulogoz</color>",
  ui_story_5036_50361501_20_dialog_content = "อะไร Ouroboros กำลังฟักไข่?!",
  ui_story_5036_50361501_21_dialog_content = "ฉันรู้ว่ามันกะทันหัน แต่เราไม่มีเวลาอธิบาย",
  ui_story_5036_50361501_22_dialog_content = "หากโอโรโบรอสฟักตัวออกมา มันจะทำให้ยักษ์ใหญ่ทั้งหมดนี้เสียสมดุลและทำให้เราทุกคนตกอยู่ในอันตราย",
  ui_story_5036_50361501_23_dialog_content = "สิ่งที่เราให้ความสำคัญสูงสุดในตอนนี้คือการอพยพทุกคนบนเรือ!",
  ui_story_5036_50361501_24_dialog_content = "และเราควรทำมันโดยเร็ว หรือ... เอ่อ... ดูเหมือนว่าเราจะสายเกินไปแล้ว",
  ui_story_5036_50361501_25_dialog_content = "กร๊ากกก—!!!",
  ui_story_5036_50361501_26_dialog_content = "Eclipsites กำลังไหลออกมาจากภายในยักษ์ใหญ่!",
  ui_story_5036_50361501_27_dialog_content = "ตื่นได้แล้วทุกคน! เข้ารับตำแหน่งป้องกัน!",
  ui_story_5036_50361501_28_dialog_content = "ครับ ท่านหญิง!",
  ui_story_5036_50361501_29_dialog_content = "ฮึบบบบ!",
  ui_story_5036_50361501_30_dialog_content = "คุณจะไม่ผ่านฉันไป!",
  ui_story_5036_50361501_31_dialog_content = "เวร! สิ่งมีชีวิตที่สกปรกเหล่านี้ไม่มีที่สิ้นสุดหรือไม่!",
  ui_story_5036_50361501_32_dialog_content = "บ่นพอแล้ว มุ่งเน้นไปที่การป้องกัน",
  ui_story_5036_50361501_33_dialog_content = "ใช่ ใช่ ฉันรู้!",
  ui_story_5036_50361501_34_dialog_content = "<color=#e8d9bb>ครืนนน...</color>",
  ui_story_5036_50361501_35_dialog_content = "ยักษ์ใหญ่ทั้งหมดสั่นสะเทือน! บอสตัวสุดท้ายกำลังจะปรากฎตัว?!",
  ui_story_5036_50361501_36_dialog_content = "สู้ๆ นะทุกคน! ดูเหมือนว่ามีบางอย่างออกมาจาก Colossus!",
  ui_story_5036_50361501_37_dialog_content = "ครี—!",
  ui_story_5036_50361501_38_dialog_content = "มังกร?! มันใหญ่มาก!!",
  ui_story_5036_50361501_39_dialog_content = "มันฟักออกมาจริงๆ!",
  ui_story_5036_50361501_40_dialog_content = "กร๊าาาาซ!",
  ui_story_5036_50361501_41_dialog_content = "Eclipsites กำลังเริ่มโจมตี Ouroboros!",
  ui_story_5036_50361501_42_dialog_content = "ครี—ครี—!",
  ui_story_5036_50361501_43_dialog_content = "ดูสิพี่สาว! ที่ด้านบนสุดของยักษ์ใหญ่!",
  ui_story_5036_50361501_44_dialog_content = "นั่นมัน...มังกรเหรอ!",
  ui_story_5036_50361501_45_dialog_content = "เฮ้! ยักษ์ใหญ่กำลังสั่นอย่างหนัก มันจะตกลงมาจากท้องฟ้า!",
  ui_story_5036_50361501_46_dialog_content = "<color=#e8d9bb>ตูม!!!</color>",
  ui_story_5036_50361501_47_dialog_content = "นี้ไม่ดี! Ouroboros เพิ่งฟักไข่ ยังบินไม่ได้!",
  ui_story_5036_50361501_48_dialog_content = "การโจมตีของ Eclipsites จะทำให้การต่อสู้รุนแรงยิ่งขึ้น!",
  ui_story_5036_50361501_49_dialog_content = "มีวิธีใดที่จะทำให้สงบลงก่อน?",
  ui_story_5036_50361501_50_dialog_content = "หรือว่านายจะใช้พลังจิตดีล่ะ?",
