  ui_story_5036_50361501_52_option_content = "“หยุดนะ โอโรโบรอส!”",
  ui_story_5036_50361501_53_dialog_content = "ครี—!",
  ui_story_5036_50361501_54_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5036_50361501_55_dialog_content = "อ๊ะ!",
  ui_story_5036_50361501_56_dialog_content = "มันจะไม่ฟังฉันเลย!",
  ui_story_5036_50361501_57_dialog_content = "Eclipsites ได้... ล้อมรอบเวที",
