  ui_story_5036_50361501_68_dialog_content = "ได้เลย!",
  ui_story_5036_50361501_69_dialog_content = "อัศวินแห่ง Lumopolis นั้นไว้ใจได้ในยามอันตรายเช่นนี้!",
  ui_story_5036_50361501_70_dialog_content = "คุณไม่มีสิ่งที่ต้องทำ? หาทางทำให้มังกรสงบลง",
  ui_story_5036_50361501_71_dialog_content = "ปล่อยฉัน ฉันไม่ใช่นักสู้...",
  ui_story_5036_50361501_72_dialog_content = "คุณ... ไม่เป็นไร อพยพกับส่วนที่เหลือแล้ว",
  ui_story_5036_50361501_73_dialog_content = "ไม่มีปัญหา. เดี๋ยวผมดูออกเอง",
  ui_story_5036_50361501_74_dialog_content = "ทุกคน มาทางนี้!",
  ui_story_5036_50361501_75_dialog_content = "โซรอซ เป็นยังไง? PlayerName?",
  ui_story_5036_50361501_76_dialog_content = "Ouroboros ไม่สงบลง โซรอซโยงไม่ได้!",
  ui_story_5036_50361501_77_dialog_content = "ถ้ามีวิธีทำให้มันสงบลงได้แม้แต่วินาทีเดียว...",
  ui_story_5036_50361501_78_dialog_content = "แต่ดูเหมือนว่าจะไม่ทำเช่นนั้น อย่างน้อยก็ไม่นาน",
  ui_story_5036_50361501_79_dialog_content = "เรือเหาะ Lumopolis อยู่ที่ไหน",
  ui_story_5036_50361501_80_dialog_content = "เห็นได้ชัดว่าฉันได้ติดต่อพวกเขาแล้ว",
  ui_story_5036_50361501_81_dialog_content = "คอนเสิร์ตได้ดึงดูดขุนนางสองสามคนด้วยเรือบินของพวกเขา หลายคนกำลังช่วยอพยพอยู่แล้ว",
  ui_story_5036_50361501_82_dialog_content = "City Lord กำลังส่งเรือเหาะทั้งหมดที่มีใน Lumopolis มาที่นี่ แต่คงต้องใช้เวลาสักระยะ",
  ui_story_5036_50361501_83_dialog_content = "ไม่ต้องพูดถึง Lumopolis มีเพียงเรือบินขนาดเล็กบ่อยกว่าไม่ ต้องใช้เวลาหลายเที่ยวในการข้ามฟากผู้คนทั้งหมดออกจากที่นี่",
  ui_story_5036_50361501_84_dialog_content = "เราต้องซื้อเวลาให้พวกเขามากขึ้น",
  ui_story_5036_50361501_85_dialog_content = "เอื้อออ—!",
  ui_story_5036_50361501_X85_dialog_content = "ยืนหยัด!",
  ui_story_5036_50361501_87_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5036_50361501_88_dialog_content = "เลดี้คาร์ลีน มี Eclipsites มากเกินไป! เราไม่สามารถรักษาเส้นของเราได้!",
  ui_story_5036_50361501_89_dialog_content = "อา ทุกคนจากลูโมโพลิส เราควรหนีจากที่นั่นดีกว่า!",
  ui_story_5036_50361501_90_dialog_content = "มังกรดิ้นรนอย่างรุนแรงเกินไป และยักษ์ใหญ่ก็แก่เกินไป—",
  ui_story_5036_50361501_91_dialog_content = "หลายส่วนของมันรับไม่ไหว มันเริ่มจะพังทลายแล้ว!",
  ui_story_5036_50361501_92_dialog_content = "เรือบินอยู่ที่ไหน",
  ui_story_5036_50361501_93_dialog_content = "รายงาน! Soroz ไม่สามารถเชื่อมต่อได้ แต่เรือบินจาก Lumopolis กำลังมา!",
  ui_story_5036_50361501_94_dialog_content = "เราหมดทางเลือกแล้ว! ติดต่อทุกทีมเพื่อเบิกคืน หยุดปกป้อง Ouroboros ในตอนนี้และมุ่งไปหาผู้คน!",
  ui_story_5036_50361501_95_dialog_content = "ได้เลยค่ะ",
  ui_story_5036_50361501_96_dialog_content = "คาร์ลีน!",
  ui_story_5036_50361501_97_dialog_content = "ฉันสบายดี ทุกคนอยู่ที่นี่ไหม",
  ui_story_5036_50361501_98_dialog_content = "พวกเขาทั้งหมดอยู่ที่นี่ เลดี้คาร์ลีน!",
  ui_story_5036_50361501_99_dialog_content = "เรือบินชุดแรกมาแล้ว การอพยพกำลังดำเนินการ แต่...",
  ui_story_5036_50361501_100_dialog_content = "มันต้องใช้เวลา",
  ui_story_5036_50361501_101_dialog_content = "เรือบินเล็กเกินไป คนมากเกินไป",
  ui_story_5036_50361501_102_dialog_content = "ฉันจะทำให้ดีที่สุดเพื่อซื้อเวลาของคุณ",
  ui_story_5036_50361501_103_dialog_content = "รีบ! ยักษ์ใหญ่อาจพลิกคว่ำได้ทุกเมื่อ!",
  ui_story_5036_50361501_104_dialog_content = "สะอื้น... ฉัน...",
  ui_story_5036_50361501_105_dialog_content = "คุณสบายดีไหม โกลดี้?",
  ui_story_5036_50361501_106_dialog_content = "ฉันสบายดี... คอนเสิร์ตพังหมดแล้ว แต่ฉันสบายดี...",
  ui_story_5036_50361501_107_dialog_content = "ยังไงก็ต้องปกป้องแฟนๆ พวกเขาบาดเจ็บเพราะฉันไม่ได้!",
  ui_story_5036_50361501_108_dialog_content = "แม้ว่า... นี่จะเป็นคอนเสิร์ตครั้งสุดท้ายของฉัน!",
  ui_story_5036_50361501_109_dialog_content = "ใช่ เรามาโฟกัสที่ประเด็นที่มีอยู่ก่อน",
  ui_story_5036_50361501_110_dialog_content = "โดยวิธีการที่วิค Ouroboros จริง ๆ แล้วไม่ใช่วิคได้ไหม?",
  ui_story_5036_50361501_111_dialog_content = "ตอนนี้เขาหนีไปไหนแล้ว?",
  ui_story_5036_50361501_112_dialog_content = "เขาไม่ได้อพยพไปกับคุณเหรอ?",
  ui_story_5036_50361501_113_dialog_content = "ฉันคิดว่าเขาอยู่ข้างหลังฉัน ฉันเลยไม่ได้สนใจอะไรมาก!",
  ui_story_5036_50361501_114_dialog_content = "โอ้ ฉันไม่ใช่นักสู้เลยจริงๆ",
  ui_story_5036_50361501_115_dialog_content = "ฉันคิดว่าฉันได้ยินเขา?",
  ui_story_5036_50361501_116_dialog_content = "เขาอยู่ที่นั่น!",
  ui_story_5036_50361501_117_dialog_content = "ในเมื่อผมเรียกตัวเองว่าเป็นนักสัตววิทยา ผมจึงเริ่มทำตัวให้เหมือนดีกว่า",
  ui_story_5036_50361501_118_dialog_content = "ทำไมเขาถึงอยู่ที่นั่นคนเดียว?",
  ui_story_5036_50361501_119_dialog_content = "กลับมาที่นี่! มันอันตราย!",
  ui_story_5036_50361501_120_dialog_content = "ขอบคุณที่เตือน แต่ฉันทำไม่ได้ ยังไม่เพียงแค่",
  ui_story_5036_50361501_121_dialog_content = "เฮ้ คุณ! คุณเหนอะหนะผี! ที่นี่!",
  ui_story_5036_50361501_122_dialog_content = "พี่โก้! ฟ่อ-!",
  ui_story_5036_50361501_123_dialog_content = "กร๊ากกก...",
  ui_story_5036_50361501_124_dialog_content = "ใช่! แค่นั้นแหละ...",
  ui_story_5036_50361501_125_dialog_content = "ทำไมต้องตามหา Ouroboros ในเมื่อมี Aurorian ที่ไร้ที่พึ่งอยู่ที่นี่?",
  ui_story_5036_50361501_126_dialog_content = "(ใกล้อีกนิด... ต้องพาพวกมันออกห่างจาก Ouroboros)",
  ui_story_5036_50361501_127_dialog_content = "(นกเค้าแมวลูทูมิน่าจะเพียงพอที่จะดึงความสนใจของพวกมันและซื้อเวลาได้)",
  ui_story_5036_50361501_128_option_content = "วิค กลับมานี่!",
  ui_story_5036_50361501_129_dialog_content = "ฮ่าฮ่าฮ่า! ไม่ต้องห่วง ฉันสบายดี!",
  ui_story_5036_50361501_130_dialog_content = "มีเพียงนักสัตววิทยาที่เก่งที่สุดเท่านั้นที่สามารถมอบชีวิตของเขาให้กับสัตว์มหัศจรรย์ของเขาได้!",
  ui_story_5036_50361501_131_dialog_content = "ก๊ากกก—!",
  ui_story_5036_50361501_132_dialog_content = "(ดี! พวกเขาจับเหยื่อ!)",
  ui_story_5036_50361501_133_dialog_content = "(ตอนนี้ สิ่งที่ฉันต้องการคืออัญเชิญนกฮูกลูทูมิ!)",
  ui_story_5036_50361501_134_dialog_content = "ลูทูมิ ฮูก!",
  ui_story_5036_50361501_135_dialog_content = "ฮู้—ฮู้ฮู้!",
  ui_story_5036_50361501_136_dialog_content = "วิ่งหนีทำไม เจ้านกฮูกลูทูมิ!? กลับมาที่นี่—!",
  ui_story_5036_50361501_137_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_5036_50361501_138_dialog_content = "ครี!",
  ui_story_5036_50361501_139_dialog_content = "อะไรนะ!",
  ui_story_5036_50361501_140_dialog_content = "<color=#e8d9bb>หวือ— ปัง!</color>",
  ui_story_5036_50361501_141_dialog_content = "วิค?",
  ui_story_5036_50361501_142_dialog_content = "อุ๊ย อุ๊ย อุ๊ย!",
  ui_story_5036_50361501_143_dialog_content = "(หางของ Ouroboros ส่งเขาบินไป! เดี๋ยวก่อน! นั่นมัน...!)",
  ui_story_5036_50361501_144_dialog_content = "วิค! วิ่ง!",
  ui_story_5036_50361501_145_dialog_content = "จุ๊! มังกรนั่นไม่รู้จักวิธีอ่อนโยนจริงๆ",
  ui_story_5036_50361501_146_dialog_content = "PlayerName, คุณพูดอะไร? ฉันไม่ได้ยินคุณ!",
  ui_story_5036_50361501_147_dialog_content = "อ๊ากกกก!",
  ui_story_5036_50361501_148_dialog_content = "เอ้ย...โดนล้อม!",
  ui_story_5036_50361501_149_dialog_content = "เฮ้ Eclipsites ฉันแก่แล้ว และนั่นทำให้ฉันรู้สึกแย่!",
  ui_story_5036_50361501_150_dialog_content = "ดู Caeleste ตรงนั้นสิ! เขายังเด็กและอ่อนโยน! และฉ่ำกว่าฉันมาก!",
  ui_story_5036_50361501_151_dialog_content = "กรรร!!!",
  ui_story_5036_50361501_152_dialog_content = "ช่วยฉันด้วย เจ้าเฟอร์บอลน้อย!",
  ui_story_5036_50361501_153_dialog_content = "PlayerName!",
  ui_story_5036_50361502_1_dialog_content = "เลิศ! ฉันยังมีชีวิตอยู่!",
  ui_story_5036_50361502_2_dialog_content = "แม้ว่าแผนการทั้งหมดของฉันที่จะดึงดูดความสนใจของ Eclipsites จะล้มเหลว",
  ui_story_5036_50361502_3_dialog_content = "คุณมีอารมณ์ที่จะหัวเราะแค่ไหน!?",
  ui_story_5036_50361502_4_dialog_content = "ถ้าคุณมีแผน คุณต้องบอกเราเกี่ยวกับมัน!",
  ui_story_5036_50361502_5_dialog_content = "ขอโทษขอโทษ! ฉันกังวลเกี่ยวกับความปลอดภัยของ Ouroboros มากจนลืมไปเลย",
  ui_story_5036_50361502_6_dialog_content = "แต่สำหรับบันทึก แผนของฉันคงจะสำเร็จถ้ามันไม่ส่งฉันบิน",
  ui_story_5036_50361502_7_dialog_content = "นี่ไม่ใช่เวลาที่จะพูดถึงสิ่งที่อยากได้!",
  ui_story_5036_50361502_8_dialog_content = "มีวิธีอื่นที่จะทำให้มันสงบลงไหม?",
  ui_story_5036_50361502_9_dialog_content = "น่าเสียดาย ฉันคิดอย่างอื่นไม่ออกนอกจากเอาชนะ Eclipsites ทั้งหมด",
  ui_story_5036_50361502_10_dialog_content = "เราไม่สามารถรอให้ Ouroboros รวบรวมพละกำลังมากพอที่จะบินหนีไปได้เองหรือ?",
  ui_story_5036_50361502_11_dialog_content = "นั่นเป็นแง่ดีเกินไป Eclipsites ไม่ถอยเลย",
  ui_story_5036_50361502_12_dialog_content = "หากยังเป็นเช่นนี้ต่อไป แม้ว่าโอโรโบรอสจะบินได้อีกครั้ง มันก็จะบาดเจ็บเกินไป",
  ui_story_5036_50361502_13_dialog_content = "ยะ...ยังไงอ่ะ",
  ui_story_5036_50361502_14_dialog_content = "เลดี้คาร์ลีน เราได้รับคำสั่งจากท่านเจ้าเมือง",
  ui_story_5036_50361502_15_dialog_content = "ถึงเวลาแล้วล่ะครับ",
  ui_story_5036_50361502_16_dialog_content = "การอพยพใกล้จะเสร็จสมบูรณ์ ทั้งฝ่ายบริหารของ Illumina และ Lumopolis ได้เสร็จสิ้นการประเมินความเสี่ยงของ Colossus แล้ว",
  ui_story_5036_50361502_17_dialog_content = "พวกเขาตัดสินใจทิ้งทหารไว้เบื้องหลังเพื่อยึด Eclipsites กลับมา ควบคุมมังกร และรักษาสมดุลของ Colossus",
  ui_story_5036_50361502_18_dialog_content = "เมื่อ Colossus ออกจาก Umbraton แล้ว พวกเขาจะยิงมันลง",
  ui_story_5036_50361502_19_dialog_content = "คุณต้องการยิงยักษ์ใหญ่พร้อมกับ Ouroboros!? ไม่มีทาง!",
  ui_story_5036_50361502_20_dialog_content = "อาจเป็นครั้งสุดท้าย! พวกเขาจะสูญพันธุ์ไปโดยสิ้นเชิงหากคุณทำอย่างนั้น!",
  ui_story_5036_50361502_21_dialog_content = "และฉันจะไม่ยอมเสียยูโลโกซไป!",
  ui_story_5036_50361502_22_dialog_content = "คุณมีความคิดที่ดีกว่า? ถ้าทำไม่ได้ก็หุบปากซะ",
  ui_story_5036_50361502_23_dialog_content = "ยักษ์ใหญ่อยู่เหนือพื้นที่ที่มีประชากรมากที่สุดใน Umbraton เราจะไม่เสี่ยงชีวิตของชาวออโรเรียนหลายล้านคน!",
  ui_story_5036_50361502_24_dialog_content = "จะเกิดอะไรขึ้นถ้าฉันปฏิเสธที่จะออกจากยักษ์ใหญ่?",
  ui_story_5036_50361502_25_dialog_content = "วิค คุณกำลังพูดอะไร—?",
  ui_story_5036_50361502_26_dialog_content = "ฉันเป็นนักสัตววิทยา ไม่มีทางที่ฉันจะปล่อยให้อันตรายมาถึง Ouroboros นั้น",
  ui_story_5036_50361502_27_dialog_content = "ถ้านายอยากยิงโคลอสซัส นายต้องพาฉันลงไปด้วย",
  ui_story_5036_50361502_28_dialog_content = "วิค มันอันตราย!",
  ui_story_5036_50361502_29_dialog_content = "หยุดพูดเล่นๆ!",
  ui_story_5036_50361502_30_dialog_content = "(ฉันจะทำอย่างไร ฉันจะช่วย Ouroboros และ Colossus ได้อย่างไร)",
  ui_story_5036_50361502_31_dialog_content = "(มันต้องมีทาง...)",
  ui_story_5036_50361502_32_dialog_content = "พวกเขาจะได้ยินเสียงของฉันที่พื้นผ่านอุปกรณ์อย่างแน่นอน!",
  ui_story_5036_50361502_33_dialog_content = "ช่างน่าทึ่งจริงๆ สิ่งมีชีวิตนี้สามารถสื่อสารโดยใช้ท่วงทำนองที่ Caelestites ใช้ในการควบคุม Colossi",
  ui_story_5036_50361502_34_dialog_content = "การเขียนเพลงของคุณด้วยท่วงทำนองที่ใช้ในการกระตุ้น Colossi คุณอาจปลุกให้ Ouroboros ตื่นโดยไม่ได้ตั้งใจ!",
  ui_story_5036_50361502_35_dialog_content = "มีอีกวิธีที่อยากลอง!",
  ui_story_5036_50361502_36_dialog_content = "หา?",
  ui_story_5036_50361502_37_dialog_content = "ว่าไง",
  ui_story_5036_50361502_38_dialog_content = "Chaminade ค้นพบว่า Ouroboros สามารถเข้าใจท่วงทำนองที่ Caelestites ใช้ในการควบคุม Colossi",
  ui_story_5036_50361502_39_dialog_content = "ถ้าเราสามารถเล่นทำนองที่ปิด Colossus และหยุด Eclipsites ในเวลาเดียวกัน บางทีเราอาจจะสงบลงได้",
  ui_story_5036_50361502_40_dialog_content = "คุ้มค่าที่จะลอง",
  ui_story_5036_50361502_41_dialog_content = "เพลงจะเล่นได้ไหมถ้าความสามารถทางจิตของ PlayerName ไม่สามารถเข้าถึงมังกรได้?",
  ui_story_5036_50361502_42_dialog_content = "ก็... ตราบใดที่มันดังพอ เราก็ควรจะได้รับความสนใจ",
  ui_story_5036_50361502_43_dialog_content = "เราสามารถใช้ระบบลำโพงของเวทีได้!",
  ui_story_5036_50361502_44_dialog_content = "ใช่. ฉันต้องการความช่วยเหลือจากโกลดี้ เราน่าจะทำได้ด้วย Luminatics และอุปกรณ์ของเธอ!",
  ui_story_5036_50361502_45_dialog_content = "หืม?",
  ui_story_5036_50361502_46_dialog_content = "...",
  ui_story_5036_50361502_47_dialog_content = "เข้าใจแล้วครับ",
  ui_story_5036_50361502_48_dialog_content = "คอนเสิร์ตของฉันไม่สามารถจบลงได้ก่อนที่ฉันจะร้องเพลงเสร็จ",
  ui_story_5036_50361502_49_dialog_content = "แม้ว่าฉันจะไม่สามารถขึ้นเวทีเป็นไอดอลได้ในอนาคต ตราบใดที่คุณและแฟนๆ ของฉันยังอยู่ตรงนั้น...",
  ui_story_5036_50361502_50_dialog_content = "ฉันจะร้องเพลงให้คุณฟังทุกเมื่อที่คุณต้องการ",
  ui_story_5036_50361502_51_dialog_content = "ไม่ต้องพูดถึง Umbraton อยู่ใต้เรา เป็นบ้านของฉันและบ้านของแฟนๆ",
  ui_story_5036_50361502_52_dialog_content = "คุณแน่ใจแค่ไหนว่าจะได้ผล PlayerName?",
  ui_story_5036_50361502_53_option_content = "ฉันไม่สามารถสัญญาอะไรกับคุณ ...",
  ui_story_5036_50361502_54_option_content = "ฉันต้องการที่จะให้มันยิง!",
  ui_story_5036_50361502_55_dialog_content = "ได้สิ",
  ui_story_5036_50361502_56_dialog_content = "ฉันจะช่วยเอง",
  ui_story_5036_50361502_57_dialog_content = "เลดี้คาร์ลีน! คุณจริงจังไหม",
  ui_story_5036_50361502_58_dialog_content = "แน่นอน. และฉันจะให้การสนับสนุนหากล้มเหลว",
  ui_story_5036_50361502_59_dialog_content = "แจ้งทุกทีมสแตนด์บาย!",
  ui_story_5036_50361502_60_dialog_content = "เข้าใจ อัศวิน ฟอร์มขึ้น!",
  ui_story_5036_50361502_61_dialog_content = "คาร์ลีน ขอบคุณมาก!",
  ui_story_5036_50361502_62_dialog_content = "ฉันจะช่วยด้วย!",
  ui_story_5036_50361502_63_dialog_content = "แต่ลูกเรือที่ดูแลระบบลำโพงออกจากเรือเหาะไปแล้ว",
  ui_story_5036_50361502_64_dialog_content = "อย่าลืมพวกเรา! เรามีสิ่งนี้",
  ui_story_5036_50361502_65_dialog_content = "อุปกรณ์อาจมีการปรับเปลี่ยน แต่ยังคงเหมือนเดิมมาก ปล่อยให้พวกเขาเป็นของเรา",
  ui_story_5036_50361502_66_dialog_content = "โกรนรู ซิบอน!?",
  ui_story_5036_50361502_67_dialog_content = "PlayerNameคุณกำลังพยายามท้าทายด่านที่ยากสุด ๆ ใช่ไหม?",
  ui_story_5036_50361502_68_dialog_content = "ฉันจะพลาดอะไรสนุกๆ แบบนี้ไปได้ยังไง?",
  ui_story_5036_50361502_69_dialog_content = "A-และฉัน!",
  ui_story_5036_50361502_70_dialog_content = "ฉันได้สัมภาษณ์ผู้คนในช่วงสองสามวันที่ผ่านมา รวมถึงผู้ที่จัดการระบบลำโพงด้วย",
  ui_story_5036_50361502_71_dialog_content = "ฉันได้เรียนรู้สิ่งหนึ่งหรือสองจากพวกเขาด้วย!",
  ui_story_5036_50361502_72_dialog_content = "ดูเหมือนว่าจะเป็นความพยายามที่บ้าคลั่ง แต่ได้โปรดให้ฉันแท็กด้วย! ฉันจะทำให้ดีที่สุดเพื่อช่วยโกลดี้และคุณ!",
  ui_story_5036_50361502_73_dialog_content = "ขอบคุณนะ...",
  ui_story_5036_50361502_74_dialog_content = "PlayerNameคุณมีวิธีที่จะทำให้ทุกคนเป็นหนึ่งเดียวกัน",
  ui_story_5036_50361502_75_dialog_content = "ความสามารถนี้เพียงอย่างเดียวทำให้ Caelestite เป็นสัตว์ร้ายที่น่าอัศจรรย์",
  ui_story_5036_50361502_76_dialog_content = "เดี๋ยวก่อน ฉันไม่ใช่สัตว์ร้าย!",
  ui_story_5036_50361502_77_dialog_content = "ฮ่าฮ่าฮ่า ไม่มีเวลาที่จะถกเถียงกัน",
  ui_story_5036_50361502_78_dialog_content = "เรามีเวลาน้อย มาช่วย Ouroboros ก่อน!",
  ui_story_5036_50361502_79_dialog_content = "ถูกต้อง. ไปที่เวที!",
  ui_story_5036_50361601_1_dialog_content = "โกลดี้ คุณจำทำนองที่ฉันสอนได้ไหม",
  ui_story_5036_50361601_2_dialog_content = "แน่นอน! ทุกข้อของมัน!",
  ui_story_5036_50361601_3_dialog_content = "แต่มี Eclipsites มากมายขวางทางเรา...",
  ui_story_5036_50361601_4_dialog_content = "ไม่ต้องกังวล. เราจะดูแลพวกเขาและเปิดทางให้คุณเอง",
  ui_story_5036_50361601_5_dialog_content = "ใช่. ปล่อยให้การต่อสู้เป็นของเรา คุณแค่โฟกัสไปที่การร้องเพลง!",
  ui_story_5036_50361601_6_dialog_content = "อย่างแท้จริง. สู้ไม่ได้ แต่ลูกขนปุยจะช่วยได้",
  ui_story_5036_50361601_7_dialog_content = "จิ๊บ!",
  ui_story_5036_50361601_8_dialog_content = "ขอบคุณที่ยังคงต้องการช่วยฉัน โกลดี้",
  ui_story_5036_50361601_9_dialog_content = "ไม่ต้องขอบคุณฉัน",
  ui_story_5036_50361601_10_dialog_content = "คุณช่วยฉันมาหลายวันแล้ว PlayerName.",
  ui_story_5036_50361601_11_dialog_content = "ถ้าไม่ได้คุณช่วย คอนเสิร์ตนี้คงไม่มีทางเกิดขึ้น",
  ui_story_5036_50361601_12_dialog_content = "แต่ก็พังทลาย...",
  ui_story_5036_50361601_13_dialog_content = "ถึงกระนั้น ฉันรู้ว่าคุณพยายามมากแค่ไหน",
  ui_story_5036_50361601_14_dialog_content = "ความล้มเหลวของคอนเสิร์ตไม่ได้เปลี่ยนข้อเท็จจริงนั้น",
  ui_story_5036_50361601_15_dialog_content = "เอาล่ะ ได้เวลาที่ฉันจะตอบแทนคุณแล้ว!",
  ui_story_5036_50361601_16_dialog_content = "ได้เลยค่ะ!",
  ui_story_5036_50361601_17_dialog_content = "งั้นก็ไปกันเถอะ!",
  ui_story_5036_50361601_18_dialog_content = "กรรร!!!",
  ui_story_5036_50361601_19_dialog_content = "Eclipsites มาแล้ว! เตรียมรบ!",
  ui_story_5036_50361602_1_dialog_content = "เรามาถึงขั้นตอนแล้ว! อุปกรณ์เป็นไงบ้าง?",
  ui_story_5036_50361602_2_dialog_content = "อุปกรณ์ครบ!",
  ui_story_5036_50361602_3_dialog_content = "ปริมาณเอาต์พุตสูงสุด—!",
  ui_story_5036_50361602_4_dialog_content = "กร๊ากกก—!",
  ui_story_5036_50361602_5_dialog_content = "หา?!",
  ui_story_5036_50361602_6_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5036_50361602_7_dialog_content = "ท-ขอบคุณ!",
  ui_story_5036_50361602_8_dialog_content = "ด้วยความยินดี",
  ui_story_5036_50361602_9_dialog_content = "ปล่อยให้ Eclipsites เป็นของเรา! คุณเพียงแค่มุ่งเน้นไปที่การจัดการอุปกรณ์!",
  ui_story_5036_50361602_10_dialog_content = "ตราบใดที่เรายังอยู่ที่นี่ เราจะไม่ยอมให้ Eclipsite ผ่านไป!",
  ui_story_5036_50361602_11_dialog_content = "กร๊าซซซ!",
  ui_story_5036_50361602_12_dialog_content = "อย่าแม้แต่จะคิดหนีเชียว!",
  ui_story_5036_50361602_13_dialog_content = "โอกาสของคุณมาถึงแล้ว! Furball น้อย โจมตีกลับ!",
  ui_story_5036_50361602_14_dialog_content = "จิ๊บ!",
  ui_story_5036_50361602_15_dialog_content = "กร๊ากกก—",
  ui_story_5036_50361602_16_dialog_content = "ว้าว สิ่งนั้นรวดเร็ว แม้แต่ Furball ตัวน้อยก็ยังมีปัญหาในการตามทัน",
  ui_story_5036_50361602_17_dialog_content = "มันยังคงวิ่งไปรอบ ๆ ลำบากแค่ไหน!",
  ui_story_5036_50361602_18_dialog_content = "รอก่อน! อย่าให้มันรบกวนการร้องเพลงของ Goldie อย่างน้อยที่สุด!",
  ui_story_5036_50361602_19_dialog_content = "ใช่!",
  ui_story_5036_50361602_20_dialog_content = "(ทุกคนสู้ๆ ฉันต้องทำงานของฉัน)",
  ui_story_5036_50361602_21_dialog_content = "ครี—ครี!",
  ui_story_5036_50361602_22_dialog_content = "<color=#e8d9bb>รัมเบิ้ล—!</color>",
  ui_story_5036_50361602_23_dialog_content = "Ouroboros คุณก็ลำบากเหมือนกันใช่ไหม",
  ui_story_5036_50361602_24_dialog_content = "เพียงแค่รออีกสักหน่อย ไว้วางใจเรา. เราจะปกป้องคุณ",
  ui_story_5036_50361602_25_dialog_content = "อืม... ฉันจะเริ่มร้องเพลงแล้ว!",
  ui_story_5036_50361602_26_dialog_content = "เข้าใจแล้ว!",
  ui_story_5036_50361602_27_dialog_content = "(ใจเย็นๆ โกลดี้)",
  ui_story_5036_50361602_28_dialog_content = "(ปลอบประโลมเหล่าโอโรโบรอสด้วยเพลงนี้และทำให้มันสงบลง)",
  ui_story_5036_50361602_29_dialog_content = "(ทำเพลงนี้ให้คู่ควรกับการอำลาเวทีและชีวิตการเป็นไอดอลเป็นครั้งสุดท้าย)",
  ui_story_5036_50361602_30_dialog_content = "โอโรโบรอส ฟังเพลงของฉันสิ!",
  ui_story_5036_50361602_31_dialog_content = "♪ โลกกว้างใหญ่ จักรวาลคือมหาสมุทร ♪",
  ui_story_5036_50361602_32_dialog_content = "♪ เราเกิดมาเหมือนอุกกาบาต ขี้เล่น และสดใส ♪",
  ui_story_5036_50361602_33_dialog_content = "♪ เราเล่นด้วยความสุข แต่บางครั้งก็เหนื่อย ♪",
  ui_story_5036_50361602_34_dialog_content = "♪ แสงไฟในบ้านนำทางเราอย่างอบอุ่นสู่รังของเรา ♪",
  ui_story_5036_50361602_35_dialog_content = "ทุกคน ทำตามคำสั่งและอพยพ! Shadowlord จะรับรองความปลอดภัยของคุณ!",
  ui_story_5036_50361602_36_dialog_content = "♪ แสงไฟในบ้านนำทางเราอย่างอบอุ่นสู่รังของเรา ♪",
  ui_story_5036_50361602_37_dialog_content = "พี่สาว ได้ยินไหม?",
  ui_story_5036_50361602_38_dialog_content = "มันกำลังร้องเพลง!",
  ui_story_5036_50361602_39_dialog_content = "มิส คนอพยพทั้งหมดออกจากเรือบินแล้ว",
  ui_story_5036_50361602_40_dialog_content = "ตกลง. เตรียมออกปฏิบัติการอีกครั้งและอพยพพลเรือนกลุ่มต่อไป!",
  ui_story_5036_50361602_41_dialog_content = "♪ แสงไฟในบ้านนำทางเราอย่างอบอุ่นสู่รังของเรา ♪",
  ui_story_5036_50361602_42_dialog_content = "นั่นคือ... ร้องเพลง?",
  ui_story_5036_50361602_43_dialog_content = "เสียงที่อ่อนโยนเช่นนี้ มันมาจากยักษ์ใหญ่หรือไม่?",
  ui_story_5036_50361602_44_dialog_content = "♪ เด็กเหนื่อย ไปนอนเถอะ ♪",
  ui_story_5036_50361602_45_dialog_content = "♪ ขอให้เพลงกล่อมเด็กนี้ปกป้องความฝันของคุณ ♪",
  ui_story_5036_50361602_46_dialog_content = "♪ นี่คือบ้านของคุณ ♪",
  ui_story_5036_50361602_47_dialog_content = "ครี—!",
  ui_story_5036_50361602_48_dialog_content = "(ดูเหมือนว่า Ouroboros จะตอบสนอง!)",
  ui_story_5036_50361602_49_dialog_content = "คาร์ลีน PlayerName! ดูเหมือนจะสงบลง!",
  ui_story_5036_50361602_50_dialog_content = "ยอดเยี่ยม! เพลงกำลังทำงาน!",
  ui_story_5036_50361602_51_dialog_content = "ยักษ์ใหญ่หยุดโยกแล้ว สิ่งนี้จะได้ผล!",
  ui_story_5036_50361602_52_dialog_content = "ก้าวไปสู่ Eclipsites!",
  ui_story_5036_50361602_53_dialog_content = "♪ นี่คือบ้านของคุณ ♪",
  ui_story_5036_50361602_54_dialog_content = "เพลง?",
  ui_story_5036_50361602_55_dialog_content = "มันเป็นท่วงทำนองที่ปิด Colossus ลง มันนุ่มนวลเหมือนเพลงกล่อมเด็ก",
  ui_story_5036_50361602_56_dialog_content = "โกลดี้ร้องเพลงเหรอ? แต่...",
  ui_story_5036_50361602_57_dialog_content = "♪ ตอนนี้ไม่มีบ้านนั้นแล้ว ♪",
  ui_story_5036_50361602_58_dialog_content = "(ฉันดูเหมือนจะได้ยิน Chaminade ร้องเพลง!)",
  ui_story_5036_50361602_59_dialog_content = "(เธอคงเสียใจมาก ฉันไม่มีแม้แต่โอกาสปลอบโยนเธอเลย...)",
  ui_story_5036_50361602_60_dialog_content = "(เธออาจเป็นเพียงร่างในความฝัน ไม่มีอยู่จริง)",
  ui_story_5036_50361602_61_dialog_content = "(แต่ความโศกเศร้าและความเหงาของเธอนั้นเป็นเรื่องจริงมาก)",
  ui_story_5036_50361602_62_dialog_content = "(ถ้าอย่างนั้นฉันจะมอบเพลงนี้ให้กับคุณ Chaminade)",
  ui_story_5036_50361602_63_dialog_content = "(และหวังว่ามันจะขจัดความเศร้าของคุณออกไป)",
  ui_story_5036_50361602_64_dialog_content = "♪ ตอนนี้ไม่มีบ้านนั้นแล้ว ♪",
  ui_story_5036_50361602_65_dialog_content = "♪ ถึงกระนั้น เด็ก ๆ ก็เริ่มออกเดินทางกันหรือยัง ♪",
  ui_story_5036_50361602_66_dialog_content = "♪ ผ่านน้ำตาที่ไหลตลอดทั้งคืน ♪",
  ui_story_5036_50361602_67_dialog_content = "♪ ผ่านความเศร้าโศกและความสุข การจากไป และการพบกันใหม่ ♪",
  ui_story_5036_50361602_68_dialog_content = "♪ พวกเขายังมองเห็นแสงแห่งความหวังที่รุ่งอรุณได้หรือไม่? ♪",
  ui_story_5036_50361602_69_dialog_content = "♪ แสงสว่างที่ยังต้องรออยู่ข้างหน้า ♪",
  ui_story_5036_50361602_70_dialog_content = "น้ำวนเชี่ยวกราก!",
  ui_story_5036_50361602_71_dialog_content = "มีอีกกี่ตัว...?",
  ui_story_5036_50361602_72_dialog_content = "เกรย์!!!",
  ui_story_5036_50361602_73_dialog_content = "ดูมัน! มันกลับมาแล้ว!",
  ui_story_5036_50361602_74_dialog_content = "ฉันจะไม่ให้คุณเข้าใกล้!",
  ui_story_5036_50361602_75_dialog_content = "นั่นคือเพลงของคุณ โกลดี้?",
  ui_story_5036_50361602_76_dialog_content = "มันอบอุ่นมาก เหมือนแสงแดดและสายลมใน Eraveil",
  ui_story_5036_50361602_77_dialog_content = "ฉันเห็นตอนนี้ แม้ว่า Eraveil จะถูกทำลาย แต่ก็ยังไม่หายไป บ้าน...สร้างใหม่ได้",
  ui_story_5036_50361602_78_dialog_content = "โกลดี้ ฉันได้ยินคุณ",
  ui_story_5036_50361602_79_dialog_content = "ดังนั้น ฉันควรจะ—",
  ui_story_5036_50361602_80_dialog_content = "♪ ลองเช็ดน้ำตาเหล่านั้น ♪",
  ui_story_5036_50361602_81_dialog_content = "♪ เช็ดน้ำตาเหล่านั้นออก แล้วออกเดินทางอีกครั้ง— ♪",
