  ui_story_5036_50361701_20_dialog_content = "มันสัมผัสได้ถึงความปรารถนาสุดท้ายของหัวใจที่จะกลับบ้านของฉัน ดังนั้นมันจึงสร้าง Eraveil ขึ้นมาในโลกแห่งความฝัน และตัวฉันเอง",
