  ui_story_5036_50361701_37_dialog_content = "แต่สุดท้ายเธออยากให้ฉันนำเพลงนี้ไปให้ทุกคนฟัง",
  ui_story_5036_50361701_38_dialog_content = "ฉันจะรักษาสัญญานั้น แม้ว่าฉันจะไม่สามารถเป็นไอดอลได้อีกต่อไป",
  ui_story_5036_50361701_39_dialog_content = "<color=#e8d9bb>บี๊บ บี๊บ บี๊บ—</color>",
  ui_story_5036_50361701_40_dialog_content = "เฮ้! คำขอข้อความจาก Sheol!",
  ui_story_5036_50361701_41_dialog_content = "เราจะทำอย่างไร เราควรตอบไหม?",
  ui_story_5036_50361701_42_dialog_content = "อย่างใดฉันรู้สึกไม่ดีเกี่ยวกับเรื่องนี้",
  ui_story_5036_50361701_43_dialog_content = "เดี๋ยวกูถามกุ๊บกิ๊บ!",
  ui_story_5036_50361701_44_dialog_content = "<color=#e8d9bb>ดิง—</color>",
  ui_story_5036_50361701_45_dialog_content = "มันชี้ลง นั่นเป็นสัญญาณที่ดี!",
  ui_story_5036_50361701_46_dialog_content = "เราควรตอบไหม?",
  ui_story_5036_50361701_47_dialog_content = "มาตอบกันเถอะว่า PlayerName.",
  ui_story_5036_50361701_48_dialog_content = "ทางเดียวคือเผชิญหน้ากับปัญหาของเรา",
  ui_story_5036_50361701_49_dialog_content = "เอาล่ะ ทำให้เธอผ่าน—",
  ui_story_5036_50361701_50_dialog_content = "PlayerName?",
  ui_story_5036_50361701_51_dialog_content = "เลดี้เชล? ฉันฟัง!",
  ui_story_5036_50361701_52_dialog_content = "ตอนนี้คุณอยู่ที่ไหน เกิดอะไรขึ้น?",
  ui_story_5036_50361701_53_dialog_content = "เราอยู่ที่โซรอซ เราทุกคนอยู่ที่นี่ ทุกคนสบายดี",
  ui_story_5036_50361701_54_dialog_content = "ไม่มีใครบาดเจ็บ? สุดยอดเลย...เดี๋ยวก็...",
  ui_story_5036_50361701_55_dialog_content = "โกล—ตาย!",
  ui_story_5036_50361701_56_dialog_content = "ฮือ ๆ ๆ",
  ui_story_5036_50361701_57_dialog_content = "คุณอธิบายตัวเองดีกว่า คอนเสิร์ตที่ควรจะดำเนินไปอย่างราบรื่นกลับกลายเป็นความหายนะเช่นนี้ได้อย่างไร!?",
  ui_story_5036_50361701_58_dialog_content = "ฉัน เอ่อ...",
  ui_story_5036_50361701_59_dialog_content = "ฉันเสียใจ. ฉันทำมันพัง...",
  ui_story_5036_50361701_60_dialog_content = "ฉันไม่ได้ตรวจสอบสถานที่อย่างระมัดระวังพอ ดังนั้นฉันจึงล้มเหลวในการหาไข่ Ouroboros บน Colossus และตระหนักถึงภัยคุกคามที่อาจเกิดขึ้นจากมัน",
  ui_story_5036_50361701_61_dialog_content = "และฉันไม่คาดคิดมาก่อนว่าโอโรโบรอสจะตอบสนองต่อการร้องเพลงและการฟักไข่ของฉัน...",
  ui_story_5036_50361701_62_dialog_content = "คุณรู้ไหม คุณสามารถตำหนิ Ouroboros สำหรับทุกสิ่ง",
  ui_story_5036_50361701_63_dialog_content = "ไม่ ฉันจะรับผิดชอบทั้งหมดสำหรับสิ่งนี้และชดใช้ค่าเสียหายทั้งหมดตามสัญญา",
  ui_story_5036_50361701_64_dialog_content = "เฮ้อ... คุณหลอกฉันจริงๆ",
  ui_story_5036_50361701_65_dialog_content = "ฉันลงทุนเงินจำนวนมากเพื่อโปรโมตคอนเสิร์ต เมื่อ Colossus หายไป เงินทั้งหมดที่ใช้ในการบำรุงรักษาอุปกรณ์และการตั้งค่าเวทีก็ลดลงเช่นกัน",
  ui_story_5036_50361701_66_dialog_content = "ยังไม่รวมถึงค่าใช้จ่ายอื่นๆ เช่น ค่าดูแลผู้ชมเมื่อเกิดเหตุ",
  ui_story_5036_50361701_67_dialog_content = "ผมเสียใจด้วยจริง ๆ...",
  ui_story_5036_50361701_68_dialog_content = "แต่โปรดวางใจ ฉันจะคืนเงินให้คุณเต็มจำนวน",
  ui_story_5036_50361701_69_dialog_content = "แม้ว่าฉันจะไม่ได้เป็นไอดอลอีกต่อไปในอนาคต แต่ฉันก็ยังทำงานหนักเพื่อหาเงิน…",
  ui_story_5036_50361701_70_dialog_content = "ฮะ? ฉันขอให้คุณชดเชยความสูญเสียเมื่อใด",
  ui_story_5036_50361701_71_dialog_content = "เอ๋...?",
  ui_story_5036_50361701_72_dialog_content = "คอนเสิร์ตคือภัยพิบัติ ใช่ แต่คุณทำได้ดีอย่างคาดไม่ถึง!",
  ui_story_5036_50361701_73_dialog_content = "อารมณ์ในเพลงของคุณไม่ได้ส่งผ่านไปยัง Ouroboros เท่านั้น แต่ยังส่งต่อไปยังผู้ชมด้วย!",
  ui_story_5036_50361701_74_dialog_content = "แม้แต่คนที่ไม่เคยสนใจเรื่องไอดอลก็รู้เรื่องคุณเพราะเหตุการณ์นี้!",
  ui_story_5036_50361701_75_dialog_content = "และหลายคนถามถึง \"ไอดอล\"!",
  ui_story_5036_50361701_76_dialog_content = "อะไรนะ!",
  ui_story_5036_50361701_77_dialog_content = "คุณไม่เพียงแค่ทำตามสัญญาให้ครบถ้วนเท่านั้น แต่ยังทำเกินกว่านั้นมาก",
  ui_story_5036_50361701_78_dialog_content = "A-คุณจริงจังไหม?",
  ui_story_5036_50361701_79_dialog_content = "ฉันเหรอ? ทำไมคุณไม่ค้นหาจากแฟนของคุณ",
  ui_story_5036_50361701_80_dialog_content = "นางสาว! นั่นคือคุณ?",
  ui_story_5036_50361701_81_dialog_content = "เป็นคุณนั้นเอง! คุณและน้องสาวของคุณปลอดภัยหรือไม่?",
  ui_story_5036_50361701_82_dialog_content = "เราสบายดี! คุณน่าทึ่งมาก!",
  ui_story_5036_50361701_83_dialog_content = "เพลงเพราะดี แถมคุณยังทำให้มังกรตัวนั้นเชื่องได้ด้วย!",
  ui_story_5036_50361701_84_dialog_content = "ทุกคนเห็นว่าคุณกล้าหาญแค่ไหน! เจ๋ง!",
  ui_story_5036_50361701_85_dialog_content = "จริงหรือ เฮ้! ฉันดีใจมากที่ได้ยินคุณพูดแบบนั้น!",
  ui_story_5036_50361701_86_dialog_content = "มีคนอื่นอยากคุยกับคุณด้วย!",
  ui_story_5036_50361701_87_dialog_content = "นั่นคือโกลดี้?",
  ui_story_5036_50361701_88_dialog_content = "ย-ใช่ นี่คือโกลดี้พูด และคุณคือ—?",
  ui_story_5036_50361701_89_dialog_content = "คุณสนใจที่จะเป็นศิลปินเดี่ยวส่วนตัวของฉันไหม?",
  ui_story_5036_50361701_90_dialog_content = "ว่าไงนะ!?",
  ui_story_5036_50361701_91_dialog_content = "การแสดงของคุณทำให้ฉันเชื่อว่าคุณเป็นบุคคลที่เชื่อถือได้ มีเกียรติและกล้าหาญ",
  ui_story_5036_50361701_92_dialog_content = "ได้โปรดเป็นศิลปินเดี่ยวของฉัน! ฉันสามารถช่วยคุณร้องเพลงบนเวทีที่หรูหราที่สุดใน Lumopolis ทั้งหมด",
  ui_story_5036_50361701_93_dialog_content = "ขอบคุณสำหรับข้อเสนอที่ดีของคุณ แต่...",
  ui_story_5036_50361701_94_dialog_content = "ฉันจะโน้มน้าวใจคุณได้อย่างไร ตั้งชื่อราคาของคุณ!",
  ui_story_5036_50361701_95_dialog_content = "ไม่ใช่เรื่องของเงิน ฉันอยากจะเป็นไอดอลมากกว่าเป็นนักแสดงส่วนตัว",
  ui_story_5036_50361701_96_dialog_content = "ไอดอลนำความหวังและความสุขมาสู่ทุกคนไม่ว่าจะอยู่ในสถานะใดก็ตาม",
  ui_story_5036_50361701_97_dialog_content = "ฉันสัญญากับเพื่อนคนสำคัญและบรรพบุรุษว่าจะนำเพลงของเรามาให้ทุกคนฟัง!",
  ui_story_5036_50361701_98_dialog_content = "อย่างนั้นเหรอ...? ช่างน่าเสียดาย",
  ui_story_5036_50361701_99_dialog_content = "ฉันขอให้คุณโชคดีกับความฝันของคุณ และฉันจะเข้าร่วมคอนเสิร์ตครั้งต่อไปของคุณอย่างแน่นอน",
  ui_story_5036_50361701_100_dialog_content = "ขอบคุณมาก!",
  ui_story_5036_50361701_101_dialog_content = "ดังนั้น? ตอนนี้คุณมั่นใจหรือยัง?",
  ui_story_5036_50361701_102_dialog_content = "ใช่! โดยไม่มีข้อกังขา!",
  ui_story_5036_50361701_103_dialog_content = "แล้วเชียร์ให้พร้อมรับความท้าทายต่อไป",
  ui_story_5036_50361701_104_dialog_content = "ฉันได้กรอกกำหนดการของคุณเรียบร้อยแล้ว คุณจะมีหลายสิ่งที่ต้องทำเมื่อกลับไปที่ Umbraton",
