  ui_story_5036_50361701_106_dialog_content = "อีกอย่าง ฉันได้ยินมาว่าคุณค้นพบความสามารถใหม่ที่มีศักยภาพชื่อว่าวิค เขาอยู่ที่นี่?",
  ui_story_5036_50361701_107_dialog_content = "ฉันใคร?",
  ui_story_5036_50361701_108_dialog_content = "สนใจสมัครเป็นหนึ่งในไอดอลของฉันไหม?",
  ui_story_5036_50361701_109_dialog_content = "อะไร ฮ่าๆๆ? คุณต้องล้อฉันเล่นแน่ๆ",
  ui_story_5036_50361701_110_dialog_content = "ฉันไม่ได้ถูกตัดออกไปเพื่ออยู่ภายใต้สปอตไลท์ ฉันชอบใช้เวลากับสัตว์",
  ui_story_5036_50361701_111_dialog_content = "คุณจะไม่พิจารณาใหม่?",
  ui_story_5036_50361701_112_dialog_content = "ฉันสามารถจ่ายเงินให้คุณอย่างงามและรวมแชมเปญที่ดีที่สุดจาก Umbraton เป็นโบนัส",
  ui_story_5036_50361701_113_dialog_content = "นั่นฟังดูน่าหลงใหล ฉันไม่ต้องดูแลเจ้าเฟอร์บอลตัวน้อย และฉันก็ดื่มได้ทุกวัน—",
  ui_story_5036_50361701_114_dialog_content = "เจี๊ยบ?! ",
  ui_story_5036_50361701_115_dialog_content = "เจี๊ยบ!!!",
  ui_story_5036_50361701_116_dialog_content = "ฮะ? เฮ้! ปล่อยนะคุณ! ไปกันเถอะ!",
  ui_story_5036_50361701_117_dialog_content = "ดูเหมือนมีคนไม่เห็นด้วยอย่างยิ่ง",
  ui_story_5036_50361701_118_dialog_content = "เอาล่ะ เราจะพูดถึงเรื่องนี้อีกครั้ง",
  ui_story_5036_50361701_119_dialog_content = "แล้วเจอกันที่ Umbraton",
  ui_story_5036_50361701_120_dialog_content = "ยอดเยี่ยม! มันช่าง...สมบูรณ์แบบจริงๆ!",
  ui_story_5036_50361701_121_dialog_content = "ฉันสามารถเป็นไอดอลต่อไปได้!",
  ui_story_5036_50361701_122_dialog_content = "ยินดีด้วย โกลดี้!",
  ui_story_5036_50361701_123_dialog_content = "แม้ว่าคอนเสิร์ตครั้งนี้จะล้มเหลวแค่ไหน แต่ครั้งหน้าจะทำให้สำเร็จให้ได้!",
  ui_story_5036_50361701_124_dialog_content = "กรุณาอย่ามา PlayerName. ฉันจะช่วยคุณในจุดที่ดีที่สุด!",
  ui_story_5036_50361701_125_dialog_content = "แน่นอน. มันเป็นข้อตกลง!",
  ui_story_5036_50361701_126_dialog_content = "แต่จะต้องใช้เวลาสักระยะก่อนที่จะเกิดขึ้น",
  ui_story_5036_50361701_127_dialog_content = "หลังจากที่ฉันกลับมา ฉันจะเขียนเพลงเกี่ยวกับการทดสอบนี้!",
  ui_story_5036_50361701_128_dialog_content = "ดูเหมือนทุกอย่างจะจบลงด้วยดี",
  ui_story_5036_50361701_129_dialog_content = "ดูเหมือนว่ามันแน่นอน ว้าว ตอนนี้ฉันได้พักผ่อนสักครู่แล้ว จู่ๆ ฉันก็เหนื่อยมาก",
  ui_story_5036_50361701_130_dialog_content = "ง่วงแล้ว... หาว...",
  ui_story_5036_50361701_131_dialog_content = "ฮึ่ม! ถ้าไม่ใช่เพราะละครเรื่องนี้ ฉันคงกำลังอาบน้ำร้อนอยู่พอดี!",
  ui_story_5036_50361701_132_dialog_content = "ไม่อาบน้ำ ไม่มีปัญหา",
  ui_story_5036_50361701_133_dialog_content = "ไม่มีความแตกต่างอย่างไรก็ตาม",
  ui_story_5036_50361701_134_dialog_content = "มันดีมากที่ได้เห็นเทคโนโลยีโบราณที่หายากบน Eulogoz",
  ui_story_5036_50361701_135_dialog_content = "หน้าจอและระบบสเตอริโอนั้นน่าทึ่งมาก ฉันได้แรงบันดาลใจ!",
  ui_story_5036_50361701_136_dialog_content = "ฉันสงสัยว่าฉันควรตรวจสอบหลักการทำงานของพวกเขาและสร้างบัลลังก์หรือไม่ ...",
  ui_story_5036_50361701_137_dialog_content = "อย่าบอกนะว่า...",
  ui_story_5036_50361701_138_dialog_content = "จากนั้นฉันก็สามารถเล่นเกมได้ทุกที่ทุกเวลา!",
  ui_story_5036_50361701_139_dialog_content = "อย่างที่ฉันคิด",
  ui_story_5036_50361701_140_dialog_content = "อย่างไรก็ตาม. ให้เรากลับลงไปที่พื้นผิวก่อน",
  ui_story_5036_50361701_141_dialog_content = "<color=#e8d9bb>หลังจากนั้นซักพัก</color>",
  ui_story_5036_50361701_142_dialog_content = "เป็นเวลากลางวันแล้ว ฉันไม่ได้ตระหนักว่าเวลาผ่านไปนานมากแล้ว",
  ui_story_5036_50361701_143_dialog_content = "ในที่สุดก็กลับขึ้นบก! นั่นเป็นอะไรที่ค่อนข้างดีใช่ไหม เจ้าเฟอร์บอลน้อย",
  ui_story_5036_50361701_144_dialog_content = "จิ๊บ!",
  ui_story_5036_50361701_145_dialog_content = "เราเป็นคนต่อสู้ในขณะที่คุณดูอยู่!",
  ui_story_5036_50361701_146_dialog_content = "เฮ้ มันไม่ยุติธรรมเลยที่จะพูดแบบนั้น ฉันพยายามอย่างดีที่สุดเพื่อปกป้อง Ouroboros เช่นกัน!",
  ui_story_5036_50361701_147_dialog_content = "ไม่เป็นไร ฉันจะไม่เถียงคุณเพราะคุณพยายามเต็มที่แล้ว",
  ui_story_5036_50361701_148_dialog_content = "ฉันจะไปตอนนี้ Fia และ Shira ยังคงรอให้ฉันกลับไปหาพวกเขาและเล่าเรื่อง Ouroboros ให้พวกเขาฟัง",
  ui_story_5036_50361701_149_dialog_content = "แล้วเจอกันใหม่นะ",
  ui_story_5036_50361701_150_dialog_content = "ต่อวิก!",
  ui_story_5036_50361701_151_dialog_content = "ระวังที่นั่น! อย่าโดนลักพาตัวอีก!",
  ui_story_5036_50361701_152_dialog_content = "ไม่ต้องกังวล! ฉันเป็นผู้ใหญ่ที่พึ่งพาได้โดยสิ้นเชิง!",
  ui_story_5036_50361701_153_dialog_content = "เราจะนั่งเรือบินกลับไปที่ลูโมโปลิสด้วย",
  ui_story_5036_50361701_154_dialog_content = "(เอาจริงๆ คราวหน้าต้องให้คนไปเตรียมน้ำร้อนไว้ให้ล่วงหน้าแล้วล่ะ...)",
  ui_story_5036_50361701_155_dialog_content = "เฮ้ คุณ Rediesel Wrench brauts เจอกันครั้งหน้าฉันจะส่งแกเข้าคุกให้หมด",
  ui_story_5036_50361701_156_dialog_content = "อะไร ช่างหยิ่งยโส คุณคิดว่าคุณเป็นใคร",
  ui_story_5036_50361701_157_dialog_content = "ต่อมาคือคาเลสไทต์",
  ui_story_5036_50361701_158_dialog_content = "ลาก่อน!",
  ui_story_5036_50361701_159_dialog_content = "ทุกคนหายไปไหน? ซีโอ เรากลับกันเถอะ",
  ui_story_5036_50361701_160_dialog_content = "ไม่เป็นอะไร. หมดเวลาพักร้อนแล้ว ได้เวลากลับไปทำงานแล้ว",
  ui_story_5036_50361701_161_dialog_content = "เจ้าหน้าที่ Gronru คุณไม่ได้บินกลับกับเราบน Colossus เหรอ?",
  ui_story_5036_50361701_162_dialog_content = "ทุกอย่างปกติดี. ผมกับซีโอจะไปเอารถ จะได้ไม่รบกวนแผนการของคุณ",
  ui_story_5036_50361701_163_dialog_content = "นอกจากนี้ ฉันต้องคุยกับ Sio ถึงความเป็นไปได้ในการเพิ่มหน้าจอและเครื่องเล่นเกมบนบัลลังก์!",
  ui_story_5036_50361701_164_dialog_content = "ทะ-พูดอะไรน่ะ!?",
  ui_story_5036_50361701_165_dialog_content = "ไปกันเถอะ Sio ตัวน้อยของฉัน!",
  ui_story_5036_50361701_166_dialog_content = "H-ช่วยฉันด้วย...!",
  ui_story_5036_50361701_167_dialog_content = "ดูเหมือนว่ายังมีปัญหาที่แก้ไม่ได้สำหรับคนอย่าง Siobhan",
  ui_story_5036_50361701_168_dialog_content = "เดาว่าเราควรกลับด้วย",
  ui_story_5036_50361701_169_dialog_content = "ใช่ ใช่!",
  ui_story_5036_50361701_170_dialog_content = "ฉันตัดสินใจแล้ว!",
  ui_story_5036_50361701_171_dialog_content = "ฮะ? ครั้งนี้คุณตัดสินใจบ้าอะไร",
  ui_story_5036_50361701_172_dialog_content = "เมื่อเรากลับมา ฉันจะเกลี้ยกล่อมให้หัวหน้าจัดเวทีบนหัวของ Lepidoz!",
  ui_story_5036_50361701_173_dialog_content = "ฟังดูเป็นความคิดที่ดีจริงๆ!",
  ui_story_5036_50361701_174_dialog_content = "เฮ้! มันเป็นความคิดของฉัน! ฉันจะขอให้เจ้านายสร้างเวทีไอดอล!",
  ui_story_5036_50361701_175_dialog_content = "กลับมาที่นี่คุณ! เฮฟวีเมทัลคือดนตรีที่แท้จริง!",
  ui_story_5036_50361701_176_dialog_content = "โอ้ช่างมีชีวิตชีวา",
  ui_story_5036_50361701_177_dialog_content = "ขออำลาด้วย PlayerName.",
  ui_story_5036_50361701_178_dialog_content = "ขอบคุณสำหรับทุกอย่าง!",
  ui_story_5036_50361701_179_dialog_content = "คุณด้วย. คุณทำงานอย่างหนักเพื่อให้คอนเสิร์ตนี้เกิดขึ้น และเราต่อสู้มาอย่างยาวนาน ได้เวลาพักผ่อนอย่างเต็มที่แล้ว",
  ui_story_5036_50361701_180_dialog_content = "ฉันเป็นไอดอลมืออาชีพ คุณก็รู้ งีบหลับนิดหน่อยก็พร้อมลุย!",
  ui_story_5036_50361701_181_dialog_content = "โปรดตั้งตารอคอนเสิร์ตครั้งต่อไปของฉัน!",
