  ui_story_5036_50361701_183_dialog_content = "ลาก่อน!",
  ui_story_5036_50361701_184_dialog_content = "ดังนั้นแนวโน้มความรุนแรงของโกลดีจึงเป็นเพียงคำบอกเล่าเท่านั้น ฉันต้องล้างข้อมูลนั้นในบทความของฉัน",
  ui_story_5036_50361701_185_dialog_content = "เฮ้หัวหน้าบรรณาธิการ?",
  ui_story_5036_50361701_186_dialog_content = "<size=45>บรั่นดี! อะไรทำให้คุณติดต่อฉันนานขนาดนี้</size>",
  ui_story_5036_50361701_187_dialog_content = "คุณจะถูกไล่ออกถ้าคุณไม่มีสิ่งที่ยิ่งใหญ่สำหรับฉัน!",
  ui_story_5036_50361701_188_dialog_content = "ฉันได้ตรวจสอบข่าวลือที่อ้างว่าโกลดีเป็นคนรุนแรง เป็นของปลอมทั้งหมด!",
  ui_story_5036_50361701_189_dialog_content = "...",
  ui_story_5036_50361701_190_dialog_content = "นั่นคือทั้งหมดที่คุณค้นพบตลอดเวลาที่ยักษ์ใหญ่พเนจรบินอยู่เหนืออัมบราตัน!?",
  ui_story_5036_50361701_191_dialog_content = "แม้ว่าจะเป็นข่าวปลอม แต่ก็ยังดึงดูดผู้อ่านได้ใช่ไหม? หากไม่มีเรื่องซุบซิบแบบนี้ เราคงต้องปิดตัวลง",
  ui_story_5036_50361701_192_dialog_content = "ฉันผิดหวังในตัวคุณมาก บรั่นดี คุณกำลังถูกลดระดับ",
  ui_story_5036_50361701_193_dialog_content = "รอ! นั่นไม่ใช่สิ่งเดียว! ฉันมีรายละเอียดพิเศษเกี่ยวกับคอนเสิร์ต Wandering Colossus!",
