  ui_story_5036_50361701_195_dialog_content = "ในเงื่อนไขเดียว",
  ui_story_5036_50361701_196_dialog_content = "ว่าไง",
  ui_story_5036_50361701_197_dialog_content = "บทความพิเศษและบทความปัดเป่าข่าวลือเกี่ยวกับโกลดี้จะต้องอยู่ในหน้าเดียวกัน",
  ui_story_5036_50361701_198_dialog_content = "ฉันอยากให้ทุกคนรู้ว่าพวกเขาเข้าใจผิดเกี่ยวกับโกลดี้!",
  ui_story_5036_50361701_199_dialog_content = "T-นั่นมันพรีโพส...",
  ui_story_5036_50361701_200_dialog_content = "<size=45>อืม ก็ได้ สบายดี!</size>",
  ui_story_5036_50361701_201_dialog_content = "ฉันจะทำอย่างนั้น. ตอนนี้รับรายงานของคุณที่นี่",
  ui_story_5036_50361701_202_dialog_content = "ได้เลย",
