  ui_story_5036_50361701_213_dialog_content = "เพราะนั่นคือสิ่งที่เขาพูดเมื่อคราวก่อนเช่นกัน",
  ui_story_5036_50361701_214_dialog_content = "แต่จนถึงขณะนี้ยังไม่มีการเปลี่ยนแปลงในเชิงบวกในสถานะทางการเงินของเขา เขาก็ยิ่งยากจนลงเรื่อยๆ",
  ui_story_5036_50361701_215_dialog_content = "จริง. เขายังไม่ได้จ่ายค่าอาหารสัตว์มหัศจรรย์ของเดือนที่แล้ว!",
  ui_story_5036_50361701_216_dialog_content = "*สะอื้น* ฉันมันขี้แพ้ในสายตาเธอขนาดนั้นเลยเหรอ?",
  ui_story_5036_50361701_217_dialog_content = "คุณคาดหวังอะไร?",
  ui_story_5036_50361701_218_dialog_content = "ผมเศร้ามาก!",
