  ui_story_5036_50361701_221_dialog_content = "ฮือ ๆ ๆ",
  ui_story_5036_50361701_222_dialog_content = "แต่คุณพูดถูกเพียงครั้งเดียว Ouroboros อยู่บน Wandering Colossus จริงๆ",
