  ui_story_5036_50361701_229_dialog_content = "เช่นเดียวกับ Ouroboros ที่กลับไปสู่วัยเด็กในทุกวงจรชีวิต",
  ui_story_5036_50361701_230_dialog_content = "อย่างไรก็ตาม Ouroboroses มีจำนวนน้อยเกินไป หลายคนไม่เคยพบพ่อแม่ของพวกเขา",
  ui_story_5036_50361701_231_dialog_content = "ด้วยเหตุนี้ พวกเขาจึงสามารถค้นหา Colossi ที่พวกเขาแบ่งปันสายสัมพันธ์อันแน่นแฟ้นด้วยเท่านั้น",
  ui_story_5036_50361701_232_dialog_content = "การปฏิบัติต่อ Colossi เหมือนพ่อแม่ของพวกเขา...ช่างน่าเศร้า",
